import pty,os,subprocess,fcntl,termios,struct
def run(cols,args):
    m,s=pty.openpty(); fcntl.ioctl(s,termios.TIOCSWINSZ,struct.pack("HHHH",24,cols,0,0))
    p=subprocess.Popen(["/tmp/claptest/target/debug/claptest"]+args,stdin=subprocess.PIPE,stdout=s,stderr=s)
    os.close(s); out=b""
    while True:
        try:d=os.read(m,65536)
        except: break
        if not d: break
        out+=d
    p.wait(); print(out.decode())
run(120,["--help"])
