import sys; sys.path.insert(0,'/tmp/probe'); from run import *
from fractions import Fraction
def is_paired(m,p,d):
    inp=f"--- a/f\n+++ b/f\n@@ -1 +1 @@\n-{m}\n+{p}\n"
    r=run(["--paging=never","--no-gitconfig","--syntax-theme=none","--minus-style=","--plus-style=","--minus-emph-style=white red","--plus-emph-style=white green","--minus-non-emph-style=","--plus-non-emph-style=","--file-style=omit","--hunk-header-style=omit",f"--max-line-distance={d:.12f}"],inp)
    return b"41;37" in r.stdout or b"42;37" in r.stdout
def thresh(m,p):
    lo,hi=0.0,1.0
    if not is_paired(m,p,1.0): return None
    for _ in range(18):
        mid=(lo+hi)/2
        if is_paired(m,p,mid): hi=mid
        else: lo=mid
    return Fraction(hi).limit_denominator(200)
def show(m,p): print(f"{m!r}->{p!r}: {thresh(m,p)}")
# substitutions k out of n words (single letters, distinct)
for n in [4,6,8]:
  for k in range(1,n):
    mwords=[chr(97+i) for i in range(n)]; pwords=mwords.copy()
    for i in range(k): pwords[1+i]='x' if i%2==0 else 'y'
    # ensure distinct changes not duplicate letters issue use x,y,z,w
    show(' '.join(mwords),' '.join(pwords))
# Insertions of one word into n words at middle/end/begin
for n in [2,3,4,6]:
  mwords=[chr(97+i) for i in range(n)]
  for pos in [0,1,n]:
    pwords=mwords.copy(); pwords.insert(pos,'x'); show(' '.join(mwords),' '.join(pwords))
# deletions
for n in [3,4,6]:
  mwords=[chr(97+i) for i in range(n)]
  for pos in [0,1,n-1]:
    pwords=mwords.copy(); del pwords[pos]; show(' '.join(mwords),' '.join(pwords))
