use std::collections::HashMap;
use std::fmt;
use crate::csscolors::COLOR_GROUPS;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    // ANSI named 0..=7 (codes 30-37 / 40-47)
    Ansi(u8),
    Fixed(u8),
    Rgb(u8,u8,u8),
}
impl Color {
    pub fn to_rgb(&self) -> Option<(u8,u8,u8)> {
        match *self { Color::Rgb(r,g,b)=>Some((r,g,b)), Color::Fixed(n)=>Some(fixed_to_rgb(n)), Color::Ansi(n)=>Some(fixed_to_rgb(n)) }
    }
    pub fn ansi_fg(&self) -> String {
        match *self {
            Color::Ansi(n)=>format!("{}",30+n),
            Color::Fixed(n)=>format!("38;5;{}",n),
            Color::Rgb(r,g,b)=>format!("38;2;{};{};{}",r,g,b),
        }
    }
    pub fn ansi_bg(&self) -> String {
        match *self {
            Color::Ansi(n)=>format!("{}",40+n),
            Color::Fixed(n)=>format!("48;5;{}",n),
            Color::Rgb(r,g,b)=>format!("48;2;{};{};{}",r,g,b),
        }
    }
    pub fn display_name(&self) -> String {
        match *self {
            Color::Rgb(r,g,b)=>format!("\"#{:02x}{:02x}{:02x}\"",r,g,b),
            Color::Ansi(n)=>ansi_name(n).to_string(),
            Color::Fixed(n)=> {
                match n {
                    0..=7=>ansi_name(n).to_string(),
                    8=>"bright-black".to_string(),
                    9=>"brightred".to_string(),
                    10=>"bright-green".to_string(),
                    11=>"brightyellow".to_string(),
                    12=>"bright-blue".to_string(),
                    13=>"brightmagenta".to_string(),
                    14=>"bright-cyan".to_string(),
                    15=>"brightwhite".to_string(),
                    _=>format!("{}",n),
                }
            }
        }
    }
}
pub fn ansi_name(n:u8)->&'static str {
    match n {0=>"black",1=>"red",2=>"green",3=>"yellow",4=>"blue",5=>"purple",6=>"cyan",7=>"white",_=>"black"}
}
pub fn fixed_to_rgb(n:u8)->(u8,u8,u8){
    match n {
        0=>(0,0,0),1=>(128,0,0),2=>(0,128,0),3=>(128,128,0),4=>(0,0,128),5=>(128,0,128),6=>(0,128,128),7=>(192,192,192),
        8=>(128,128,128),9=>(255,0,0),10=>(0,255,0),11=>(255,255,0),12=>(0,0,255),13=>(255,0,255),14=>(0,255,255),15=>(255,255,255),
        16..=231=>{
            let n=n-16; let levels=[0u8,95,135,175,215,255];
            (levels[(n/36) as usize], levels[((n/6)%6) as usize], levels[(n%6) as usize])
        }
        _=>{let v=8+10*(n-232); (v,v,v)}
    }
}
fn srgb_to_lin(c:f64)->f64{ let c=c/255.0; if c<=0.04045 {c/12.92} else {((c+0.055)/1.055).powf(2.4)} }
fn lab(rgb:(u8,u8,u8))->(f64,f64,f64){
    let r=srgb_to_lin(rgb.0 as f64); let g=srgb_to_lin(rgb.1 as f64); let b=srgb_to_lin(rgb.2 as f64);
    let mut x=r*0.4124+g*0.3576+b*0.1805; let mut y=r*0.2126+g*0.7152+b*0.0722; let mut z=r*0.0193+g*0.1192+b*0.9505;
    x/=0.95047; z/=1.08883;
    let fx=|t:f64| if t>0.008856 {t.cbrt()} else {7.787*t+16.0/116.0};
    let (x,y,z)=(fx(x),fx(y),fx(z));
    (116.0*y-16.0,500.0*(x-y),200.0*(y-z))
}
fn lab_dist(a:(u8,u8,u8),b:(u8,u8,u8))->f64{
    let x=lab(a); let y=lab(b); ((x.0-y.0).powi(2)+(x.1-y.1).powi(2)+(x.2-y.2).powi(2)).sqrt()
}
pub fn rgb_to_fixed(rgb:(u8,u8,u8))->u8{
    let levels=[0u8,95,135,175,215,255];
    let thresholds=[36u8,115,155,195,235];
    let q=|c:u8| -> usize { let mut i=0; while i<5 && c>=thresholds[i] {i+=1;} i };
    let idx=[q(rgb.0),q(rgb.1),q(rgb.2)];
    let cube_idx=(16+36*idx[0]+6*idx[1]+idx[2]) as u8;
    let cube_rgb=(levels[idx[0]],levels[idx[1]],levels[idx[2]]);
    // gray candidate by luminance
    let lum=0.299*rgb.0 as f64+0.587*rgb.1 as f64+0.114*rgb.2 as f64;
    let mut best_i=0usize; let mut best_d=f64::MAX;
    for i in 0..24 { let v=(8+10*i) as f64; let d=(v-lum).abs(); if d<best_d {best_d=d; best_i=i;} }
    let gray_idx=(232+best_i) as u8; let gray_val=(8+10*best_i) as u8; let gray_rgb=(gray_val,gray_val,gray_val);
    // Special-case very dark colors: reference may choose cube black (16) when that is much closer in Lab than gray ramp start.
    let candidates=[(cube_idx,cube_rgb),(gray_idx,gray_rgb)];
    let mut chosen=candidates[0];
    if lab_dist(rgb,candidates[1].1) < lab_dist(rgb,candidates[0].1) { chosen=candidates[1]; }
    // If rgb exactly matches a palette colour, prefer it (lab_dist 0 for cube/gray generation usually handles it)
    chosen.0
}
pub fn parse_rgb_hex(s:&str)->Option<(u8,u8,u8)>{
    // s starts with '#'
    let h=&s[1..];
    if !h.chars().all(|c|c.is_ascii_hexdigit()) {return None;}
    match h.len() {
        3=>{
            let v:Vec<u8>=h.chars().map(|c|c.to_digit(16).unwrap() as u8).collect(); Some((v[0],v[1],v[2]))
        }
        6|8=>{
            let p=&h[0..6]; Some((u8::from_str_radix(&p[0..2],16).ok()?,u8::from_str_radix(&p[2..4],16).ok()?,u8::from_str_radix(&p[4..6],16).ok()?))
        }
        _=>None
    }
}
pub fn css_color(name:&str)->Option<(u8,u8,u8)>{
    // Build map lazily each call is okay (styles parsed at startup only; syntax themes pre-resolved)
    for (_g,items) in COLOR_GROUPS {
        for (n,hex) in *items { if *n==name { return parse_rgb_hex(hex); } }
    }
    // gray/grey aliases
    if name.contains("grey") { return css_color(&name.replace("grey","gray")); }
    if name.contains("gray") { /* CSS list uses gray spellings mostly; grey alone */
        if name=="gray" { return Some((128,128,128)); }
    }
    if name=="grey" { return Some((128,128,128)); }
    None
}

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum Fg { Normal, Syntax, Color(Color) }
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum Bg { Normal, Color(Color) }

#[derive(Clone,Debug,PartialEq)]
pub struct Style {
    pub fg: Fg,
    pub bg: Bg,
    pub bold: bool,
    pub dim: bool,
    pub italic: bool,
    pub underline: bool,
    pub blink: bool,
    pub reverse: bool,
    pub hidden: bool,
    pub strike: bool,
    pub is_omit: bool,
    pub is_raw: bool,
    pub has_file: bool,
    pub has_line_number: bool,
    pub has_box: bool,
    pub has_ol: bool,
    pub has_none: bool,
    // Original string (lowercased, quotes removed) for some error/identity checks
    pub orig: String,
}
impl Default for Style {
    fn default()->Self{ Style{fg:Fg::Normal,bg:Bg::Normal,bold:false,dim:false,italic:false,underline:false,blink:false,reverse:false,hidden:false,strike:false,is_omit:false,is_raw:false,has_file:false,has_line_number:false,has_box:false,has_ol:false,has_none:false,orig:String::new()} }
}
impl Style {
    pub fn new_empty()->Self{Self::default()}
    pub fn is_plain(&self)->bool{
        self.fg==Fg::Normal && self.bg==Bg::Normal && !self.bold && !self.dim && !self.italic && !self.underline && !self.blink && !self.reverse && !self.hidden && !self.strike && !self.is_raw
    }
    pub fn ansi_codes(&self)->Vec<String>{
        // Order observed in reference (ansi_term): attributes in numeric code order? Check examples:
        // bold red bg: "1;48;5;52;31" -> bold(1), background, foreground
        // reverse purple: "7;35"; blink etc all: "2;3;4;5;7;8;9" then colors
        // plus emph syntax with bg and syntax fg resolved separately by painter.
        // For a concrete Style (fg is Color/Normal), produce codes in order: attrs sorted by code [1,2,3,4,5,7,8,9], bg, fg ??? But observed:
        // red (fg only) "31"; red blue(bg) "44;31" bg before fg; black white bold italic: "1;3;47;30"
        // syntax segment painting in plus lines: "48;5;28;38;5;141" bg before fg.
        // However foreground-only from syntax painter is just fg.
        let mut codes:Vec<String>=Vec::new();
        if self.bold {codes.push("1".into());}
        if self.dim {codes.push("2".into());}
        if self.italic {codes.push("3".into());}
        if self.underline {codes.push("4".into());}
        if self.blink {codes.push("5".into());}
        if self.reverse {codes.push("7".into());}
        if self.hidden {codes.push("8".into());}
        if self.strike {codes.push("9".into());}
        if let Bg::Color(c)=self.bg {codes.push(c.ansi_bg());}
        if let Fg::Color(c)=self.fg {codes.push(c.ansi_fg());}
        codes
    }
    pub fn paint(&self, text:&str)->String{
        if text.is_empty() {
            // Painting empty text in reference: often still emits code + reset in some places, but caller decides.
            // Default paint used by us: if style has any codes, emit them even for empty? Caller handles.
        }
        let codes=self.ansi_codes();
        if codes.is_empty() { return text.to_string(); }
        format!("\x1b[{}m{}\x1b[0m",codes.join(";"),text)
    }
    // Paint but like ansi_term prefix/suffix; reset is 0m
    pub fn prefix(&self)->String{
        let codes=self.ansi_codes(); if codes.is_empty() {String::new()} else {format!("\x1b[{}m",codes.join(";"))}
    }
}
impl fmt::Display for Style {
    fn fmt(&self,f:&mut fmt::Formatter)->fmt::Result{
        // Match reference Display used in --show-config.
        // Attributed order in display text: blink, bold, dim, italic, reverse, strike, ul  (alphabetical-ish, hidden not printed)
        // Actually observed: "blink dim italic reverse strike ul" for all attrs (bold absent there), "bold ul red", "bold italic black white", "reverse red".
        // Order seems: blink, bold, dim, italic, reverse, strike, ul
        let mut parts:Vec<String>=Vec::new();
        if self.is_omit {parts.push("omit".into());}
        if self.blink {parts.push("blink".into());}
        if self.bold {parts.push("bold".into());}
        if self.dim {parts.push("dim".into());}
        if self.italic {parts.push("italic".into());}
        if self.reverse {parts.push("reverse".into());}
        if self.strike {parts.push("strike".into());}
        if self.underline {parts.push("ul".into());}
        if self.is_raw {
            parts.push("raw".into());
            // If raw and no other??? Display observed: "raw" alone; "bold raw"; with a colour also just ... "raw" (colour suppressed)
            // But for commit-style raw, display = "raw".
            return write!(f,"{}",parts.join(" "));
        }
        match self.fg {
            Fg::Syntax=>parts.push("syntax".into()),
            Fg::Color(c)=>parts.push(c.display_name()),
            Fg::Normal=>{
                // Only push "normal" if no bg colour? Observations:
                // style with only attrs -> "bold normal", "ul normal"
                // fg normal bg 52 -> "normal 52"
                // fg normal bg normal -> "normal"
                parts.push("normal".into());
            }
        }
        if let Bg::Color(c)=self.bg { parts.push(c.display_name()); }
        // Special: if fg is Syntax and bg is Normal, display is just "syntax" (no normal) - covered.
        // If fg is Color and bg Normal, just colour name.
        write!(f,"{}",parts.join(" "))
    }
}

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum ColorTokenKind { FgBgColor, }
#[derive(Clone,Debug)]
enum ParsedColor { Color(Color), Normal, Syntax, Auto }

fn color_from_token(tok:&str, true_color:bool)->Option<ParsedColor>{
    match tok {
        "normal"=>return Some(ParsedColor::Normal),
        "syntax"=>return Some(ParsedColor::Syntax),
        "auto"=>return Some(ParsedColor::Auto),
        _=>{}
    }
    // ANSI names
    let ansi_names:[(&str,u8);_]=[("black",0),("red",1),("green",2),("yellow",3),("blue",4),("magenta",5),("purple",5),("cyan",6),("white",7)];
    for (n,v) in ansi_names { if tok==n { return Some(ParsedColor::Color(Color::Ansi(v))); } }
    // bright
    let bright_base=tok.strip_prefix("bright").map(|s|s.strip_prefix('-').unwrap_or(s));
    if let Some(base)=bright_base {
        for (n,v) in ansi_names { if base==n { return Some(ParsedColor::Color(Color::Fixed(v+8))); } }
    }
    // numeric
    if !tok.is_empty() && tok.chars().all(|c|c.is_ascii_digit()) {
        if let Ok(n)=tok.parse::<u8>() {
            return Some(ParsedColor::Color(if n<=7 {Color::Ansi(n)} else {Color::Fixed(n)}));
        } else { return None; }
    }
    // hex
    if tok.starts_with('#') {
        if let Some(rgb)=parse_rgb_hex(tok) {
            return Some(ParsedColor::Color(if true_color {Color::Rgb(rgb.0,rgb.1,rgb.2)} else {Color::Fixed(rgb_to_fixed(rgb))}));
        } else { return None; }
    }
    // CSS
    if let Some(rgb)=css_color(tok) {
        return Some(ParsedColor::Color(if true_color {Color::Rgb(rgb.0,rgb.1,rgb.2)} else {Color::Fixed(rgb_to_fixed(rgb))}));
    }
    None
}

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum StyleContext { Normal, Decoration, FileLike }

pub fn parse_style(s:&str, true_color:bool, context:StyleContext) -> Result<Style,String> {
    let cleaned: String = s.chars().filter(|c| *c!='"' && *c!='\'').collect();
    let lower=cleaned.to_lowercase();
    let mut style=Style::default();
    style.orig=lower.clone();
    let mut colors:Vec<ParsedColor>=Vec::new();
    for tok in lower.split_whitespace() {
        match tok {
            "bold"=>style.bold=true,
            "dim"=>style.dim=true,
            "italic"=>style.italic=true,
            "ul"|"underline"=>style.underline=true,
            "blink"=>style.blink=true,
            "reverse"=>style.reverse=true,
            "hidden"=>style.hidden=true,
            "strike"=>style.strike=true,
            "omit"=>style.is_omit=true,
            "raw"=>{
                if context==StyleContext::Decoration { return Err("'raw' may not be used in a decoration style.\n".to_string()); }
                style.is_raw=true;
            },
            "file"=>style.has_file=true,
            "line-number"=>style.has_line_number=true,
            "box"=>{
                if context==StyleContext::Normal { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_box=true;
            },
            "ol"=>{
                if context!=StyleContext::Decoration { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_ol=true;
            },
            "none"=>{
                if context==StyleContext::Normal { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_none=true;
            },
            "syntax" if context==StyleContext::Decoration=>{
                // syntax as a colour token in decoration: specific error before colour handling (observed for --*-decoration-style=syntax)
                return Err("'syntax' may not be used in a decoration style.\n".to_string());
            },
            _=>{
                if let Some(c)=color_from_token(tok,true_color) {
                    colors.push(c);
                } else {
                    return Err(format!("Invalid color or style attribute: {}\n",tok));
                }
            }
        }
    }
    if colors.len()>2 {
        return Err(format!("Invalid style string: {}. See the STYLES section of delta --help.\n", lower.trim()));
    }
    // foreground
    // Keep Auto as a marker encoded temporarily: caller resolves auto using defaults. We encode Auto fg as Normal here and handle in resolve via orig? Better: return style with fg/bg still needing resolution.
    // Instead parse_style is used with an optional default resolution in config.rs via parse_style_with_defaults. Here, treat Auto as Normal for fg, and Normal for bg; config resolution re-parses with defaults.
    // To preserve Auto information, we store it in a separate manner by caller: see StyleParse below.
    let _=colors;
    // This function is not used directly for auto-containing styles except validation; actual resolution in config uses parse_style_full.
    let full=parse_style_full(s,true_color,context,None,None)?;
    Ok(full)
}

pub struct AutoColors { pub fg: Option<Fg>, pub bg: Option<Bg> }
// Parse and resolve 'auto' tokens: first auto -> fg default, second auto -> bg default. If default is None, auto fg -> Normal, auto bg -> Normal.
// IMPORTANT reference semantics for defaults (from show-config probes):
// "normal auto" for minus-style: fg normal, bg auto -> auto resolved to minus bg colour.
// "syntax auto" for plus: bg auto -> plus bg.
// "auto" alone for minus-style (fg position): show-config displayed "normal" (auto fg defaults to the style's default fg, which for minus is normal)
// "auto auto" -> normal + bg
// "auto normal" -> normal (fg auto->default normal, bg normal)
// For zero-style "syntax normal": no auto.
// For whitespace-error-style default in help is "auto auto" but actual default resolved from git config color.diff.whitespace or "magenta reverse" (see config).
pub fn parse_style_full(s:&str, true_color:bool, context:StyleContext, default_fg: Option<Fg>, default_bg: Option<Bg>) -> Result<Style,String> {
    let cleaned: String = s.chars().filter(|c| *c!='"' && *c!='\'').collect();
    let lower=cleaned.to_lowercase();
    let mut style=Style::default();
    style.orig=lower.clone();
    let mut colors:Vec<ParsedColor>=Vec::new();
    for tok in lower.split_whitespace() {
        match tok {
            "bold"=>style.bold=true,
            "dim"=>style.dim=true,
            "italic"=>style.italic=true,
            "ul"|"underline"=>style.underline=true,
            "blink"=>style.blink=true,
            "reverse"=>style.reverse=true,
            "hidden"=>style.hidden=true,
            "strike"=>style.strike=true,
            "omit"=>style.is_omit=true,
            "raw"=>{
                if context==StyleContext::Decoration { return Err("'raw' may not be used in a decoration style.\n".to_string()); }
                style.is_raw=true;
            },
            "file"=>style.has_file=true,
            "line-number"=>style.has_line_number=true,
            "box"=>{
                if context==StyleContext::Normal { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_box=true;
            },
            "ol"=>{
                if context!=StyleContext::Decoration { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_ol=true;
            },
            "none"=>{
                if context==StyleContext::Normal { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_none=true;
            },
            "syntax" if context==StyleContext::Decoration=>{
                return Err("'syntax' may not be used in a decoration style.\n".to_string());
            },
            _=>{
                if let Some(c)=color_from_token(tok,true_color) {
                    colors.push(c);
                } else {
                    return Err(format!("Invalid color or style attribute: {}\n",tok));
                }
            }
        }
    }
    if colors.len()>2 {
        return Err(format!("Invalid style string: {}. See the STYLES section of delta --help.\n", s.trim_matches(|c| c=='"'||c=='\'' ).trim().to_string().to_lowercase()));
        // NOTE reference error uses the original style string as passed (lowercasing? Input probe was lower). We'll refine: caller may need exact.
    }
    if colors.len()>=1 {
        match colors[0] {
            ParsedColor::Color(c)=>style.fg=Fg::Color(c),
            ParsedColor::Normal=>style.fg=Fg::Normal,
            ParsedColor::Syntax=>style.fg=Fg::Syntax,
            ParsedColor::Auto=>style.fg=default_fg.unwrap_or(Fg::Normal),
        }
    }
    if colors.len()>=2 {
        match colors[1] {
            ParsedColor::Color(c)=>style.bg=Bg::Color(c),
            ParsedColor::Normal=>style.bg=Bg::Normal,
            ParsedColor::Syntax=>{ return Err("You have used the special color 'syntax' as a background color (second color in a style string). It may only be used as a foreground color (first color in a style string).\n".to_string()); },
            ParsedColor::Auto=>style.bg=default_bg.unwrap_or(Bg::Normal),
        }
    }
    Ok(style)
}
RS
