    for i in 0..24 { let v=(8+10*i) as f64; let d=(v-lum).abs(); if d<best_d {best_d=d; best_i=i;} }
    let gray_idx=(232+best_i) as u8; let gray_val=(8+10*best_i) as u8; let gray_rgb=(gray_val,gray_val,gray_val);
    // Special-case very dark colors: reference may choose cube black (16) when that is much closer in Lab than gray ramp start.
    let candidates=[(cube_idx,cube_rgb),(gray_idx,gray_rgb)];
    let mut chosen=candidates[0];
    if lab_dist(rgb,candidates[1].1) < lab_dist(rgb,candidates[0].1) { chosen=candidates[1]; }
    // If rgb exactly matches a palette colour, prefer it (lab_dist 0 for cube/gray generation usually handles it)
    chosen.0
}
pub fn parse_rgb_hex(s:&str)->Option<(u8,u8,u8)>{
    // s starts with '#'
    let h=&s[1..];
    if !h.chars().all(|c|c.is_ascii_hexdigit()) {return None;}
    match h.len() {
        3=>{
            let v:Vec<u8>=h.chars().map(|c|c.to_digit(16).unwrap() as u8).collect(); Some((v[0],v[1],v[2]))
        }
        6|8=>{
            let p=&h[0..6]; Some((u8::from_str_radix(&p[0..2],16).ok()?,u8::from_str_radix(&p[2..4],16).ok()?,u8::from_str_radix(&p[4..6],16).ok()?))
