        _=>None
    }
}
pub fn css_color(name:&str)->Option<(u8,u8,u8)>{
    // Build map lazily each call is okay (styles parsed at startup only; syntax themes pre-resolved)
    for (_g,items) in COLOR_GROUPS {
        for (n,hex) in *items { if *n==name { return parse_rgb_hex(hex); } }
    }
    // gray/grey aliases
    if name.contains("grey") { return css_color(&name.replace("grey","gray")); }
    if name.contains("gray") { /* CSS list uses gray spellings mostly; grey alone */
        if name=="gray" { return Some((128,128,128)); }
    }
    if name=="grey" { return Some((128,128,128)); }
    None
}

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum Fg { Normal, Syntax, Color(Color) }
