impl Style {
    pub fn new_empty()->Self{Self::default()}
    pub fn is_plain(&self)->bool{
        self.fg==Fg::Normal && self.bg==Bg::Normal && !self.bold && !self.dim && !self.italic && !self.underline && !self.blink && !self.reverse && !self.hidden && !self.strike && !self.is_raw
