    pub fn ansi_codes(&self)->Vec<String>{
        // Order observed in reference (ansi_term): attributes in numeric code order? Check examples:
        // bold red bg: "1;48;5;52;31" -> bold(1), background, foreground
        // reverse purple: "7;35"; blink etc all: "2;3;4;5;7;8;9" then colors
        // plus emph syntax with bg and syntax fg resolved separately by painter.
        // For a concrete Style (fg is Color/Normal), produce codes in order: attrs sorted by code [1,2,3,4,5,7,8,9], bg, fg ??? But observed:
        // red (fg only) "31"; red blue(bg) "44;31" bg before fg; black white bold italic: "1;3;47;30"
        // syntax segment painting in plus lines: "48;5;28;38;5;141" bg before fg.
        // However foreground-only from syntax painter is just fg.
        let mut codes:Vec<String>=Vec::new();
        if self.bold {codes.push("1".into());}
        if self.dim {codes.push("2".into());}
        if self.italic {codes.push("3".into());}
        if self.underline {codes.push("4".into());}
        if self.blink {codes.push("5".into());}
        if self.reverse {codes.push("7".into());}
        if self.hidden {codes.push("8".into());}
        if self.strike {codes.push("9".into());}
        if let Bg::Color(c)=self.bg {codes.push(c.ansi_bg());}
