        // Actually observed: "blink dim italic reverse strike ul" for all attrs (bold absent there), "bold ul red", "bold italic black white", "reverse red".
        // Order seems: blink, bold, dim, italic, reverse, strike, ul
        let mut parts:Vec<String>=Vec::new();
        if self.is_omit {parts.push("omit".into());}
        if self.blink {parts.push("blink".into());}
        if self.bold {parts.push("bold".into());}
        if self.dim {parts.push("dim".into());}
        if self.italic {parts.push("italic".into());}
        if self.reverse {parts.push("reverse".into());}
        if self.strike {parts.push("strike".into());}
        if self.underline {parts.push("ul".into());}
        if self.is_raw {
            parts.push("raw".into());
            // If raw and no other??? Display observed: "raw" alone; "bold raw"; with a colour also just ... "raw" (colour suppressed)
            // But for commit-style raw, display = "raw".
            return write!(f,"{}",parts.join(" "));
        }
        match self.fg {
            Fg::Syntax=>parts.push("syntax".into()),
            Fg::Color(c)=>parts.push(c.display_name()),
