        // If fg is Color and bg Normal, just colour name.
        write!(f,"{}",parts.join(" "))
    }
}

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum ColorTokenKind { FgBgColor, }
#[derive(Clone,Debug)]
enum ParsedColor { Color(Color), Normal, Syntax, Auto }

fn color_from_token(tok:&str, true_color:bool)->Option<ParsedColor>{
    match tok {
        "normal"=>return Some(ParsedColor::Normal),
        "syntax"=>return Some(ParsedColor::Syntax),
        "auto"=>return Some(ParsedColor::Auto),
        _=>{}
    }
    // ANSI names
    let ansi_names:[(&str,u8);_]=[("black",0),("red",1),("green",2),("yellow",3),("blue",4),("magenta",5),("purple",5),("cyan",6),("white",7)];
    for (n,v) in ansi_names { if tok==n { return Some(ParsedColor::Color(Color::Ansi(v))); } }
    // bright
    let bright_base=tok.strip_prefix("bright").map(|s|s.strip_prefix('-').unwrap_or(s));
    if let Some(base)=bright_base {
        for (n,v) in ansi_names { if base==n { return Some(ParsedColor::Color(Color::Fixed(v+8))); } }
    }
    // numeric
    if !tok.is_empty() && tok.chars().all(|c|c.is_ascii_digit()) {
        if let Ok(n)=tok.parse::<u8>() {
            return Some(ParsedColor::Color(if n<=7 {Color::Ansi(n)} else {Color::Fixed(n)}));
        } else { return None; }
    }
    // hex
    if tok.starts_with('#') {
        if let Some(rgb)=parse_rgb_hex(tok) {
            return Some(ParsedColor::Color(if true_color {Color::Rgb(rgb.0,rgb.1,rgb.2)} else {Color::Fixed(rgb_to_fixed(rgb))}));
        } else { return None; }
    }
    // CSS
    if let Some(rgb)=css_color(tok) {
        return Some(ParsedColor::Color(if true_color {Color::Rgb(rgb.0,rgb.1,rgb.2)} else {Color::Fixed(rgb_to_fixed(rgb))}));
    }
    None
}

#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum StyleContext { Normal, Decoration, FileLike }

pub fn parse_style(s:&str, true_color:bool, context:StyleContext) -> Result<Style,String> {
    let cleaned: String = s.chars().filter(|c| *c!='"' && *c!='\'').collect();
    let lower=cleaned.to_lowercase();
    let mut style=Style::default();
    style.orig=lower.clone();
    let mut colors:Vec<ParsedColor>=Vec::new();
    for tok in lower.split_whitespace() {
        match tok {
            "bold"=>style.bold=true,
            "dim"=>style.dim=true,
            "italic"=>style.italic=true,
            "ul"|"underline"=>style.underline=true,
            "blink"=>style.blink=true,
            "reverse"=>style.reverse=true,
            "hidden"=>style.hidden=true,
            "strike"=>style.strike=true,
            "omit"=>style.is_omit=true,
            "raw"=>{
                if context==StyleContext::Decoration { return Err("'raw' may not be used in a decoration style.\n".to_string()); }
                style.is_raw=true;
            },
            "file"=>style.has_file=true,
            "line-number"=>style.has_line_number=true,
            "box"=>{
                if context==StyleContext::Normal { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_box=true;
            },
            "ol"=>{
                if context!=StyleContext::Decoration { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_ol=true;
            },
            "none"=>{
                if context==StyleContext::Normal { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_none=true;
            },
            "syntax" if context==StyleContext::Decoration=>{
                // syntax as a colour token in decoration: specific error before colour handling (observed for --*-decoration-style=syntax)
                return Err("'syntax' may not be used in a decoration style.\n".to_string());
            },
            _=>{
                if let Some(c)=color_from_token(tok,true_color) {
                    colors.push(c);
                } else {
                    return Err(format!("Invalid color or style attribute: {}\n",tok));
                }
            }
        }
    }
    if colors.len()>2 {
        return Err(format!("Invalid style string: {}. See the STYLES section of delta --help.\n", lower.trim()));
    }
    // foreground
    // Keep Auto as a marker encoded temporarily: caller resolves auto using defaults. We encode Auto fg as Normal here and handle in resolve via orig? Better: return style with fg/bg still needing resolution.
    // Instead parse_style is used with an optional default resolution in config.rs via parse_style_with_defaults. Here, treat Auto as Normal for fg, and Normal for bg; config resolution re-parses with defaults.
    // To preserve Auto information, we store it in a separate manner by caller: see StyleParse below.
    let _=colors;
    // This function is not used directly for auto-containing styles except validation; actual resolution in config uses parse_style_full.
    let full=parse_style_full(s,true_color,context,None,None)?;
    Ok(full)
}

pub struct AutoColors { pub fg: Option<Fg>, pub bg: Option<Bg> }
// Parse and resolve 'auto' tokens: first auto -> fg default, second auto -> bg default. If default is None, auto fg -> Normal, auto bg -> Normal.
// IMPORTANT reference semantics for defaults (from show-config probes):
// "normal auto" for minus-style: fg normal, bg auto -> auto resolved to minus bg colour.
// "syntax auto" for plus: bg auto -> plus bg.
// "auto" alone for minus-style (fg position): show-config displayed "normal" (auto fg defaults to the style's default fg, which for minus is normal)
// "auto auto" -> normal + bg
// "auto normal" -> normal (fg auto->default normal, bg normal)
// For zero-style "syntax normal": no auto.
// For whitespace-error-style default in help is "auto auto" but actual default resolved from git config color.diff.whitespace or "magenta reverse" (see config).
pub fn parse_style_full(s:&str, true_color:bool, context:StyleContext, default_fg: Option<Fg>, default_bg: Option<Bg>) -> Result<Style,String> {
    let cleaned: String = s.chars().filter(|c| *c!='"' && *c!='\'').collect();
    let lower=cleaned.to_lowercase();
    let mut style=Style::default();
    style.orig=lower.clone();
    let mut colors:Vec<ParsedColor>=Vec::new();
    for tok in lower.split_whitespace() {
        match tok {
            "bold"=>style.bold=true,
            "dim"=>style.dim=true,
            "italic"=>style.italic=true,
            "ul"|"underline"=>style.underline=true,
            "blink"=>style.blink=true,
            "reverse"=>style.reverse=true,
            "hidden"=>style.hidden=true,
            "strike"=>style.strike=true,
            "omit"=>style.is_omit=true,
            "raw"=>{
                if context==StyleContext::Decoration { return Err("'raw' may not be used in a decoration style.\n".to_string()); }
                style.is_raw=true;
            },
            "file"=>style.has_file=true,
            "line-number"=>style.has_line_number=true,
            "box"=>{
                if context==StyleContext::Normal { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_box=true;
            },
            "ol"=>{
                if context!=StyleContext::Decoration { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_ol=true;
            },
            "none"=>{
                if context==StyleContext::Normal { return Err(format!("Invalid color or style attribute: {}\n",tok)); }
                style.has_none=true;
            },
            "syntax" if context==StyleContext::Decoration=>{
                return Err("'syntax' may not be used in a decoration style.\n".to_string());
            },
            _=>{
                if let Some(c)=color_from_token(tok,true_color) {
                    colors.push(c);
                } else {
                    return Err(format!("Invalid color or style attribute: {}\n",tok));
                }
            }
        }
    }
    if colors.len()>2 {
        return Err(format!("Invalid style string: {}. See the STYLES section of delta --help.\n", s.trim_matches(|c| c=='"'||c=='\'' ).trim().to_string().to_lowercase()));
        // NOTE reference error uses the original style string as passed (lowercasing? Input probe was lower). We'll refine: caller may need exact.
    }
    if colors.len()>=1 {
        match colors[0] {
            ParsedColor::Color(c)=>style.fg=Fg::Color(c),
            ParsedColor::Normal=>style.fg=Fg::Normal,
            ParsedColor::Syntax=>style.fg=Fg::Syntax,
            ParsedColor::Auto=>style.fg=default_fg.unwrap_or(Fg::Normal),
        }
    }
    if colors.len()>=2 {
        match colors[1] {
            ParsedColor::Color(c)=>style.bg=Bg::Color(c),
            ParsedColor::Normal=>style.bg=Bg::Normal,
            ParsedColor::Syntax=>{ return Err("You have used the special color 'syntax' as a background color (second color in a style string). It may only be used as a foreground color (first color in a style string).\n".to_string()); },
            ParsedColor::Auto=>style.bg=default_bg.unwrap_or(Bg::Normal),
        }
    }
    Ok(style)
}
RS
"}

