// Parse SGR codes into styles. If downgrade_rgb, RGB colours become Fixed.
pub fn parse_sections(s:&str, downgrade_rgb:bool)->Vec<Section>{
    let mut sections:Vec<Section>=Vec::new();
    let mut cur=Style::default();
    let mut text=String::new();
    let bytes=s.as_bytes();
    let mut i=0usize;
    let chars:Vec<(usize,char)>=s.char_indices().collect();
    // Easier operate on chars with index into string for escapes (ASCII)
    let mut it=s.chars().peekable();
    while let Some(ch)=it.next() {
        if ch=='\x1b' {
            // flush text
            if !text.is_empty() { sections.push(Section{text:std::mem::take(&mut text),style:cur.clone()}); }
            match it.peek() {
                Some('[')=>{ it.next();
                    let mut params=String::new();
                    let mut final_ch=' ';
                    while let Some(&c)=it.peek() {
                        it.next();
                        if ('@'..='~').contains(&c) { final_ch=c; break; } else { params.push(c); }
                    }
                    if final_ch=='m' { apply_sgr(&mut cur,&params,downgrade_rgb); }
                    // other CSI (K etc) ignored; but some (K) in raw passthrough lines are preserved by Unknown state because we don't re-emit parsed line there.
                }
                Some(']')=>{ it.next();
                    // OSC until BEL or ESC \
                    let mut prev='\0';
                    while let Some(c)=it.next() {
                        if c=='\x07' {break;}
                        if prev=='\x1b' && c=='\\' {break;}
                        prev=c;
                    }
                }
                Some(_)=>{
                    // Two-char escape, consume one
                    let _=it.next();
                }
                None=>{}
            }
        } else {
            text.push(ch);
        }
    }
