        sections.push(Section{text,style:cur});
    }
    // Merge adjacent same-style sections
    let mut out:Vec<Section>=Vec::new();
    for sec in sections {
        if sec.text.is_empty() { continue; }
        if let Some(last)=out.last_mut() {
            if last.style==sec.style { last.text.push_str(&sec.text); continue; }
        }
        out.push(sec);
    }
    if out.is_empty() { out.push(Section{text:String::new(),style:Style::default()}); }
    out
}
fn apply_sgr(style:&mut Style, params:&str, downgrade_rgb:bool){
    if params.is_empty() { *style=Style::default(); return; }
    // Some codes use ':' as separator for 38:5 etc. normalize to ';'
    let normalized=params.replace(':',";");
    let parts:Vec<&str>=normalized.split(';').collect();
    let mut idx=0;
    while idx<parts.len() {
        let p=parts[idx];
        let code: i64 = if p.is_empty() {0} else {p.parse().unwrap_or(0)};
        match code {
            0=>{*style=Style::default();}
            1=>style.bold=true,
            2=>style.dim=true,
            3=>style.italic=true,
            4=>style.underline=true,
            5=>style.blink=true,
            7=>style.reverse=true,
            8=>style.hidden=true,
            9=>style.strike=true,
            22=>{style.bold=false; style.dim=false;}
            23=>style.italic=false,
            24=>style.underline=false,
            25=>style.blink=false,
            27=>style.reverse=false,
            28=>style.hidden=false,
            29=>style.strike=false,
            30..=37=>style.fg=Fg::Color(Color::Ansi((code-30) as u8)),
            39=>style.fg=Fg::Normal,
            40..=47=>style.bg=Bg::Color(Color::Ansi((code-40) as u8)),
            49=>style.bg=Bg::Normal,
            90..=97=>style.fg=Fg::Color(Color::Fixed((code-90+8) as u8)),
            100..=107=>style.bg=Bg::Color(Color::Fixed((code-100+8) as u8)),
            38|48=>{
                let is_fg=code==38;
                if idx+1<parts.len() {
                    if parts[idx+1]=="5" && idx+2<parts.len() {
                        if let Ok(n)=parts[idx+2].parse::<u8>() {
                            let col=Color::Fixed(n);
                            if is_fg {style.fg=Fg::Color(col);} else {style.bg=Bg::Color(col);}
                        }
                        idx+=2;
                    } else if parts[idx+1]=="2" && idx+4<parts.len() {
                        let r=parts[idx+2].parse::<u8>().unwrap_or(0); let g=parts[idx+3].parse::<u8>().unwrap_or(0); let b=parts[idx+4].parse::<u8>().unwrap_or(0);
                        let col=if downgrade_rgb {Color::Fixed(rgb_to_fixed((r,g,b)))} else {Color::Rgb(r,g,b)};
                        if is_fg {style.fg=Fg::Color(col);} else {style.bg=Bg::Color(col);}
                        idx+=4;
                    }
                }
            }
            _=>{}
        }
        idx+=1;
    }
}
// Convert an SGR style from raw input to delta Style-string-like style for comparisons with map-styles keys.
// Reference mapping likely compares Style structs parsed from a style string (with RGB downgrade etc). Our Style from ANSI should be comparable.
pub fn style_is_plain(st:&Style)->bool{ st.is_plain() }
