pub fn build_command() -> Command {
    let mut cmd = Command::new("delta")
        .version("0.18.2")
        .about("A viewer for git and diff output");
    for spec in SPECS {
        let mut arg = Arg::new(spec.long).long(spec.long);
        if let Some(s)=spec.short { arg=arg.short(s); }
        if let Some(vn)=spec.value_name {
            arg=arg.value_name(vn);
            match spec.long {
                "detect-dark-light"=>{ arg=arg.value_parser(PossibleValuesParser::new(["auto","always","never"])); }
                "generate-completion"=>{ arg=arg.value_parser(PossibleValuesParser::new(["bash","elvish","fish","powershell","zsh"])); }
                "grep-output-type"=>{ arg=arg.value_parser(PossibleValuesParser::new(["ripgrep","classic"])); }
                "inspect-raw-lines"=>{ arg=arg.value_parser(PossibleValuesParser::new(["true","false"])); }
                "line-fill-method"=>{ arg=arg.value_parser(PossibleValuesParser::new(["ansi","spaces"])); }
                "paging"|"true-color"|"24-bit-color"=>{ arg=arg.value_parser(PossibleValuesParser::new(["auto","always","never"])); }
                "diff-stat-align-width"|"line-buffer-size"|"max-syntax-highlighting-length"|"max-line-length"|"tabs"=>{
                    arg=arg.value_parser(clap::value_parser!(usize));
                }
                "max-line-distance"=>{ arg=arg.value_parser(clap::value_parser!(f64)); }
                _=>{}
            }
        } else {
            arg=arg.action(ArgAction::SetTrue);
        }
        cmd=cmd.arg(arg);
    }
    cmd=cmd.arg(Arg::new("MINUS_FILE"));
    cmd=cmd.arg(Arg::new("PLUS_FILE"));
    cmd
}

#[derive(Default,Clone,Debug)]
pub struct RawOpts {
    pub values: HashMap<String,String>,
    pub flags: HashSet<String>,
    pub present: HashSet<String>,
    pub minus_file: Option<String>,
    pub plus_file: Option<String>,
}
impl RawOpts {
    pub fn from_matches(m:&clap::ArgMatches)->Self{
        let mut r=RawOpts::default();
        for spec in SPECS {
            let src=m.value_source(spec.long);
            let present = matches!(src, Some(clap::parser::ValueSource::CommandLine));
            if present { r.present.insert(spec.long.to_string()); }
            if spec.value_name.is_none() {
                if m.get_flag(spec.long) { r.flags.insert(spec.long.to_string()); }
            } else {
                match spec.long {
                    "diff-stat-align-width"|"line-buffer-size"|"max-syntax-highlighting-length"|"max-line-length"|"tabs"=>{
                        if let Some(v)=m.get_one::<usize>(spec.long) { r.values.insert(spec.long.to_string(), v.to_string()); }
                    }
                    "max-line-distance"=>{
                        if let Some(v)=m.get_one::<f64>(spec.long) { r.values.insert(spec.long.to_string(), format!("{}",v)); }
                    }
                    _=>{
                        if let Some(v)=m.get_one::<String>(spec.long) { r.values.insert(spec.long.to_string(), v.clone()); }
                    }
                }
            }
        }
        r.minus_file=m.get_one::<String>("MINUS_FILE").cloned();
        r.plus_file=m.get_one::<String>("PLUS_FILE").cloned();
        r
    }
    pub fn flag(&self,name:&str)->bool{ self.flags.contains(name) }
    pub fn get(&self,name:&str)->Option<&str>{ self.values.get(name).map(|s|s.as_str()) }
    pub fn present(&self,name:&str)->bool{ self.present.contains(name) }
}

pub fn huge_usage(bin:&str)->String{
    // Match observed clap rendering for "similar argument exists" for non-help/version options.
    let mut parts:Vec<String>=Vec::new();
    for spec in SPECS {
        if let Some(vn)=spec.value_name { parts.push(format!("--{} <{}>",spec.long,vn)); } else { parts.push(format!("--{}",spec.long)); }
    }
    parts.push("MINUS_FILE".to_string());
    parts.push("PLUS_FILE".to_string());
    format!("\x1b[1m\x1b[4mUsage:\x1b[0m \x1b[1m{}\x1b[0m <{}>", bin, parts.join("|"))
}
RS
"}

