use std::collections::HashMap;
use std::path::{Path, PathBuf};

#[derive(Clone,Debug,PartialEq,Eq,Hash)]
pub struct Key { pub section:String, pub subsection:Option<String>, pub name:String }
#[derive(Clone,Debug,Default)]
pub struct GitConfig {
    pub entries: HashMap<Key, Option<String>>,
    // Order of feature section names as seen (for show-themes listing?) Keep insertion order list.
    pub delta_feature_names_in_order: Vec<String>,
}
impl GitConfig {
    pub fn get(&self, section:&str, subsection:Option<&str>, name:&str)->Option<&Option<String>>{
        self.entries.get(&Key{section:section.to_lowercase(),subsection:subsection.map(|s|s.to_string()),name:name.to_lowercase()})
    }
    pub fn get_string(&self, section:&str, subsection:Option<&str>, name:&str)->Option<String>{
        match self.get(section,subsection,name) {
            Some(Some(v))=>Some(v.clone()),
            Some(None)=>Some("true".to_string()), // key without value: git represents as boolean true; string getter in libgit2 returns "true"? Config code for string options unlikely key-alone.
            None=>None,
        }
    }
    pub fn feature_names(&self)->Vec<String>{
        // All subsection names under [delta "..."], sorted? Show-themes order - check later. Maintain order of first appearance among files sorted by ... we'll return collected order unique.
        self.delta_feature_names_in_order.clone()
    }
}

pub fn load(raw: &crate::opts::RawOpts) -> GitConfig {
    if raw.flag("no-gitconfig") { return GitConfig::default(); }
    let mut files:Vec<PathBuf>=Vec::new();
    if let Some(cfg)=raw.get("config") {
        if !cfg.is_empty() { files.push(PathBuf::from(cfg)); return load_files(&files); }
    }
    // system
    let nosystem = std::env::var_os("GIT_CONFIG_NOSYSTEM").is_some();
    if !nosystem { files.push(PathBuf::from("/etc/gitconfig")); }
    if let Some(home)=home_dir() {
        let xdg = std::env::var_os("XDG_CONFIG_HOME").map(PathBuf::from).unwrap_or_else(|| home.join(".config"));
        files.push(xdg.join("git").join("config"));
        files.push(home.join(".gitconfig"));
    }
    if let Some(local)=discover_local_config() { files.push(local); }
    load_files(&files)
}
fn load_files(files:&[PathBuf])->GitConfig{
    let mut cfg=GitConfig::default();
    for f in files {
        if !f.exists() { continue; }
        match parse_file_recursive(f, &mut cfg, 0) {
            Ok(())=>{},
            Err(_)=>{ return GitConfig::default(); }
        }
    }
    cfg
}
pub fn home_dir()->Option<PathBuf>{
    if let Some(h)=std::env::var_os("HOME") { if !h.is_empty() { return Some(PathBuf::from(h)); } }
    None
}
fn discover_local_config()->Option<PathBuf>{
    let cwd=std::env::current_dir().ok()?;
    let mut dir: &Path = &cwd;
    loop {
        let cand=dir.join(".git");
        if cand.is_dir() { return Some(cand.join("config")); }
        if cand.is_file() {
            if let Ok(content)=std::fs::read_to_string(&cand) {
                for line in content.lines() {
                    if let Some(rest)=line.strip_prefix("gitdir:") {
                        let p=rest.trim();
                        let gitdir= if Path::new(p).is_absolute() { PathBuf::from(p)} else { dir.join(p)};
                        return Some(gitdir.join("config"));
                    }
                }
            }
            return None;
        }
        // dir itself is a git dir?
        if dir.join("HEAD").exists() && dir.join("config").exists() && dir.file_name().map(|s|s==".git").unwrap_or(false) {
            return Some(dir.join("config"));
        }
        dir = dir.parent()?;
    }
}
fn parse_file_recursive(path:&Path, cfg:&mut GitConfig, depth:usize)->Result<(),String>{
    if depth>10 { return Ok(()); }
    let content=std::fs::read_to_string(path).map_err(|e|e.to_string())?;
    // git config may contain non-utf8; read_to_string failing would be parse error -> empty config in caller.
    let mut section: Option<(String,Option<String>)>=None;
    let parent_dir=path.parent().unwrap_or(Path::new(".")).to_path_buf();
    let mut lines=content.lines().peekable();
    let mut logical = String::new();
    // Handle line continuations (backslash at EOL inside value) at raw level? Git: line continuation only in values. Simpler join lines ending with an odd number trailing backslashes by removing final backslash + newline before parsing.
    let mut physical_lines:Vec<String>=Vec::new();
    for l in content.lines() { physical_lines.push(l.to_string()); }
    let mut idx=0;
    while idx<physical_lines.len() {
        let mut line=physical_lines[idx].clone(); idx+=1;
        while line.ends_with('\\') && !line.ends_with("\\\\") && idx<physical_lines.len() {
            line.pop(); line.push('\n'); line.push_str(&physical_lines[idx]); idx+=1;
        }
        let _=logical;
        let trimmed=line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with(';') { continue; }
        if trimmed.starts_with('[') {
            // find ]
            let close=trimmed.find(']').ok_or("bad section")?;
            let rest_after=&trimmed[close+1..].trim();
            if !rest_after.is_empty() && !rest_after.starts_with('#') && !rest_after.starts_with(';') { return Err("bad section trailing".into()); }
            let inside=&trimmed[1..close].trim();
            // [section "subsection"] or [section.sub]
            if let Some(qpos)=inside.find('"') {
                let sec=inside[..qpos].trim().to_lowercase();
                if sec.is_empty() {return Err("bad section".into());}
                let rest=&inside[qpos..];
                // rest should be quoted string
                let sub=parse_quoted(rest.trim()).ok_or("bad subsection")?;
                section=Some((sec,Some(sub)));
            } else if let Some(dot)=inside.find('.') {
                let sec=inside[..dot].to_lowercase();
                let sub=inside[dot+1..].to_lowercase();
                section=Some((sec,Some(sub)));
            } else {
                if inside.is_empty() {return Err("bad section".into());}
                section=Some((inside.to_lowercase(),None));
            }
            if let Some((sec,Some(sub)))=&section {
                if sec=="delta" && !cfg.delta_feature_names_in_order.contains(sub) { cfg.delta_feature_names_in_order.push(sub.clone()); }
            }
            continue;
        }
        // key line
        let (sec,sub)=match &section { Some((a,b)=>(a.clone(),b.clone())), None=>return Err("key outside section".into()) };
        // key is first token up to = or whitespace/comment
        let mut pos=0usize; let chars:Vec<char>=line.chars().collect();
        while pos<chars.len() && chars[pos].is_whitespace() {pos+=1;}
        let start=pos;
        if pos>=chars.len() || !chars[pos].is_ascii_alphabetic() { return Err("bad key".into()); }
        while pos<chars.len() && (chars[pos].is_ascii_alphanumeric()||chars[pos]=='-') {pos+=1;}
        let keyname:String=chars[start..pos].iter().collect::<String>().to_lowercase();
        while pos<chars.len() && chars[pos].is_whitespace() {pos+=1;}
        let mut value: Option<String>=None;
        if pos<chars.len() {
            if chars[pos]=='=' {
                pos+=1;
                let rawval:String=chars[pos..].iter().collect();
                value=Some(parse_value(&rawval).ok_or("bad value")?);
            } else if chars[pos]=='#' || chars[pos]==';' {
                value=None;
            } else {
                return Err("bad config line".into());
            }
        }
        // Handle include.path immediately in order
        let is_include = sec=="include" && sub.is_none() && keyname=="path";
        let key=Key{section:sec.clone(),subsection:sub.clone(),name:keyname.clone()};
        cfg.entries.insert(key, value.clone());
        if is_include {
            if let Some(Some(pval))=Some(value.clone()) {
                let inc_path=resolve_include_path(&pval,&parent_dir);
                if inc_path.exists() { let _=parse_file_recursive(&inc_path,cfg,depth+1); }
            }
        }
        // includeIf is not implemented (sections includeif with subsection condition)
    }
    Ok(())
}
fn resolve_include_path(p:&str,parent:&Path)->PathBuf{
    if let Some(rest)=p.strip_prefix("~/") {
        if let Some(h)=home_dir() { return h.join(rest); }
    }
    let path=Path::new(p);
    if path.is_absolute() { path.to_path_buf()} else { parent.join(path)}
}
fn parse_quoted(s:&str)->Option<String>{
    if !s.starts_with('"') {return None;}
    let mut out=String::new(); let mut chars=s.chars(); chars.next();
    let mut closed=false;
    while let Some(c)=chars.next() {
        if c=='"' {closed=true; break;}
        if c=='\\' { let n=chars.next()?; match n {'"' => out.push('"'),'\\'=>out.push('\\'),_=>{out.push('\\');out.push(n);} } } else {out.push(c);}
    }
    if closed {Some(out)} else {None}
}
fn parse_value(raw:&str)->Option<String>{
    let mut out=String::new();
    let mut in_quotes=false;
    let mut chars:Vec<char>=raw.chars().collect();
    let mut i=0;
    // Trim leading whitespace outside quotes (handled by skipping? Git strips leading whitespace)
    while i<chars.len() && chars[i].is_whitespace() && chars[i]!='\n' { if chars[i]==' '||chars[i]=='\t' {i+=1;} else {break;} }
    while i<chars.len() {
        let c=chars[i];
        if in_quotes {
            if c=='"' {in_quotes=false; i+=1; continue;}
            if c=='\\' {
                if i+1>=chars.len() {return None;}
                let n=chars[i+1]; i+=2;
                match n {'n'=>out.push('\n'),'t'=>out.push('\t'),'b'=>out.push('\u{0008}'),'"'=>out.push('"'),'\\'=>out.push('\\'),_=>return None}
                continue;
            }
            out.push(c); i+=1; continue;
        } else {
            if c=='"' {in_quotes=true; i+=1; continue;}
            if c=='\\' && i+1<chars.len() {
                // outside quotes git treats backslash escapes similarly for some chars; line continuations already joined (as \n inserted). If next is comment char etc preserve?
                let n=chars[i+1];
                match n {'n'=>{out.push('\n');i+=2;continue;},'t'=>{out.push('\t');i+=2;continue;},'b'=>{out.push('\u{0008}');i+=2;continue;},'"'=>{out.push('"');i+=2;continue;},'\\'=>{out.push('\\');i+=2;continue;},_=>{out.push(c);i+=1;continue;}}
            }
            if (c=='#'||c==';') && (i==0 || chars[i-1].is_whitespace()) {
                break;
            }
            out.push(c); i+=1;
        }
    }
    if in_quotes {return None;}
    // Trim trailing whitespace not in quotes: our out may include trailing spaces from unquoted part. Since quotes segments lost info, approximate trim trailing spaces/tabs but not if original ended with quoted segment - rare.
    Some(out.trim_end_matches(|c| c==' '||c=='\t'||c=='\r').to_string())
}
pub fn parse_git_bool(v:&Option<String>)->Option<bool>{
    match v {
        None=>Some(true),
        Some(s)=>{
            let t=s.trim().to_lowercase();
            match t.as_str() {
                ""=>Some(false),
                "true"|"yes"|"on"=>Some(true),
                "false"|"no"|"off"=>Some(false),
                _=>{
                    if let Ok(n)=t.parse::<i64>() { Some(n!=0) } else { None }
                }
            }
        }
    }
}
RS
"}

