#[derive(Clone,Debug,PartialEq,Eq)]
pub enum LangKind { Plain, Python, Rust, CLike, Go, JavaScript, Ruby, Shell, Php, Html, Css, Haskell, Lisp, Sql, Lua, Perl, Generic }

pub fn language_name_for_path(path:&str, default_language:&str)->String{
    let base=path.rsplit('/').next().unwrap_or(path);
    // exact filename / dotfile
    for (name,exts) in LANGUAGES {
        for e in *exts {
            if *e==base { return name.to_string(); }
        }
    }
    // compound extensions (entries containing '.')
    for (name,exts) in LANGUAGES {
        for e in *exts {
            if e.contains('.') && !e.starts_with('.') {
                if base.len()>e.len() && base.ends_with(e) && base.as_bytes().get(base.len()-e.len()-1)==Some(&b'.') { return name.to_string(); }
            }
        }
    }
    if let Some(dot)=base.rfind('.') {
        if dot>0 || base.starts_with('.') && base[1..].contains('.') {
            let ext=&base[dot+1..];
            if !ext.is_empty() {
                for (name,exts) in LANGUAGES {
                    if exts.iter().any(|e|*e==ext) { return name.to_string(); }
                }
            }
        }
    }
    // default language is an extension or language name
    language_name_for_token(default_language).unwrap_or_else(||"Plain Text".to_string())
}
