// Tokenize one line (without trailing newline). Returns (text, category_index) sections merged.
pub fn tokenize_line(line:&str, kind:&LangKind, state:&mut SynState)->Vec<(String,usize)>{
    if *kind==LangKind::Plain { return vec![(line.to_string(),CAT_PLAIN)]; }
    let chars:Vec<char>=line.chars().collect();
    let n=chars.len();
    let mut out:Vec<(String,usize)>=Vec::new();
    let mut push=|out:&mut Vec<(String,usize)>, text:String, cat:usize|{
        if text.is_empty() {return;}
        if let Some(last)=out.last_mut() { if last.1==cat { last.0.push_str(&text); return; } }
        out.push((text,cat));
    };
    let substr=|a:usize,b:usize| -> String { chars[a..b].iter().collect() };
    let mut i=0usize;
    // Context for function-definition parameters/name within this line
    let mut expect_func_name=false;
    let mut expect_class_name=false;
    let mut in_param_list=0usize; // >0 when inside def/fn parentheses
    let mut after_dot=false;
    // Handle continuing block comment/triple string
    // (Fall through to main loop checks at i==0)
    while i<n {
        // Block comment continuation
        if let SynState::BlockComment(end)=state.clone() {
            if line[i..].starts_with(&end) {
                let l=end.chars().count(); push(&mut out,substr(i,i+l),CAT_COMMENT); i+=l; *state=SynState::Normal; continue;
            } else {
                push(&mut out,substr(i,n),CAT_COMMENT); i=n; break;
            }
        }
        if let SynState::TripleString(q)=state.clone() {
            if line[i..].starts_with(&q) {
                let l=q.chars().count(); push(&mut out,substr(i,i+l),CAT_STRING); i+=l; *state=SynState::Normal; continue;
            } else {
                // consume to end or closing
                if let Some(pos)=line[i..].find(&q) {
                    let charpos=line[..line.char_indices().nth(i).map(|x|x.0).unwrap_or(line.len())].chars().count();
                    let _=charpos;
                    let endidx=i+line[i..].chars().take_while(|_|false).count(); let _=endidx;
                    // find char index of pos
                    let byte_start=line.char_indices().nth(i).map(|x|x.0).unwrap_or(line.len());
                    let end_byte=byte_start+pos+q.len();
                    let end_char=line[..end_byte].chars().count();
                    push(&mut out,substr(i,end_char),CAT_STRING); i=end_char; *state=SynState::Normal; continue;
                } else { push(&mut out,substr(i,n),CAT_STRING); i=n; break; }
            }
        }
        let rest:&str=&line[line.char_indices().nth(i).map(|x|x.0).unwrap_or(line.len())..];
        // Comments
        let line_comment: Option<&str> = match kind {
            LangKind::Python|LangKind::Ruby|LangKind::Shell|LangKind::Perl|LangKind::Generic => if rest.starts_with('#') {Some("#")} else {None},
            LangKind::Haskell|LangKind::Sql|LangKind::Lua => if rest.starts_with("--") {Some("--")} else {None},
            LangKind::Lisp => if rest.starts_with(';') {Some(";")} else {None},
            _=> if rest.starts_with("//") {Some("//")} else if *kind==LangKind::Php && rest.starts_with('#') {Some("#")} else {None},
        };
        if line_comment.is_some() {
            push(&mut out,substr(i,n),CAT_COMMENT); break;
        }
        if rest.starts_with("/*") && matches!(kind,LangKind::Rust|LangKind::CLike|LangKind::Go|LangKind::JavaScript|LangKind::Php|LangKind::Css) {
            if let Some(pos)=rest[2..].find("*/") {
                let end=i+2+rest[2..].chars().take(pos+2).count(); push(&mut out,substr(i,end),CAT_COMMENT); i=end; continue;
            } else { push(&mut out,substr(i,n),CAT_COMMENT); *state=SynState::BlockComment("*/".into()); break; }
        }
        if rest.starts_with("<!--") && *kind==LangKind::Html {
            if let Some(pos)=rest[4..].find("-->") { let end=i+4+rest[4..].chars().take(pos+3).count(); push(&mut out,substr(i,end),CAT_COMMENT); i=end; continue; }
            else { push(&mut out,substr(i,n),CAT_COMMENT); *state=SynState::BlockComment("-->".into()); break; }
        }
        let ch=chars[i];
        // Strings
        if ch=='"' || ch=='\'' || (ch=='`' && *kind==LangKind::JavaScript) {
            // Python triple
            if *kind==LangKind::Python && rest.len()>=3 && (&rest[0..3]=="\"\"\"" || &rest[0..3]=="'''") {
                let q=&rest[0..3];
                if let Some(pos)=rest[3..].find(q) { let end=i+3+rest[3..].chars().take(pos+3).count(); push(&mut out,substr(i,end),CAT_STRING); i=end; continue; }
                else { push(&mut out,substr(i,n),CAT_STRING); *state=SynState::TripleString(q.to_string()); break; }
            }
            // Rust char literal / lifetime: single quote handling
            if *kind==LangKind::Rust && ch=='\'' {
                // lifetime 'a (letter then not closing quickly) -> treat as plain quote then ident as parameter?
                // Check char literal: '\'' escaped or single char then '\''
                let mut j=i+1; let mut is_char=false;
                if j<n {
                    if chars[j]=='\\' { // '\n' etc then closing
                        if j+2<n && chars[j+2]=='\'' {is_char=true;}
                    } else if j+1<n && chars[j+1]=='\'' {is_char=true;}
                }
                if is_char {
                    // consume through closing
                    let mut end=i+1; if end<n && chars[end]=='\\' {end+=2;} else {end+=1;} end+=1; // closing
                    push(&mut out,substr(i,end.min(n)),CAT_STRING); i=end.min(n); after_dot=false; continue;
                } else {
                    push(&mut out,"'".to_string(),CAT_PLAIN); i+=1; continue;
                }
            }
            // regular string to closing (respect escapes except Python raw? ignore)
            let mut j=i+1;
            while j<n {
                if chars[j]=='\\' { j+=2; continue; }
                if chars[j]==ch { j+=1; break; }
                j+=1;
            }
            if j>n {j=n;}
            push(&mut out,substr(i,j),CAT_STRING); i=j; after_dot=false; expect_func_name=false; continue;
        }
        // Rust raw string r"..." r#"..."#
        if *kind==LangKind::Rust && ch=='r' && (rest.starts_with("r\"")||rest.starts_with("r#")) {
            // find closing: count hashes
            let hashes=rest.chars().skip(1).take_while(|c|*c=='#').count();
            if rest.chars().nth(1+hashes)==Some('"') {
                let close=format!("\"{}", "#".repeat(hashes));
                if let Some(pos)=rest[1+hashes+1..].find(&close) {
                    let byte_len=1+hashes+1+pos+close.len(); let end=i+rest[..byte_len].chars().count(); push(&mut out,substr(i,end),CAT_STRING); i=end; continue;
                }
            }
        }
        // Numbers
        if ch.is_ascii_digit() {
            let mut j=i;
            // hex etc
            while j<n && (chars[j].is_ascii_alphanumeric()||chars[j]=='_'||chars[j]=='.') {
                // stop .. range operator: if '..' and previous consumed digits and next is '.' break before second?
                if chars[j]=='.' && j+1<n && chars[j+1]=='.' {break;}
                // Don't include trailing '.' if followed by non-digit in float like 3.0); our loop includes both and then outer will split? To match syntect number token often includes whole 3.0, but reference show number emph only '3' and .0 plain in diff; in zero line check number segment includes 123 only. For "3.0" syntect token likely is whole float. Keep, painter emph splitting by token alignment may differ (word tokens, not syntax sections).
                j+=1;
            }
            // Trim trailing dot
            while j>i && chars[j-1]=='.' {j-=1;}
            if j==i {j=i+1;}
            push(&mut out,substr(i,j),CAT_NUMBER); i=j; after_dot=false; continue;
        }
        // Identifiers
        if ch=='_' || ch=='$' || ch.is_alphabetic() {
            let mut j=i;
            while j<n && (chars[j]=='_'||chars[j]=='$'||chars[j].is_alphanumeric()) {j+=1;}
            let word=substr(i,j);
            // Determine following char (skipping spaces)
            let mut k=j; while k<n && chars[k]==' ' {k+=1;}
            let following=if k<n {Some(chars[k])} else {None};
            let cat = if expect_func_name {
                expect_func_name=false; in_param_list=usize::MAX; CAT_FUNCTION
            } else if expect_class_name {
                expect_class_name=false; CAT_CLASS
            } else if def_words(kind).contains(&word.as_str()) {
                expect_func_name=true; if word=="class" {expect_func_name=false; expect_class_name=true;}
                CAT_DEFKEYWORD
            } else if storage_words(kind).contains(&word.as_str()) {
                if (*kind==LangKind::Rust && word=="fn") || (*kind==LangKind::Go && word=="func") { expect_func_name=true; }
                if *kind==LangKind::JavaScript && word=="function" { expect_func_name=true; }
                // In CLike, type words should be Type not Storage; our storage list for CLike includes them, map to TYPE there
                if *kind==LangKind::CLike { CAT_TYPE } else { CAT_STORAGE }
            } else if type_words(kind).contains(&word.as_str()) {
                CAT_TYPE
            } else if constant_words(kind).contains(&word.as_str()) {
                CAT_CONSTANT
            } else if keywords(kind).contains(&word.as_str()) {
                if word=="class" {expect_class_name=true;}
                CAT_KEYWORD
            } else if in_param_list>0 && in_param_list!=usize::MAX {
                // inside a def parameter list tracked below via paren handling after function name
                CAT_PARAMETER
            } else if in_param_list==usize::MAX {
                // we are in function name state until '('; identifiers before '(' are func name (only first handled above), after that plain
                CAT_PLAIN
            } else if following==Some('(') && after_dot==false && matches!(kind,LangKind::Python|LangKind::Ruby) && ["print","len","range","str","int","list","dict","set","tuple","open","super","isinstance","type","repr"].contains(&word.as_str()) {
                // Python builtins: syntect may color support functions - approximate as TYPE (teal?) checked later
                CAT_TYPE
            } else if word.chars().next().map(|c|c.is_uppercase()).unwrap_or(false) && matches!(kind,LangKind::Rust|LangKind::CLike|LangKind::Go) {
                CAT_TYPE
            } else {
                CAT_PLAIN
            };
            push(&mut out,word,cat); i=j; after_dot=false; continue;
        }
        // Operators / punctuation
        if ch=='(' {
            if in_param_list==usize::MAX { in_param_list=1; } else if in_param_list>0 { in_param_list+=1; }
            push(&mut out,"(".to_string(),CAT_PLAIN); i+=1; after_dot=false; continue;
        }
        if ch==')' {
            if in_param_list>0 && in_param_list!=usize::MAX { in_param_list-=1; }
            push(&mut out,")".to_string(),CAT_PLAIN); i+=1; after_dot=false; continue;
        }
        if ch=='.' { push(&mut out,".".to_string(),CAT_PLAIN); i+=1; after_dot=true; continue; }
        if "+-*/%<>=!&|^~?:".contains(ch) {
            // Colon handling: in many languages ':' plain, but TS type colon pink, Rust :: plain. Treat ':' plain except JavaScript? Match sample: TS ':' was operator. For Python ':' plain.
            if ch==':' {
                // :: as one plain token
                if rest.starts_with("::") { push(&mut out,"::".to_string(),CAT_PLAIN); i+=2; after_dot=false; continue; }
                let cat=if *kind==LangKind::JavaScript {CAT_OPERATOR} else {CAT_PLAIN};
                push(&mut out,":".to_string(),cat); i+=1; after_dot=false; continue;
            }
            // operator run
            let mut j=i; while j<n && "+-*/%<>=!&|^~".contains(chars[j]) {j+=1;}
            // '->' '=>' etc are runs included
            push(&mut out,substr(i,j),CAT_OPERATOR); i=j; after_dot=false; continue;
        }
        // whitespace / punctuation single char as plain (merge)
        push(&mut out,ch.to_string(),CAT_PLAIN); i+=1; if !ch.is_whitespace() {after_dot=false;}
    }
    out
}
RS
"}

