fn builtin_feature(name:&str)->Option<HashMap<String,Val>>{
    let mut m:HashMap<String,Val>=HashMap::new();
    let mut s=|k:&str,v:&str|{m.insert(k.to_string(),Val::S(v.to_string()));};
    let mut b=|k:&str,v:bool|{m.insert(k.to_string(),Val::B(v));};
    match name {
        "navigate"=>{ b("navigate",true); s("file-modified-label","\u{0394}"); s("hunk-label","\u{2022}"); }
        "hyperlinks"=>{ b("hyperlinks",true); }
        "line-numbers"=>{ b("line-numbers",true); }
        "side-by-side"=>{ b("side-by-side",true); s("minus-style","syntax auto"); s("minus-emph-style","syntax auto"); }
        "color-only"=>{ b("color-only",true); s("file-style","raw"); s("hunk-header-style","raw"); b("keep-plus-minus-markers",true); s("tabs","0"); }
        "raw"=>{ b("raw",true); s("commit-style","raw"); s("file-style","raw"); s("hunk-header-style","raw"); s("minus-style","red"); s("minus-emph-style","red"); s("zero-style","normal"); s("plus-style","green"); s("plus-emph-style","green"); b("keep-plus-minus-markers",true); s("tabs","0"); }
        "diff-highlight"=>{ b("diff-highlight",true); s("commit-style","raw"); s("file-style","raw"); s("hunk-header-style","raw"); s("minus-style","red"); s("minus-emph-style","reverse red"); s("zero-style","normal"); s("plus-style","green"); s("plus-emph-style","reverse green"); }
        "diff-so-fancy"=>{ b("diff-so-fancy",true); s("file-style","brightyellow"); s("file-decoration-style","bold yellow ul ol"); s("hunk-header-style","file line-number bold syntax"); s("hunk-header-decoration-style","purple box"); s("minus-style","bold red"); s("minus-emph-style","bold red 52"); s("zero-style","normal"); s("plus-style","bold green"); s("plus-emph-style","bold green 22"); }
        _=>return None,
    }
    Some(m)
}
pub static BUILTIN_FEATURE_NAMES: &[&str]=&["color-only","diff-highlight","diff-so-fancy","hyperlinks","line-numbers","navigate","raw","side-by-side"];

struct Resolver {
    raw: RawOpts,
    git: GitConfig,
    user_feature_maps: Vec<HashMap<String,Val>>, // expanded in order
    pseudo_feature_maps: Vec<HashMap<String,Val>>, // builtin bool activations, before user features; filled after initial bool check in two passes
    no_gitconfig: bool,
    final_feature_names: Vec<String>,
}
impl Resolver {
    fn git_main(&self,name:&str)->Option<Val>{
        if self.no_gitconfig {return None;}
        match self.git.get("delta",None,name) {
            Some(Some(v))=>Some(Val::S(v.clone())),
            Some(None)=>Some(Val::B(true)),
            None=>None,
        }
    }
    fn cli_val(&self,name:&str)->Option<Val>{
        if let Some(v)=self.raw.get(name) {return Some(Val::S(v.to_string()));}
        if self.raw.flag(name) {return Some(Val::B(true));}
        None
    }
    fn get(&self,name:&str)->Option<Val>{
        if let Some(v)=self.cli_val(name) {return Some(v);}
        if let Some(v)=self.git_main(name) {return Some(v);}
        // user feature maps last wins
        let mut out:Option<Val>=None;
        for map in &self.user_feature_maps { if let Some(v)=map.get(name) {out=Some(v.clone());} }
        if out.is_some() {return out;}
        for map in &self.pseudo_feature_maps { if let Some(v)=map.get(name) {out=Some(v.clone());} }
        out
    }
    fn is_user_explicit(&self,name:&str)->bool{
        self.cli_val(name).is_some() || self.git_main(name).is_some() || self.user_feature_maps.iter().any(|m|m.contains_key(name))
    }
    fn get_no_pseudo(&self,name:&str)->Option<Val>{
        if let Some(v)=self.cli_val(name) {return Some(v);}
        if let Some(v)=self.git_main(name) {return Some(v);}
        let mut out=None; for map in &self.user_feature_maps { if let Some(v)=map.get(name) {out=Some(v.clone());} } out
    }
    fn get_bool(&self,name:&str,default:bool)->bool{
        // CLI flags cannot set false; if CLI flag true use true.
        // For values from git/feature, invalid bool -> ignore that source. Implementation: inspect sources in priority order and return first parseable bool.
        if self.raw.flag(name) {return true;}
        // value options that are booleans via gitconfig aren't CLI strings.
        if let Some(v)=self.git_main(name) {
            if let Some(b)=val_to_bool(&v) {return b;}
        }
        // feature maps last parseable wins: iterate reverse
        for map in self.user_feature_maps.iter().rev() {
            if let Some(v)=map.get(name) { if let Some(b)=val_to_bool(v) {return b;} }
        }
        for map in self.pseudo_feature_maps.iter().rev() {
            if let Some(v)=map.get(name) { if let Some(b)=val_to_bool(v) {return b;} }
        }
        default
    }
    fn get_string(&self,name:&str,default:&str)->String{
        self.get(name).map(|v|v.as_string()).unwrap_or_else(||default.to_string())
    }
    fn get_opt_string(&self,name:&str)->Option<String>{ self.get(name).map(|v|v.as_string()) }
}
fn val_to_bool(v:&Val)->Option<bool>{
    match v { Val::B(b)=>Some(*b), Val::S(s)=>gitconfig::parse_git_bool(&Some(s.clone())) }
}

fn expand_features(names:&[String], git:&GitConfig, out:&mut Vec<HashMap<String,Val>>, stack:&mut Vec<String>){
    for name in names {
        if stack.iter().any(|x|x==name) {continue;}
        if let Some(map)=builtin_feature(name) { out.push(map); continue; }
        // gitconfig feature section
        if git.entries.keys().any(|k|k.section=="delta" && k.subsection.as_deref()==Some(name.as_str())) {
            // nested features first
            if let Some(nested)=git.get_string("delta",Some(name),"features") {
                let nested_names:Vec<String>=nested.split_whitespace().map(|s|s.to_string()).collect();
                stack.push(name.clone());
                expand_features(&nested_names,git,out,stack);
                stack.pop();
            }
            let mut map:HashMap<String,Val>=HashMap::new();
            for (k,v) in &git.entries {
                if k.section=="delta" && k.subsection.as_deref()==Some(name.as_str()) {
                    if k.name=="features" {continue;}
                    map.insert(k.name.clone(), match v {Some(s)=>Val::S(s.clone()),None=>Val::B(true)});
                }
            }
            out.push(map);
        } else {
            // unknown feature ignored
        }
    }
}

fn default_true_color(raw:&RawOpts, resolver:&Resolver)->Result<bool,String>{
    // true-color option: CLI --true-color and --24-bit-color are separate clap opts; gitconfig only "true-color" (24-bit-color key ignored observed)
    // Determine string value: CLI true-color > CLI 24-bit-color > git main true-color > features > default auto
    let val: Option<String> = if let Some(v)=raw.get("true-color") {Some(v.to_string())}
        else if let Some(v)=raw.get("24-bit-color") {Some(v.to_string())}
        else { resolver.get_opt_string("true-color") };
    // NOTE resolver.get will also find CLI true-color; above handles 24-bit precedence. If no CLI, use resolver (git/feature)
    let v=val.unwrap_or_else(||"auto".to_string());
    match v.to_lowercase().as_str() {
        "always"=>Ok(true),
        "never"=>Ok(false),
        "auto"=>Ok(matches!(std::env::var("COLORTERM").ok().as_deref(),Some("truecolor")|Some("24bit"))),
        _=>Err(format!("Invalid value for --true-color option: {} (valid values are \"always\", \"never\", and \"auto\")\n",v)),
    }
}

impl Config {
    pub fn from_raw(raw:RawOpts, terminal_width_opt: Option<usize>, output_is_tty: bool) -> Result<Config,String> {
        let no_gitconfig=raw.flag("no-gitconfig");
        let git = if no_gitconfig { GitConfig::default() } else { gitconfig::load(&raw) };
        // Features base
        let git_main_features: Vec<String> = if no_gitconfig {Vec::new()} else { git.get_string("delta",None,"features").map(|s|s.split_whitespace().map(|x|x.to_string()).collect()).unwrap_or_default() };
        let mut features:Vec<String> = if raw.present("features") { raw.get("features").unwrap_or("").split_whitespace().map(|x|x.to_string()).collect() } else { git_main_features.clone() };
        if let Ok(envf)=std::env::var("DELTA_FEATURES") {
            if let Some(rest)=envf.strip_prefix('+') {
                features.extend(rest.split_whitespace().map(|x|x.to_string()));
            } else {
                features=envf.split_whitespace().map(|x|x.to_string()).collect();
            }
        }
        let mut resolver=Resolver{ raw:raw.clone(), git:git.clone(), user_feature_maps:Vec::new(), pseudo_feature_maps:Vec::new(), no_gitconfig, final_feature_names:features.clone() };
        expand_features(&features,&git,&mut resolver.user_feature_maps,&mut Vec::new());
        // Pseudo features based on final bools (no pseudo yet)
        let mut pseudo:Vec<HashMap<String,Val>>=Vec::new();
        for &bn in BUILTIN_FEATURE_NAMES {
            // Determine bool without pseudo: CLI, main, user features
            let active = {
                let tmp=Resolver{raw:raw.clone(),git:git.clone(),user_feature_maps:resolver.user_feature_maps.clone(),pseudo_feature_maps:Vec::new(),no_gitconfig,final_feature_names:features.clone()};
                tmp.get_bool(bn,false)
            };
            if active {
                if let Some(map)=builtin_feature(bn) { pseudo.push(map); }
            }
        }
        resolver.pseudo_feature_maps=pseudo;
        let r=&resolver;

        // dark/light explicit bools
        let dark=r.get_bool("dark",false);
        let light=r.get_bool("light",false);
        if dark && light { return Err("--light and --dark cannot be used together.\n".to_string()); }
        // true color
        let true_color=default_true_color(&raw,&resolver)?;
        // Syntax theme / light mode
        // syntax-theme string if explicitly resolved (could be empty)
        let syntax_theme_opt: Option<String> = r.get_opt_string("syntax-theme");
        let mut bat_warning:Option<String>=None;
        let mut is_light:bool;
        let syntax_theme: Option<String>;
        let syntax_theme_display:String;
        // Determine candidate theme string
        let candidate: Option<String> = if let Some(s)=syntax_theme_opt.clone() { Some(s) } else { std::env::var("BAT_THEME").ok() };
        // light explicit flag
        let light_explicit = if dark {Some(false)} else if light {Some(true)} else {None};
        match candidate {
            Some(cand) if cand=="none" => {
                syntax_theme=None; syntax_theme_display="none".to_string();
                is_light=light_explicit.unwrap_or(false);
            }
            Some(cand) if cand.is_empty() => {
                // treated as invalid/no theme but BAT ignored; default by light explicit else dark
                is_light=light_explicit.unwrap_or(false);
                let key=if is_light {"GitHub"} else {"Monokai Extended"};
                syntax_theme=Some(key.to_string()); syntax_theme_display=syntax::canonical_theme_name(key);
            }
            Some(cand) => {
                if syntax::is_valid_theme(&cand) {
                    is_light=light_explicit.unwrap_or_else(||syntax::is_light_theme(&cand));
                    syntax_theme_display=syntax::canonical_theme_name(&cand);
                    syntax_theme=Some(cand);
                } else {
                    bat_warning=Some(format!("\x1b[33m[bat warning]\x1b[0m: Unknown theme '{}', using default.\n",cand));
                    is_light=light_explicit.unwrap_or(false);
                    let key=if is_light {"GitHub"} else {"Monokai Extended"};
                    syntax_theme=Some(key.to_string()); syntax_theme_display=syntax::canonical_theme_name(key);
                }
            }
            None=>{
                // Terminal dark/light detection will be handled by caller? For piped output default dark.
                // detect-dark-light option is resolved here as string; if stdout is tty and mode allows, main may have computed a detected light value and passed via env hack? We implement detection in main by setting an internal env? Simpler: Config gets terminal detection via a global set by main before calling from_raw (see crate::DETECTED_LIGHT). Fallback dark.
                let detected = crate::detected_light_mode();
                is_light=light_explicit.or(detected).unwrap_or(false);
                let key=if is_light {"GitHub"} else {"Monokai Extended"};
                syntax_theme=Some(key.to_string()); syntax_theme_display=syntax::canonical_theme_name(key);
            }
        }
        if light_explicit.is_some() && candidate.is_some() && syntax_theme.is_some() {
            // already handled
        }
        // Colour defaults for auto resolution
        let (minus_bg, minus_emph_bg, plus_bg, plus_emph_bg): (Color,Color,Color,Color) = if true_color {
            if is_light { (Color::Rgb(255,224,224),Color::Rgb(255,192,192),Color::Rgb(208,255,208),Color::Rgb(160,239,160)) }
            else { (Color::Rgb(63,0,1),Color::Rgb(144,16,17),Color::Rgb(0,40,0),Color::Rgb(0,96,0)) }
