fn parse_width(ws:&str, terminal_width:usize)->Result<(WidthSpec,usize),String>{
    let orig=ws;
    // Check expression form a-b (a and b integers, a defined), but single leading '-n' is relative.
    // Find '-' that is not at start.
    let bytes=ws.as_bytes();
    let mut dash_pos:Option<usize>=None;
    for i in 1..bytes.len() { if bytes[i]==b'-' {dash_pos=Some(i); break;} }
    if let Some(pos)=dash_pos {
        let left=&ws[..pos]; let right=&ws[pos+1..];
        // left/right must be integers
        let l=left.parse::<i64>().map_err(|_|format!("Invalid value for width: \"{}\" is not an integer\n",orig))?;
        let r=right.parse::<i64>().map_err(|_|format!("Invalid value for width: \"{}\" is not an integer\n",orig))?;
        let result=l-r;
        if result<0 { return Err(format!("Invalid value for width: expression \"{}\" is not positive\n",orig)); }
        let u=result as usize; return Ok((WidthSpec::Fixed(u),u));
    }
    match ws.parse::<i64>() {
        Ok(v)=>{
            if v>=0 {let u=v as usize; Ok((WidthSpec::Fixed(u),u))}
            else {
                let result = terminal_width as i64 + v;
                let u=if result<0 {0} else {result as usize};
                Ok((WidthSpec::Fixed(u),u))
            }
        }
        Err(_)=>Err(format!("Invalid value for width: \"{}\" is not an integer\n",orig)),
    }
}
