use std::collections::{HashMap, HashSet, VecDeque};

#[derive(Clone,Debug,PartialEq,Eq)]
pub enum CallingProcess {
    GitGrep,
    Ripgrep,
    GitBlame(Option<String>),
    GitOther,
    Other,
}
#[derive(Clone,Debug)]
struct Proc { pid:i64, ppid:i64, argv:Vec<String> }

fn read_procs()->HashMap<i64,Proc>{
    let mut map=HashMap::new();
    if let Ok(entries)=std::fs::read_dir("/proc") {
        for ent in entries.flatten() {
            let name=ent.file_name(); let Some(name)=name.to_str() else {continue};
            let Ok(pid)=name.parse::<i64>() else {continue};
            let cmdline=std::fs::read(ent.path().join("cmdline")).unwrap_or_default();
            if cmdline.is_empty() {continue;}
            let argv:Vec<String>=cmdline.split(|b|*b==0).filter(|s|!s.is_empty()).map(|s|String::from_utf8_lossy(s).to_string()).collect();
            let stat=std::fs::read_to_string(ent.path().join("stat")).unwrap_or_default();
            // ppid is field after comm (in parens)
            let ppid:i64 = (||{
                let end=stat.rfind(')')?; let rest=&stat[end+2..]; let mut f=rest.split_whitespace(); let _state=f.next()?; f.next()?.parse().ok()
            })().unwrap_or(0);
            map.insert(pid,Proc{pid,ppid,argv});
        }
    }
    map
}
fn basename(s:&str)->&str{ s.rsplit('/').next().unwrap_or(s) }
fn git_subcommand(argv:&[String])->Option<(&str,usize)>{
    let mut i=1;
    while i<argv.len() {
        let a=&argv[i];
        if a=="-c" || a=="-C" || a=="--git-dir" || a=="--work-tree" || a=="--namespace" || a=="--exec-path" { i+=2; continue; }
        if a.starts_with("--git-dir=")||a.starts_with("--work-tree=")||a.starts_with("--namespace=")||a.starts_with("--exec-path=") {i+=1; continue;}
        if a.starts_with('-') {i+=1; continue;}
        return Some((a.as_str(),i));
    }
    None
}
fn match_proc(p:&Proc)->Option<CallingProcess>{
    if p.argv.is_empty() {return None;}
    let exe=basename(&p.argv[0]);
    if exe=="rg" {return Some(CallingProcess::Ripgrep);}
    if exe=="git" {
        if let Some((sub,idx))=git_subcommand(&p.argv) {
            match sub {
                "grep"=>return Some(CallingProcess::GitGrep),
                "blame"=>{
                    let mut file:Option<String>=None;
                    let args=&p.argv[idx+1..];
                    let mut after_dashdash=false;
                    for a in args {
                        if a=="--" {after_dashdash=true; continue;}
                        if !after_dashdash && a.starts_with('-') {continue;}
                        file=Some(a.clone());
                    }
                    return Some(CallingProcess::GitBlame(file));
                }
                _=>return Some(CallingProcess::GitOther),
            }
        }
    }
    None
}
pub fn detect_calling_process()->CallingProcess{
    let procs=read_procs();
    if procs.is_empty() {return CallingProcess::Other;}
    let self_pid=std::process::id() as i64;
    // ancestors
    let mut ancestors:Vec<i64>=Vec::new();
    let mut cur=self_pid;
    for _ in 0..64 {
        let Some(p)=procs.get(&cur) else {break};
        if p.ppid<=0 {break;}
        ancestors.push(p.ppid);
        if p.ppid==cur {break;}
        cur=p.ppid;
    }
    let lineage:HashSet<i64> = ancestors.iter().cloned().chain([self_pid]).collect();
    // children map
    let mut children:HashMap<i64,Vec<i64>>=HashMap::new();
    for p in procs.values() { children.entry(p.ppid).or_default().push(p.pid); }
    for v in children.values_mut() {v.sort();}
    for anc in &ancestors {
        if let Some(p)=procs.get(anc) {
            if let Some(m)=match_proc(p) {
                // Only return interesting sources; GitOther is recorded but other ancestors/siblings might be more specific? If immediate ancestor is git diff/show, this is the calling process. Return it unless it's GitOther and a sibling grep exists in same pipeline (e.g. parent shell's other child is git grep, ancestor shell itself is not git). For a git-diff ancestor case, returning GitOther is fine.
                if m!=CallingProcess::GitOther {return m;}
                else {
                    // If ancestor is a git process but not grep/blame, this is likely the true caller (pager case). Return it.
                    return m;
                }
            }
        }
        // descendants of anc excluding lineage
        let mut queue:VecDeque<i64>=VecDeque::new();
        let mut seen:HashSet<i64>=HashSet::new();
        if let Some(kids)=children.get(anc) { for k in kids { if !lineage.contains(k) {queue.push_back(*k);} } }
        while let Some(pid)=queue.pop_front() {
            if !seen.insert(pid) {continue;}
            if let Some(p)=procs.get(&pid) {
                if let Some(m)=match_proc(p) {
                    if m!=CallingProcess::GitOther {return m;}
                    // Keep searching in this subtree for a more specific process; a git-other sibling could be an unrelated git invocation.
                }
            }
            if let Some(kids)=children.get(&pid) { for k in kids { if !lineage.contains(k) {queue.push_back(*k);} } }
        }
    }
    CallingProcess::Other
}
RS
"}

