use unicode_width::UnicodeWidthChar;
use crate::style::*;
use crate::config::Config;
use std::collections::HashMap;

#[derive(Clone,Debug,PartialEq)]
pub struct ConcreteStyle { pub fg: Option<Color>, pub bg: Option<Color>, pub attrs: Vec<&'static str> }
impl ConcreteStyle {
    pub fn plain()->Self{ConcreteStyle{fg:None,bg:None,attrs:Vec::new()}}
    pub fn from_style_resolved(st:&Style, syntax_fg: Option<Color>)->Self{
        let mut attrs=Vec::new();
        if st.bold {attrs.push("1");}
        if st.dim {attrs.push("2");}
        if st.italic {attrs.push("3");}
        if st.underline {attrs.push("4");}
        if st.blink {attrs.push("5");}
        if st.reverse {attrs.push("7");}
        if st.hidden {attrs.push("8");}
        if st.strike {attrs.push("9");}
        let fg=match st.fg {Fg::Color(c)=>Some(c),Fg::Syntax=>syntax_fg,Fg::Normal=>None};
        let bg=match st.bg {Bg::Color(c)=>Some(c),Bg::Normal=>None};
        ConcreteStyle{fg,bg,attrs}
    }
    pub fn from_raw_style(st:&Style)->Self{ Self::from_style_resolved(st,None) }
    pub fn is_plain(&self)->bool{self.fg.is_none()&&self.bg.is_none()&&self.attrs.is_empty()}
    pub fn codes_full(&self)->Vec<String>{
        let mut v:Vec<String>=self.attrs.iter().map(|s|s.to_string()).collect();
        if let Some(bg)=self.bg {v.push(bg.ansi_bg());}
        if let Some(fg)=self.fg {v.push(fg.ansi_fg());}
        v
    }
    pub fn prefix_full(&self)->String{
        let c=self.codes_full(); if c.is_empty() {String::new()} else {format!("\x1b[{}m",c.join(";"))}
    }
}
#[derive(Clone,Debug)]
pub struct PaintSection { pub style: ConcreteStyle, pub text: String }

pub struct StylePainter { pub current: ConcreteStyle }
impl StylePainter {
    pub fn new()->Self{StylePainter{current:ConcreteStyle::plain()}}
    pub fn paint_sections(&mut self, sections:&[PaintSection], out:&mut String){
        for sec in sections {
            self.transition_to(&sec.style,out);
            out.push_str(&sec.text);
        }
    }
    pub fn transition_to(&mut self, target:&ConcreteStyle,out:&mut String){
        if *target==self.current {return;}
        if target.is_plain() {
            out.push_str("\x1b[0m"); self.current=ConcreteStyle::plain(); return;
        }
        // Need reset if an attribute is removed, or fg/bg removed
        let attrs_removed=self.current.attrs.iter().any(|a|!target.attrs.contains(a));
        let fg_removed=self.current.fg.is_some()&&target.fg.is_none();
        let bg_removed=self.current.bg.is_some()&&target.bg.is_none();
        if attrs_removed || fg_removed || bg_removed {
