            out.push_str("\x1b[0m");
            out.push_str(&target.prefix_full());
            self.current=target.clone(); return;
        }
        // Emit only added/changed codes in order attrs,bg,fg
        let mut codes:Vec<String>=Vec::new();
        for a in &target.attrs { if !self.current.attrs.contains(a) {codes.push(a.to_string());} }
        if target.bg!=self.current.bg { if let Some(bg)=target.bg {codes.push(bg.ansi_bg());} }
        if target.fg!=self.current.fg { if let Some(fg)=target.fg {codes.push(fg.ansi_fg());} }
        if !codes.is_empty() { out.push_str(&format!("\x1b[{}m",codes.join(";"))); }
        self.current=target.clone();
    }
    pub fn finish(&mut self,out:&mut String){
        if !self.current.is_plain() {out.push_str("\x1b[0m"); self.current=ConcreteStyle::plain();}
