// Standalone paint a text with a Style where fg syntax is resolved to a single colour (or syntax sections handled by caller)
pub fn paint_with_style(style:&Style, text:&str, syntax_color:Option<Color>)->String{
    if style.is_omit {return String::new();}
    let conc=ConcreteStyle::from_style_resolved(style,syntax_color);
    if conc.is_plain() {return text.to_string();}
    format!("{}{}\x1b[0m",conc.prefix_full(),text)
}

pub fn display_width(s:&str)->usize{
    let mut w=0usize;
    for c in s.chars() {
        if c=='\t' {w+=1; continue;}
        w+=c.width().unwrap_or(0);
    }
    w
}
pub fn expand_tabs(s:&str, tab_width:usize)->String{
    if tab_width==0 {return s.to_string();}
    let spaces=" ".repeat(tab_width);
    s.replace('\t',&spaces)
}
pub fn truncate_chars(s:&str, max:usize)->String{
    if max==0 {return s.to_string();}
    if s.chars().count()<=max {return s.to_string();}
    s.chars().take(max).collect()
}

// Format a single numeric/string field according to a placeholder spec after ':'
// spec example "^4", ">4", "<15.14", ""; fill char may precede alignment.
pub fn format_field(value:&str, spec:&str)->String{
    if spec.is_empty() {return value.to_string();}
    let chars:Vec<char>=spec.chars().collect();
    let mut idx=0; let mut fill=' '; let mut align:Option<char>=None;
    if chars.len()>=2 && ['<','^','>'].contains(&chars[1]) {fill=chars[0]; align=Some(chars[1]); idx=2;}
    else if !chars.is_empty() && ['<','^','>'].contains(&chars[0]) {align=Some(chars[0]); idx=1;}
    let rest:String=chars[idx..].iter().collect();
    let (width_s, prec_s)=match rest.split_once('.') {Some((a,b))=>(a,Some(b)),None=>(rest.as_str(),None)};
    let width:usize=width_s.parse().unwrap_or(0);
    let mut val=value.to_string();
    if let Some(p)=prec_s {
        if let Ok(prec)=p.parse::<usize>() {
            if val.chars().count()>prec {val=val.chars().take(prec).collect();}
        }
    }
    let val_width=display_width(&val);
    if width<=val_width {return val;}
    let pad=width-val_width;
    match align {
        Some('>')=>format!("{}{}",fill.to_string().repeat(pad),val),
        Some('^')=>{
            // delta center: extra padding on left
            let left=(pad+1)/2; let right=pad-left;
            format!("{}{}{}",fill.to_string().repeat(left),val,fill.to_string().repeat(right))
        }
        _=>format!("{}{}",val,fill.to_string().repeat(pad)),
    }
}
pub struct FormatPart { pub literal_before:String, pub placeholder:Option<(String,String)> } // (name,spec)
// Parse a format string into literal/placeholder segments preserving order to allow different painting for placeholder fields.
// Returns Vec of segments either literal (placeholder None with literal_before = text) - simpler custom struct below.
#[derive(Clone,Debug)]
pub enum FmtSeg { Lit(String), Field(String,String) }
pub fn parse_format(fmt:&str)->Vec<FmtSeg>{
    let mut segs=Vec::new(); let mut lit=String::new(); let chars:Vec<char>=fmt.chars().collect(); let mut i=0;
    while i<chars.len() {
        if chars[i]=='{' {
            if i+1<chars.len() && chars[i+1]=='{' {lit.push('{'); i+=2; continue;}
            // find }
            let mut j=i+1; while j<chars.len() && chars[j]!='}' {j+=1;}
            if j>=chars.len() {lit.push(chars[i]); i+=1; continue;}
            if !lit.is_empty() {segs.push(FmtSeg::Lit(std::mem::take(&mut lit)));}
            let inside:String=chars[i+1..j].iter().collect();
            let (name,spec)=match inside.split_once(':') {Some((a,b))=>(a.to_string(),b.to_string()),None=>(inside,String::new())};
            segs.push(FmtSeg::Field(name,spec)); i=j+1;
        } else if chars[i]=='}' && i+1<chars.len() && chars[i+1]=='}' {lit.push('}'); i+=2;}
        else {lit.push(chars[i]); i+=1;}
    }
    if !lit.is_empty() {segs.push(FmtSeg::Lit(lit));}
    segs
}
pub fn apply_format(fmt:&str, values:&HashMap<String,String>)->String{
    let mut out=String::new();
    for seg in parse_format(fmt) {
        match seg {FmtSeg::Lit(s)=>out.push_str(&s),FmtSeg::Field(name,spec)=>out.push_str(&format_field(values.get(&name).map(|s|s.as_str()).unwrap_or(""),&spec)),}
    }
    out
}
// Decoration
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum DecorationKind { None, Box, BoxUnderline, Underline, Overline, UnderOverline }
pub fn decoration_kind(style:&Style)->DecorationKind{
    let has_box=style.has_box;
    let has_ul=style.underline;
    let has_ol=style.has_ol;
    match (has_box,has_ul,has_ol) {
        (true,true,false)=>DecorationKind::BoxUnderline,
        (true,_,_)=>DecorationKind::Box,
        (false,true,true)=>DecorationKind::UnderOverline,
        (false,true,false)=>DecorationKind::Underline,
        (false,false,true)=>DecorationKind::Overline,
        _=>DecorationKind::None,
    }
}
// Emit decorated text lines (without trailing newline per line in vec). Painted text is a function returning painted main text line.
// width_for_decoration: for ul/ol decorations is decoration width (fixed or text width if variable); for box, box width is text width + 1 (trailing space) unless no trailing space flag is used by merge conflict no-ancestor headers.
pub fn decorated_lines<F:Fn()->String>(paint_main:F, main_plain_text:&str, deco_style:&Style, cfg:&Config, box_trailing_space:bool)->Vec<String>{
    let kind=decoration_kind(deco_style);
    let is_bold=deco_style.bold;
    let h_char=if is_bold {"━"} else {"─"};
    let v_char=if is_bold {"┃"} else {"│"};
    let tr=if is_bold {"┓"} else {"┐"};
    let br=if is_bold {"┛"} else {"┘"};
    let br_ul=if is_bold {"┻"} else {"┴"};
    let deco_paint=|text:&str| -> String {
        // Decoration fragments are painted as standalone segments in reference (dashes segment and corner segment separate). Caller builds them separately.
        paint_with_style(deco_style,text,None)
    };
    let deco_width:usize = match cfg.width_spec { crate::config::WidthSpec::Fixed(n)=>n, crate::config::WidthSpec::Variable=>display_width(main_plain_text) };
    match kind {
        DecorationKind::None=>vec![paint_main()],
        DecorationKind::Underline=>{
            vec![paint_main(), deco_paint(&h_char.repeat(deco_width))]
        }
        DecorationKind::Overline=>{
            vec![deco_paint(&h_char.repeat(deco_width)), paint_main()]
        }
        DecorationKind::UnderOverline=>{
            vec![deco_paint(&h_char.repeat(deco_width)), paint_main(), deco_paint(&h_char.repeat(deco_width))]
        }
        DecorationKind::Box|DecorationKind::BoxUnderline=>{
            let text_width=display_width(main_plain_text);
            let box_inner = if box_trailing_space {text_width+0} else {text_width};
            // Reference: main text passed includes a trailing space in most cases (file: "f.txt " rendered with trailing space before box edge). Callers construct main_plain_text accordingly: for normal decorated sections, the painter adds a trailing space to text before box. To avoid double, convention here: paint_main/main_plain_text passed to this function should already include any desired trailing space. box_inner = text_width.
            let top_dashes=h_char.repeat(box_inner);
            let top=format!("{}{}",deco_paint(&top_dashes),deco_paint(tr));
            let middle=format!("{}{}",paint_main(),deco_paint(v_char));
            let bottom=if kind==DecorationKind::BoxUnderline {
                if deco_width>box_inner {
                    format!("{}{}{}",deco_paint(&top_dashes),deco_paint(br_ul),deco_paint(&h_char.repeat(deco_width-box_inner-1)))
                } else { format!("{}{}",deco_paint(&top_dashes),deco_paint(br)) }
            } else { format!("{}{}",deco_paint(&top_dashes),deco_paint(br)) };
            let _=box_trailing_space;
            vec![top,middle,bottom]
        }
    }
}
