use regex::Regex;

#[derive(Clone,Debug,PartialEq,Eq)]
pub struct Token { pub text:String, pub start:usize, pub end:usize } // char indices in line

pub fn tokenize(line:&str, word_regex:&Regex)->Vec<Token>{
    let chars:Vec<char>=line.chars().collect();
    let mut tokens:Vec<Token>=Vec::new();
    let mut last_char_idx=0usize;
    // Map byte index to char index via char_indices list
    let char_starts:Vec<usize>=line.char_indices().map(|(i,_)|i).chain([line.len()]).collect();
    let byte_to_char=|b:usize| -> usize { char_starts.iter().position(|x|*x==b).unwrap_or(chars.len()) };
    for m in word_regex.find_iter(line) {
        if m.start()==m.end() {continue;}
        let s=byte_to_char(m.start()); let e=byte_to_char(m.end());
        let mut p=last_char_idx;
        while p<s { tokens.push(Token{text:chars[p].to_string(),start:p,end:p+1}); p+=1; }
        tokens.push(Token{text:m.as_str().to_string(),start:s,end:e});
        last_char_idx=e;
    }
    let mut p=last_char_idx;
    while p<chars.len() { tokens.push(Token{text:chars[p].to_string(),start:p,end:p+1}); p+=1; }
    tokens
}

#[derive(Clone,Debug,PartialEq,Eq)]
pub enum Op { Match(usize,usize), Delete(usize), Insert(usize) } // indices into minus/plus tokens

pub fn align_tokens(a:&[Token], b:&[Token])->Vec<Op>{
    // Trim common prefix/suffix to reduce DP
    let mut prefix=0;
    while prefix<a.len() && prefix<b.len() && a[prefix].text==b[prefix].text {prefix+=1;}
    let mut suffix=0;
    while suffix<a.len()-prefix && suffix<b.len()-prefix && a[a.len()-1-suffix].text==b[b.len()-1-suffix].text {suffix+=1;}
    let a_mid=&a[prefix..a.len()-suffix];
    let b_mid=&b[prefix..b.len()-suffix];
    let mut ops:Vec<Op>=Vec::new();
    for i in 0..prefix {ops.push(Op::Match(i,i));}
    ops.extend(align_tokens_dp(a_mid,b_mid,prefix,prefix));
    for k in 0..suffix {
        ops.push(Op::Match(a.len()-suffix+k,b.len()-suffix+k));
    }
    ops
}
fn align_tokens_dp(a:&[Token],b:&[Token],a_off:usize,b_off:usize)->Vec<Op>{
    let n=a.len(); let m=b.len();
    if n==0 { return (0..m).map(|j|Op::Insert(b_off+j)).collect(); }
    if m==0 { return (0..n).map(|i|Op::Delete(a_off+i)).collect(); }
    // LCS lengths DP (n+1 x m+1)
    let mut dp:Vec<Vec<u32>>=vec![vec![0;m+1];n+1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            dp[i][j]=if a[i].text==b[j].text {dp[i+1][j+1]+1} else {std::cmp::max(dp[i+1][j],dp[i][j+1])};
        }
    }
    let mut ops=Vec::new(); let mut i=0; let mut j=0;
    while i<n && j<m {
        if a[i].text==b[j].text {ops.push(Op::Match(a_off+i,b_off+j)); i+=1; j+=1;}
        else if dp[i+1][j]>=dp[i][j+1] {ops.push(Op::Delete(a_off+i)); i+=1;}
        else {ops.push(Op::Insert(b_off+j)); j+=1;}
    }
    while i<n {ops.push(Op::Delete(a_off+i)); i+=1;}
    while j<m {ops.push(Op::Insert(b_off+j)); j+=1;}
    ops
}
fn is_ws_token(t:&Token)->bool{ !t.text.is_empty() && t.text.chars().all(|c|c.is_whitespace()) }
fn token_char_len(t:&Token)->usize{ t.text.chars().count() }

pub fn distance_and_ops(a_line:&str,b_line:&str,word_regex:&Regex)->(f64,Vec<Token>,Vec<Token>,Vec<Op>){
    let a=tokens_cached(a_line,word_regex); let b=tokens_cached(b_line,word_regex);
    let ops=align_tokens(&a,&b);
    let d=compute_distance(&a,&b,&ops);
    (d,a,b,ops)
}
pub fn tokens_cached(line:&str, word_regex:&Regex)->Vec<Token>{ tokenize(line,word_regex) }
pub fn compute_distance(a:&[Token],b:&[Token],ops:&[Op])->f64{
    // Group ops into sections: maximal matches vs maximal changes
    #[derive(Clone)] enum Sec { Eq(Vec<usize>), Change(Vec<usize>,Vec<usize>) } // token indices (matches use a idx), deletes a, inserts b
    let mut secs:Vec<Sec>=Vec::new();
    for op in ops {
        match op {
            Op::Match(ai,_)=>{
                if let Some(Sec::Eq(v))=secs.last_mut() {v.push(*ai);} else {secs.push(Sec::Eq(vec![*ai]));}
            }
            Op::Delete(ai)=>{
                if let Some(Sec::Change(d,_))=secs.last_mut() {d.push(*ai);} else {secs.push(Sec::Change(vec![*ai],vec![]));}
            }
            Op::Insert(bi)=>{
                if let Some(Sec::Change(_,ins))=secs.last_mut() {ins.push(*bi);} else {secs.push(Sec::Change(vec![],vec![*bi]));}
            }
        }
    }
    let total_secs=secs.len();
    let mut common_counted:usize=0;
    let mut changed_counted:usize=0;
    for (idx,sec) in secs.into_iter().enumerate() {
        match sec {
            Sec::Eq(mut v)=>{
                // trim whitespace tokens at left if not first section, at right if not last
                if idx>0 {
                    while v.first().map(|i|is_ws_token(&a[*i])).unwrap_or(false) {v.remove(0); if v.is_empty() {break;}}
                }
                if idx+1<total_secs {
                    while v.last().map(|i|is_ws_token(&a[*i])).unwrap_or(false) {v.pop(); if v.is_empty() {break;}}
                }
                common_counted+=v.iter().map(|i|token_char_len(&a[*i])).sum::<usize>();
            }
            Sec::Change(mut d,mut ins)=>{
                // Trim whitespace tokens from edges of each list
                let trim_list=|v:&mut Vec<usize>, toks:&[Token]|{
                    while v.first().map(|i|is_ws_token(&toks[*i])).unwrap_or(false) {v.remove(0);}
                    while v.last().map(|i|is_ws_token(&toks[*i])).unwrap_or(false) {v.pop();}
                };
                trim_list(&mut d,a); trim_list(&mut ins,b);
                changed_counted+=d.iter().map(|i|token_char_len(&a[*i])).sum::<usize>();
                changed_counted+=ins.iter().map(|i|token_char_len(&b[*i])).sum::<usize>();
            }
        }
    }
    let denom=changed_counted + 2*common_counted;
    if denom==0 {0.0} else {changed_counted as f64 / denom as f64}
}
// Returns emph char ranges (start,end) for minus and plus tokens not matched.
pub fn emph_ranges(a:&[Token],b:&[Token],ops:&[Op])->(Vec<bool>,Vec<bool>){
    // bool per char index in respective line (caller knows char len)
    // Here return bool per token instead as vec aligned to tokens, caller map to ranges.
    let mut ma=vec![false;a.len()]; let mut mb=vec![false;b.len()];
    for op in ops { match op {Op::Delete(i)=>ma[*i]=true,Op::Insert(j)=>mb[*j]=true,Op::Match(_,_)=>{}} }
    (ma,mb)
}

// Pair minus/plus lines in a block. lines are code strings. Returns Vec of (minus_idx, plus_idx) pairs (indices local to input slices).
pub fn pair_lines(minus:&[String], plus:&[String], word_regex:&Regex, max_distance:f64)->Vec<(usize,usize)>{
    let n=minus.len(); let m=plus.len();
    if n==0||m==0 {return Vec::new();}
    // Tokenize each line once
