    for m in word_regex.find_iter(line) {
        if m.start()==m.end() {continue;}
        let s=byte_to_char(m.start()); let e=byte_to_char(m.end());
        let mut p=last_char_idx;
        while p<s { tokens.push(Token{text:chars[p].to_string(),start:p,end:p+1}); p+=1; }
        tokens.push(Token{text:m.as_str().to_string(),start:s,end:e});
        last_char_idx=e;
    }
    let mut p=last_char_idx;
    while p<chars.len() { tokens.push(Token{text:chars[p].to_string(),start:p,end:p+1}); p+=1; }
    tokens
}

#[derive(Clone,Debug,PartialEq,Eq)]
