    let a_mid=&a[prefix..a.len()-suffix];
    let b_mid=&b[prefix..b.len()-suffix];
    let mut ops:Vec<Op>=Vec::new();
    for i in 0..prefix {ops.push(Op::Match(i,i));}
    ops.extend(align_tokens_dp(a_mid,b_mid,prefix,prefix));
    for k in 0..suffix {
        ops.push(Op::Match(a.len()-suffix+k,b.len()-suffix+k));
    }
