        if !self.cfg.hunk_label.is_empty() {
            painted.push_str(&paint_with_style(&self.cfg.hunk_header_line_number_style,&self.cfg.hunk_label,None));
            painted.push(' ');
            plain.push_str(&self.cfg.hunk_label); plain.push(' ');
        }
        if style.has_file {
            let path=self.current_file_display_path_for_hunk();
            painted.push_str(&paint_with_style(&self.cfg.hunk_header_file_style,&path,None));
            painted.push(':'); plain.push_str(&path); plain.push(':');
        }
        if style.has_line_number {
            let num=h.plus_start.to_string();
            let seg=paint_with_style(&self.cfg.hunk_header_line_number_style,&num,None);
            if self.cfg.hyperlinks {
                let url=self.file_hyperlink_url(&self.current_file_display_path_for_hunk(),Some(h.plus_start),true);
                painted.push_str(&format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\",url,seg));
            } else {painted.push_str(&seg);}
            painted.push(':'); plain.push_str(&num); plain.push(':');
        }
        // Code context segment: h.code_context is text after closing @@ (includes leading space if present), plus append a trailing space.
        let mut code_seg=h.code_context.clone();
        code_seg.push(' ');
        plain.push_str(&code_seg);
        if style.fg==Fg::Syntax {
            // syntax tokenize code_seg as a line (fresh state)
            let mut st=SynState::Normal;
            let toks=syntax::tokenize_line(&code_seg,&self.lang_kind,&mut st);
            let mut secs:Vec<PaintSection>=Vec::new();
            for (text,cat) in toks {
                let syncol=self.palette.map(|p|p.colors[cat].to_color(self.cfg.true_color));
                secs.push(PaintSection{style:ConcreteStyle::from_style_resolved(style,syncol),text});
            }
            painted.push_str(&paint_sections_to_string(&secs));
        } else {
            painted.push_str(&paint_with_style(style,&code_seg,None));
        }
        (painted,plain)
    }
    fn current_file_display_path_for_hunk(&self)->String{
        if let Some(meta)=&self.file_meta {
            // Display path used in hunk header (file component): plus path stripped a/b for git, transformed & relativized
            let (minus,plus)=self.display_paths(meta);
            if meta.removed {return minus;}
            return plus;
        }
        String::new()
    }
    fn display_paths(&self,meta:&FileMeta)->(String,String){
        let mut minus=meta.minus_path.clone().unwrap_or_default();
        let mut plus=meta.plus_path.clone().unwrap_or_default();
        if !meta.is_unified {
            if let Some(s)=minus.strip_prefix("a/") {minus=s.to_string();}
            if let Some(s)=plus.strip_prefix("b/") {plus=s.to_string();}
        }
        minus=self.transform_file_path(&minus);
        plus=self.transform_file_path(&plus);
        (minus,plus)
    }
    fn transform_file_path(&self,path:&str)->String{
        let mut p=path.to_string();
        if let Some(sed)=&self.cfg.file_transformation { p=apply_sed_transformation(&p,sed); }
        if self.cfg.relative_paths { p=relativize_path(&p); }
        p
    }
    fn file_hyperlink_url(&self,display_path:&str,line:Option<usize>,_for_line_number:bool)->String{
        let fmt=&self.cfg.hyperlinks_file_link_format;
        // Original path before transformation? For url, reference uses absolute path built from actual file path (not transformed display?). We use display path joined to cwd if relative.
        let abs = if std::path::Path::new(display_path).is_absolute() {display_path.to_string()} else {
            let cwd=std::env::current_dir().unwrap_or_else(|_|std::path::PathBuf::from("/"));
            format!("{}/{}",cwd.display(),display_path)
        };
        let host=hostname_string();
        fmt.replace("{path}",&abs).replace("{line}",&line.unwrap_or(1).to_string()).replace("{host}",&host)
    }
    fn emit_file_header(&mut self){
        let mut meta = match self.file_meta.clone() {Some(m)=>m,None=>return};
        if meta.header_emitted {return;}
        meta.header_emitted=true; self.file_meta=Some(meta.clone());
        if self.color_only_effective() {return;}
        // File section always preceded by blank line
        self.emit(String::new());
        if self.cfg.file_style.is_omit {return;}
        // submodule title special
        let (title_plain, title_painted) = if let Some(t)=&meta.submodule_title {
            (t.clone(), paint_with_style(&self.cfg.file_style,t,None))
        } else {
            self.build_file_title(&meta)
        };
        // If decoration is box, append a trailing space inside the file_style painted segment. Our build_file_title returns one segment for non-hyperlinks; for hyperlinks there are OSC sequences but a trailing space should be inside colour segment before reset. Simpler: if box, rebuild painted by inserting space before final reset if present.
        let kind=decoration_kind(&self.cfg.file_decoration_style);
        let (painted,plain)=if matches!(kind,DecorationKind::Box|DecorationKind::BoxUnderline) {
            (insert_before_final_reset(&title_painted," "), format!("{} ",title_plain))
        } else {(title_painted,title_plain)};
        let lines=decorated_lines(&painted,&plain,&self.cfg.file_decoration_style,&self.cfg);
        for l in lines {self.emit(l);}
    }
    fn build_file_title(&self,meta:&FileMeta)->(String,String){
        let (minus_disp,plus_disp)=self.display_paths(meta);
        let raw_minus=meta.minus_path.clone().unwrap_or_default();
        let raw_plus=meta.plus_path.clone().unwrap_or_default();
        let is_added=meta.added || raw_minus=="/dev/null";
        let is_removed=meta.removed || raw_plus=="/dev/null";
        let label = if is_added {&self.cfg.file_added_label} else if is_removed {&self.cfg.file_removed_label} else if meta.renamed {&self.cfg.file_renamed_label} else if meta.copied {&self.cfg.file_copied_label} else {&self.cfg.file_modified_label};
        let mut suffix=String::new();
        if let (Some(old),Some(new))=(meta.old_mode.clone(),meta.new_mode.clone()) {
            if old!=new {
                if old=="100644" && new=="100755" {suffix.push_str(" (mode +x)");}
                else if old=="100755" && new=="100644" {suffix.push_str(" (mode -x)");}
                else {suffix.push_str(&format!(" (mode {} => {})",old,new));}
            }
        }
        if meta.binary {suffix.push_str(" (binary file)");}
        // Title path part construction with hyperlink awareness
        let mut plain=String::new();
        let mut painted_inner=String::new(); // without outer file_style codes, but with hyperlink OSC sequences inserted; outer paint applied differently if hyperlinks.
        // We'll construct segments: Vec<(text, Option<url>)>
        let mut segs:Vec<(String,Option<String>)>=Vec::new();
        if !label.is_empty() { segs.push((format!("{} ",label),None)); }
        if is_added {
            segs.push((plus_disp.clone(),Some(plus_disp.clone())));
        } else if is_removed {
            segs.push((minus_disp.clone(),Some(minus_disp.clone())));
        } else if minus_disp==plus_disp {
            segs.push((plus_disp.clone(),Some(plus_disp.clone())));
        } else if minus_disp.is_empty() && !plus_disp.is_empty() {
            segs.push((plus_disp.clone(),Some(plus_disp.clone())));
        } else if plus_disp.is_empty() && !minus_disp.is_empty() {
            segs.push((minus_disp.clone(),Some(minus_disp.clone())));
        } else {
            segs.push((minus_disp.clone(),Some(minus_disp.clone())));
            segs.push((format!(" {} ",self.cfg.right_arrow),None));
            segs.push((plus_disp.clone(),Some(plus_disp.clone())));
        }
        if !suffix.is_empty() {segs.push((suffix.clone(),None));}
        for (txt,_) in &segs {plain.push_str(txt);}
        let painted = if self.cfg.hyperlinks {
            // Outer colour wraps entire title: prefix codes, segments with OSC, then reset. If file style plain, still segments with OSC and no colour? paint_with_style would give no prefix/reset. Build manually.
            let conc=ConcreteStyle::from_style_resolved(&self.cfg.file_style,None);
            let mut s=String::new();
            s.push_str(&conc.prefix_full());
            for (txt,path) in segs {
                if let Some(p)=path {
                    let url=self.file_hyperlink_url(&p,None,false);
                    s.push_str(&format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\",url,txt));
                } else {s.push_str(&txt);}
            }
            if !conc.is_plain() {s.push_str("\x1b[0m");}
            s
        } else {
            paint_with_style(&self.cfg.file_style,&plain,None)
        };
        (plain,painted)
    }
    fn emit_commit_line(&mut self,raw_line:&str,stripped:&str){
        self.flush_buffer();
        if self.file_meta.is_some() && !self.color_only_effective() { self.emit_file_header(); }
        self.file_meta=None; self.hunk=None; self.state=State::Unknown;
        if self.cfg.color_only_effective() {
            if self.cfg.commit_style.is_raw { self.emit_raw_line(raw_line); }
            else if !self.cfg.commit_style.is_omit { self.emit(paint_with_style(&self.cfg.commit_style,stripped,None)); }
            return;
        }
        if self.cfg.commit_style.is_omit {return;}
        let painted = if self.cfg.commit_style.is_raw {
            // Preserve original colours, but hyperlinks may transform hash segment. For now: if hyperlinks, insert link around hash in stripped/painted? Raw line may have ANSI segments; reference does link hash while keeping raw colours. Implement in hyperlink handling pass below by operating on stripped if hyperlinks and raw has no ... We'll handle a common case.
            if self.cfg.hyperlinks { self.paint_commit_with_hyperlink(raw_line,stripped) } else { raw_line.to_string() }
        } else {
            if self.cfg.hyperlinks { self.paint_commit_with_hyperlink_styled(stripped) } else { paint_with_style(&self.cfg.commit_style,stripped,None) }
        };
        let kind=decoration_kind(&self.cfg.commit_decoration_style);
        let (p,plain)=if matches!(kind,DecorationKind::Box|DecorationKind::BoxUnderline) {
            if self.cfg.commit_style.is_raw && ansi::has_ansi(raw_line) {
                // trailing space before box should be inside raw paint? Approximation: append space after raw line (reset issues) - callers with no ansi handled by insert_before_final_reset
                (format!("{} ",painted),format!("{} ",stripped))
            } else {
                (insert_before_final_reset(&painted," "),format!("{} ",stripped))
            }
        } else {(painted,stripped.to_string())};
        let lines=decorated_lines(&p,&plain,&self.cfg.commit_decoration_style,&self.cfg);
        for l in lines {self.emit(l);}
    }
    fn commit_hash_and_rest<'a>(&self,stripped:&'a str)->Option<(&'a str,&'a str,&'a str)>{
        // commit line typically "commit <hash> ..." The commit_regex may be custom; hash is first token after match end.
        let m=self.cfg.commit_regex.find(stripped)?;
        let after=&stripped[m.end()..];
        let hash_end=after.find(|c:char|c.is_whitespace()).unwrap_or(after.len());
        Some((&stripped[..m.end()],&after[..hash_end],&after[hash_end..]))
    }
    fn commit_hyperlink_url(&self,hash:&str)->String{
        if let Some(fmt)=&self.cfg.hyperlinks_commit_link_format {
            return fmt.replace("{commit}",hash);
        }
        // Determine from git remote of repo in cwd
        if let Some(url)=crate::hyperlink_remote_url(hash) {return url;}
        String::new()
    }
    fn paint_commit_with_hyperlink(&self,raw_line:&str,stripped:&str)->String{
        // If raw line has no ANSI, simple: wrap hash token
        if !ansi::has_ansi(raw_line) {
            if let Some((pre,hash,rest))=self.commit_hash_and_rest(stripped) {
                let url=self.commit_hyperlink_url(hash);
                if url.is_empty() {return raw_line.to_string();}
                return format!("{}\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\{}",pre,url,hash,rest);
            }
            return raw_line.to_string();
        }
        // With ANSI: reconstruct sections, wrap the hash characters. Simplification: paint stripped with raw sections re-applied via sections and insert OSC around hash text characters in painted stream - difficult. We'll rebuild from raw sections character-wise.
        let secs=ansi::parse_sections(raw_line,self.cfg.true_color==false&&false); // preserve colours as parsed
        let mut out=String::new(); let mut painter=StylePainter::new();
        let Some((pre,hash,rest))=self.commit_hash_and_rest(stripped) else {return raw_line.to_string();};
        let url=self.commit_hyperlink_url(hash); if url.is_empty() {return raw_line.to_string();}
        let hash_start=pre.chars().count(); let hash_end=hash_start+hash.chars().count();
        let mut pos=0usize;
        let mut link_open=false;
        for sec in secs {
            let mut remaining=sec.text.clone();
            let sec_len=remaining.chars().count();
            let mut offset=0;
            while offset<sec_len {
                let cur=pos+offset;
                let boundary = if cur<hash_start {hash_start} else if cur<hash_end {hash_end} else {pos+sec_len};
                let take=boundary-cur;
                let chunk:String=remaining.chars().skip(offset).take(take).collect();
                if cur==hash_start && !link_open { out.push_str(&format!("\x1b]8;;{}\x1b\\",url)); link_open=true; }
                if cur>=hash_end && link_open { out.push_str("\x1b]8;;\x1b\\"); link_open=false; }
                painter.transition_to(&ConcreteStyle::from_raw_style(&sec.style),&mut out);
                out.push_str(&chunk);
                offset+=take;
            }
            pos+=sec_len;
        }
        if link_open {out.push_str("\x1b]8;;\x1b\\");}
        painter.finish(&mut out);
        let _=rest; out
    }
    fn paint_commit_with_hyperlink_styled(&self,stripped:&str)->String{
        if let Some((pre,hash,rest))=self.commit_hash_and_rest(stripped) {
            let url=self.commit_hyperlink_url(hash);
            if !url.is_empty() {
                let conc=ConcreteStyle::from_style_resolved(&self.cfg.commit_style,None);
                let mut s=String::new(); s.push_str(&conc.prefix_full());
                s.push_str(pre); s.push_str(&format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\",url,hash)); s.push_str(rest);
                if !conc.is_plain() {s.push_str("\x1b[0m");}
                return s;
            }
        }
        paint_with_style(&self.cfg.commit_style,stripped,None)
    }
}
pub fn insert_before_final_reset(painted:&str, insert:&str)->String{
    if let Some(pos)=painted.rfind("\x1b[0m") {
        let mut s=painted.to_string(); s.insert_str(pos,insert); s
    } else { format!("{}{}",painted,insert) }
}
pub fn is_structural_start(stripped:&str,cfg:&Config)->bool{
    cfg.commit_regex.is_match(stripped) || stripped.starts_with("diff --git ")||stripped.starts_with("diff --cc ")||stripped.starts_with("diff --combined ")||(stripped.starts_with("--- ") )||stripped.starts_with("@@")
}
pub fn parse_submodule_header(stripped:&str)->Option<String>{
    // "Submodule <name> <...>:"
    if stripped.starts_with("Submodule ") && stripped.ends_with(':') && stripped.split_whitespace().count()>=3 {
        return Some(stripped.to_string());
    }
    None
}
pub fn parse_diff_git_line(stripped:&str)->Option<FileMeta>{
    let mut meta=FileMeta::default(); meta.has_diff_line=true;
    let rest: &str;
    if let Some(r)=stripped.strip_prefix("diff --cc ") {meta.is_combined=true; rest=r;}
    else if let Some(r)=stripped.strip_prefix("diff --combined ") {meta.is_combined=true; rest=r;}
    else if let Some(r)=stripped.strip_prefix("diff --git ") {rest=r;}
    else {return None;}
    // Combined has a single path (usually without a/b? Actually diff --cc src/file)
    if meta.is_combined {
        let p=parse_c_quoted_or_plain(rest.trim());
        meta.minus_path=Some(p.clone()); meta.plus_path=Some(p);
        return Some(meta);
    }
    let (a,b)=split_diff_git_paths(rest.trim());
    meta.minus_path=a; meta.plus_path=b;
    Some(meta)
}
fn split_diff_git_paths(rest:&str)->(Option<String>,Option<String>){
    // Quoted pair
    if rest.starts_with('"') {
        // parse two C-quoted strings if possible
        let mut vals=Vec::new(); let mut cur=rest;
        for _ in 0..2 {
            cur=cur.trim_start();
            if let Some((v,rem))=parse_c_quoted_prefix(cur) {vals.push(v); cur=rem;} else {break;}
        }
        if vals.len()==2 {return (Some(vals[0].clone()),Some(vals[1].clone()));}
    }
    // Preferred: find " b/" separator if first path starts "a/"
    if rest.starts_with("a/") {
        if let Some(idx)=rest.find(" b/") {
            // If there are multiple, this may be ambiguous; subsequent ---/+++ overrides usually.
            return (Some(rest[..idx].to_string()),Some(rest[idx+1..].to_string()));
        }
    }
    // No prefix: if the string is two copies of same path with a space, split at point where halves equal
    // Find a split position at a space such that left==right
    for (idx,ch) in rest.char_indices() {
        if ch==' ' {
            let l=&rest[..idx]; let r=&rest[idx+1..]; if l==r {return (Some(l.to_string()),Some(r.to_string()));}
        }
    }
    // Fallback split at last space? For paths without spaces, split at first space. For spaces, subsequent headers fix it.
    if let Some(idx)=rest.find(' ') {
        return (Some(rest[..idx].to_string()),Some(rest[idx+1..].to_string()));
    }
    (Some(rest.to_string()),Some(rest.to_string()))
}
fn parse_c_quoted_prefix(s:&str)->Option<(String,&str)>{
    if !s.starts_with('"') {return None;}
    let mut out:Vec<u8>=Vec::new(); let bytes=s.as_bytes(); let mut i=1;
    while i<bytes.len() {
        match bytes[i] {
            b'"'=>{ return Some((String::from_utf8_lossy(&out).to_string(),&s[i+1..])); }
            b'\\' => {
                if i+1>=bytes.len() {return None;}
                let c=bytes[i+1] as char; i+=2;
                match c { 'n'=>out.push(b'\n'),'t'=>out.push(b'\t'),'\\'=>out.push(b'\\'),'"'=>out.push(b'"'),
                    '0'..='7'=>{
                        // up to 3 octal digits total including first
                        let mut val=(c as u8)-b'0'; let mut count=1;
                        while count<3 && i<bytes.len() && (b'0'..=b'7').contains(&bytes[i]) {val=val*8+(bytes[i]-b'0'); i+=1; count+=1;}
                        out.push(val);
                    }
                    _=>{out.push(b'\\'); out.extend_from_slice(c.to_string().as_bytes());}
                }
            }
            b=>{out.push(b); i+=1;}
        }
    }
    None
}
fn parse_c_quoted_or_plain(s:&str)->String{
    if s.starts_with('"') { if let Some((v,_))=parse_c_quoted_prefix(s) {return v;} }
    s.to_string()
}
pub fn parse_unified_path(s:&str)->Option<String>{
    let t=s.trim();
    if t.is_empty() {return None;}
    if t.starts_with('"') { if let Some((v,_))=parse_c_quoted_prefix(t) {return Some(v);} }
    // tab-separated timestamp
    let before_tab = match t.find('\t') {Some(i)=>&t[..i],None=>t};
    Some(before_tab.trim_end().to_string())
}
fn consume_meta_line(stripped:&str, meta:&mut Option<FileMeta>)->bool{
    let m=match meta {Some(x)=>x,None=>return false};
    if stripped.starts_with("index ") {return true;}
    if let Some(r)=stripped.strip_prefix("new file mode ") {m.added=true; m.new_mode=Some(r.trim().to_string()); return true;}
    if let Some(r)=stripped.strip_prefix("deleted file mode ") {m.removed=true; m.old_mode=Some(r.trim().to_string()); return true;}
    if let Some(r)=stripped.strip_prefix("old mode ") {m.old_mode=Some(r.trim().to_string()); return true;}
    if let Some(r)=stripped.strip_prefix("new mode ") {m.new_mode=Some(r.trim().to_string()); return true;}
    if stripped.starts_with("similarity index ")||stripped.starts_with("dissimilarity index ") {return true;}
    if let Some(r)=stripped.strip_prefix("rename from ") {m.renamed=true; m.minus_path=Some(r.trim().to_string()); return true;}
    if let Some(r)=stripped.strip_prefix("rename to ") {m.renamed=true; m.plus_path=Some(r.trim().to_string()); return true;}
    if let Some(r)=stripped.strip_prefix("copy from ") {m.copied=true; m.minus_path=Some(r.trim().to_string()); return true;}
    if let Some(r)=stripped.strip_prefix("copy to ") {m.copied=true; m.plus_path=Some(r.trim().to_string()); return true;}
    if stripped.starts_with("Binary files ") && stripped.ends_with(" differ") {
        m.binary=true;
        // Parse paths: Binary files <a> and <b> differ
        let inner=&stripped["Binary files ".len()..stripped.len()-" differ".len()];
        if let Some(idx)=inner.find(" and ") {
            let a=&inner[..idx]; let b=&inner[idx+5..];
            if a=="/dev/null" {m.added=true;} else {m.minus_path=Some(a.to_string());}
            if b=="/dev/null" {m.removed=true;} else {m.plus_path=Some(b.to_string());}
        }
        return true;
    }
    if stripped=="GIT binary patch" {m.binary=true; return true;}
    false
}
pub fn parse_hunk_header(stripped:&str,raw:&str)->Option<HunkState>{
    if !stripped.starts_with("@@") {return None;}
    // Find closing group of @
    let mut i=0; let chars:Vec<char>=stripped.chars().collect();
    while i<chars.len() && chars[i]=='@' {i+=1;}
    if i<2 {return None;}
    let is_combined=i>=3;
    // find next group
    let mut j=i; let mut closing_start:Option<usize>=None; let mut closing_end=0usize;
    while j<chars.len() {
        if chars[j]=='@' { let s=j; while j<chars.len()&&chars[j]=='@' {j+=1;} if j-s>=2 {closing_start=Some(s); closing_end=j; break;} } else {j+=1;}
    }
    let (header_part, code_context) = if let Some(cs)=closing_start {
        let byte_cs=stripped.char_indices().nth(cs).map(|x|x.0).unwrap_or(stripped.len());
        let byte_ce=stripped.char_indices().nth(closing_end).map(|x|x.0).unwrap_or(stripped.len());
        (&stripped[..byte_cs], stripped[byte_ce..].to_string())
    } else { (stripped,String::new()) };
    // Ensure header_part contains at least a -... and +... range to avoid recognising "@@" in text
    // Reference may recognise "@@ -1 +1 @@" etc. Use regex-like scan:
    let mut minus_start:Option<usize>=None; let mut plus_start:Option<usize>=None;
    for tok in header_part.split_whitespace() {
        if let Some(r)=tok.strip_prefix('-') {
            let num=r.split(',').next().unwrap_or("");
            if let Ok(n)=num.parse::<usize>() { if minus_start.is_none() {minus_start=Some(n);} }
        } else if let Some(r)=tok.strip_prefix('+') {
            let num=r.split(',').next().unwrap_or("");
            if let Ok(n)=num.parse::<usize>() { plus_start=Some(n); }
        }
    }
    if minus_start.is_none() && plus_start.is_none() {return None;}
    Some(HunkState{minus_start:minus_start.unwrap_or(1),plus_start:plus_start.unwrap_or(1),minus_counter:minus_start.unwrap_or(1),plus_counter:plus_start.unwrap_or(1),code_context,raw_line:raw.to_string(),header_emitted:false,header_suppressed:false,is_combined})
}
pub fn hostname_string()->String{
    std::fs::read_to_string("/proc/sys/kernel/hostname").map(|s|s.trim().to_string()).unwrap_or_default()
}
pub fn apply_sed_transformation(path:&str, sed:&str)->String{
    // Sed-style s/pattern/replacement/flags with arbitrary delimiter after s
    // Examples in delta docs: s/^(.*)\/src\/(.*)$/$2/ ??? Replacement syntax in Rust regex is $1 etc, and sed uses \1. Delta likely accepts sed replacements with $1?
    let chars:Vec<char>=sed.chars().collect();
