    fn prepare_code_line(&mut self,line:&str)->Option<CodeLine>{
        let stripped=ansi::strip_ansi(line);
        if stripped.is_empty() {return None;}
        let chars:Vec<char>=stripped.chars().collect();
        let is_combined=self.hunk.as_ref().map(|h|h.is_combined).unwrap_or(false)||self.file_meta.as_ref().map(|m|m.is_combined).unwrap_or(false);
