            if chars.len()<2 {return None;}
            let a=chars[0]; let b=chars[1];
            if !(a==' '||a=='+'||a=='-') || !(b==' '||b=='+'||b=='-') {return None;}
            let ty=if a=='-'||b=='-' {LineType::Minus} else if a=='+'||b=='+' {LineType::Plus} else {LineType::Zero};
            (chars[0..2].iter().collect(),ty,2)
        } else {
            let ty=match chars[0] {'-'=>LineType::Minus,'+'=>LineType::Plus,' '=>LineType::Zero,_=>return None};
            (chars[0].to_string(),ty,1)
        };
