        let (minus_no,plus_no)={
            let h=self.hunk.as_mut()?;
            let res=match ty {
                LineType::Minus=>{let n=h.minus_counter; h.minus_counter+=1; (Some(n),None)},
                LineType::Plus=>{let n=h.plus_counter; h.plus_counter+=1; (None,Some(n))},
                LineType::Zero=>{let a=h.minus_counter; let b=h.plus_counter; h.minus_counter+=1; h.plus_counter+=1; (Some(a),Some(b))},
            };
            res
        };
