        let limit=self.cfg.max_syntax_highlighting_length;
        let do_tokenize=|state:&mut SynState| -> Vec<(String,usize)> {
            if limit>0 && code.chars().count()>limit {
                let prefix:String=code.chars().take(limit).collect();
                let rest:String=code.chars().skip(limit).collect();
                let mut toks=syntax::tokenize_line(&prefix,&self.lang_kind,state);
                toks.push((rest,crate::syntax::CAT_PLAIN));
