        let minus=std::mem::take(&mut self.buf_minus);
        let plus=std::mem::take(&mut self.buf_plus);
        self.buf_phase_plus=false;
        if !self.color_only_effective() { self.emit_hunk_header_if_needed(); }
        if self.cfg.side_by_side && !self.color_only_effective() {
            let rows=self.paint_side_by_side_block(&minus,&plus);
            for r in rows {self.emit(r);}
            return;
        }
        // Compute pairings excluding raw lines from token alignment? Raw lines included in lists but their indices should not pair. We'll pair only non-raw subsets while preserving indices.
        let minus_codes:Vec<String>=minus.iter().map(|l|l.code.clone()).collect();
        let plus_codes:Vec<String>=plus.iter().map(|l|l.code.clone()).collect();
        // Build filtered index maps
        let m_idx:Vec<usize>=minus.iter().enumerate().filter(|(_,l)|!l.is_raw).map(|(i,_)|i).collect();
        let p_idx:Vec<usize>=plus.iter().enumerate().filter(|(_,l)|!l.is_raw).map(|(i,_)|i).collect();
        let mf:Vec<String>=m_idx.iter().map(|i|minus_codes[*i].clone()).collect();
        let pf:Vec<String>=p_idx.iter().map(|i|plus_codes[*i].clone()).collect();
        let pairs_filtered=align::pair_lines(&mf,&pf,&self.cfg.word_diff_regex,self.cfg.max_line_distance);
        let mut minus_emph:std::collections::HashMap<usize,Vec<bool>>=HashMap::new();
        let mut plus_emph:std::collections::HashMap<usize,Vec<bool>>=HashMap::new();
        let mut minus_paired:std::collections::HashSet<usize>=std::collections::HashSet::new();
        let mut plus_paired:std::collections::HashSet<usize>=std::collections::HashSet::new();
        for (fi,fj) in pairs_filtered {
            let (i,j)=(m_idx[fi],p_idx[fj]);
            minus_paired.insert(i); plus_paired.insert(j);
            let (_d,at,bt,ops)=align::distance_and_ops(&minus_codes[i],&plus_codes[j],&self.cfg.word_diff_regex);
            let (ma,mb)=align::emph_ranges(&at,&bt,&ops);
            // Convert token bool to char bool
            minus_emph.insert(i,tokens_to_char_bool(&at,&ma,minus_codes[i].chars().count()));
            plus_emph.insert(j,tokens_to_char_bool(&bt,&mb,plus_codes[j].chars().count()));
        }
        for (i,line) in minus.iter().enumerate() {
            let emph = if minus_paired.contains(&i) {Some((minus_emph.get(&i).cloned().unwrap_or_default(),true))} else {None};
            let painted=self.paint_code_line(line,emph.as_ref().map(|(v,p)|(v.clone(),*p)));
            self.emit(painted);
        }
        for (j,line) in plus.iter().enumerate() {
            let emph = if plus_paired.contains(&j) {Some((plus_emph.get(&j).cloned().unwrap_or_default(),true))} else {None};
            let painted=self.paint_code_line(line,emph.as_ref().map(|(v,p)|(v.clone(),*p)));
            self.emit(painted);
        }
    }
