        self.add_one_line_number_column(sections,&self.cfg.line_numbers_right_format,&self.cfg.line_numbers_right_style,line,false);
    }
    pub fn add_one_line_number_column(&self,sections:&mut Vec<PaintSection>,fmt:&str,col_style:&Style,line:&CodeLine,is_left:bool){
        let field_style = if line.ty==LineType::Zero {self.cfg.line_numbers_zero_style.clone()} else if is_left {self.cfg.line_numbers_minus_style.clone()} else {self.cfg.line_numbers_plus_style.clone()};
        for seg in parse_format(fmt) {
            match seg {
                FmtSeg::Lit(s)=>sections.push(PaintSection{style:ConcreteStyle::from_style_resolved(col_style,None),text:s}),
                FmtSeg::Field(name,spec)=>{
                    let val=match name.as_str() {"nm"=>line.minus_no.map(|n|n.to_string()).unwrap_or_default(),"np"=>line.plus_no.map(|n|n.to_string()).unwrap_or_default(),_=>String::new()};
