    pub fn append_code_sections(&self,line:&CodeLine,emph:Option<(Vec<bool>,bool)>,sections:&mut Vec<PaintSection>){
        let paired=emph.as_ref().map(|(_,p)|*p).unwrap_or(false);
        let emph_bool:Vec<bool>=emph.as_ref().map(|(v,_)|v.clone()).unwrap_or_default();
        // Marker
        if self.color_only_effective() || self.cfg.keep_plus_minus_markers || line.combined {
            let base=self.base_style_for(line.ty,false);
            let conc=ConcreteStyle::from_style_resolved(&base,None);
            sections.push(PaintSection{style:conc,text:line.marker.clone()});
        }
        if let Some(raw_secs)=&line.raw_code_sections {
            for sec in raw_secs {
                sections.push(PaintSection{style:ConcreteStyle::from_raw_style(&sec.style),text:sec.text.clone()});
            }
            return;
        }
        if let Some(mapped)=&line.mapped_sections {
            // TODO syntax refinement in mapped sections where original target style had syntax fg: our prebuilt uses plain colour for whole section.
            for s in mapped {sections.push(s.clone());}
            return;
        }
        // Whitespace error range for plus lines
        let ws_range:Option<(usize,usize)> = if line.ty==LineType::Plus {
            let chars:Vec<char>=line.code.chars().collect();
            if chars.is_empty() {None} else {
                let mut start=chars.len();
                while start>0 && (chars[start-1]==' '||chars[start-1]=='\t') {start-=1;}
                if start<chars.len() {Some((start,chars.len()))} else {None}
            }
        } else {None};
        // Merge syntax sections with emph/ws by character position
        // Build per-char category from syntax sections
        let mut per_char:Vec<(char,usize)>=Vec::new();
        for (text,cat) in &line.syntax { for c in text.chars() {per_char.push((c,*cat));} }
        // If syntax text length differs (trunc etc), fallback to code chars plain
        if per_char.len()!=line.code.chars().count() {
            per_char=line.code.chars().map(|c|(c,crate::syntax::CAT_PLAIN)).collect();
        }
        // Group consecutive chars with same (cat, emph flag, ws flag)
        let mut idx=0usize;
        while idx<per_char.len() {
            let cat=per_char[idx].1;
            let is_ws=ws_range.map(|(a,b)|idx>=a&&idx<b).unwrap_or(false);
            let is_emph=if paired { emph_bool.get(idx).cloned().unwrap_or(false)} else {false};
            let mut j=idx+1;
            while j<per_char.len() {
                let wsj=ws_range.map(|(a,b)|j>=a&&j<b).unwrap_or(false);
                let ej=if paired {emph_bool.get(j).cloned().unwrap_or(false)} else {false};
                if per_char[j].1!=cat || wsj!=is_ws || ej!=is_emph {break;}
                j+=1;
            }
            let text:String=per_char[idx..j].iter().map(|x|x.0).collect();
            let seg_style = if is_ws { self.cfg.whitespace_error_style.clone() } else { self.style_for_segment(line.ty,is_emph,paired) };
            let syncol=self.palette.map(|p|p.colors[cat].to_color(self.cfg.true_color));
            sections.push(PaintSection{style:ConcreteStyle::from_style_resolved(&seg_style,syncol),text});
            idx=j;
        }
    }
}
pub fn tokens_to_char_bool(tokens:&[align::Token], token_bool:&[bool], char_len:usize)->Vec<bool>{
