        let expanded=expand_tabs(&code_raw_stripped,self.cfg.tabs);
        let code=if self.cfg.side_by_side && !self.color_only_effective() {expanded} else {truncate_chars(&expanded,self.cfg.max_line_length)};
        // Syntax tokenization
        let syntax=self.tokenize_syntax(&code,ty);
        // Raw section handling
        let (raw_sections,mapped_sections,is_raw)=self.analyze_raw(line,&code_raw_stripped,ty,&code);
        Some(CodeLine{raw:line.to_string(),stripped:stripped.clone(),marker,code,ty,minus_no,plus_no,syntax,raw_code_sections:raw_sections,mapped_sections,is_raw,combined:is_combined})
    }
    fn tokenize_syntax(&mut self,code:&str,ty:LineType)->Vec<(String,usize)>{
        if self.cfg.syntax_theme.is_none() {return vec![(code.to_string(),crate::syntax::CAT_PLAIN)];}
        let limit=self.cfg.max_syntax_highlighting_length;
        let do_tokenize=|state:&mut SynState| -> Vec<(String,usize)> {
            if limit>0 && code.chars().count()>limit {
                let prefix:String=code.chars().take(limit).collect();
                let rest:String=code.chars().skip(limit).collect();
                let mut toks=syntax::tokenize_line(&prefix,&self.lang_kind,state);
                toks.push((rest,crate::syntax::CAT_PLAIN));
                toks
            } else { syntax::tokenize_line(code,&self.lang_kind,state) }
        };
        match ty {
            LineType::Minus=>do_tokenize(&mut self.syn_minus),
            LineType::Plus=>do_tokenize(&mut self.syn_plus),
            LineType::Zero=>{
                let toks=do_tokenize(&mut self.syn_plus);
                self.syn_minus=self.syn_plus.clone();
                toks
