            let (i,j)=(m_idx[fi],p_idx[fj]);
            minus_paired.insert(i); plus_paired.insert(j);
            let (_d,at,bt,ops)=align::distance_and_ops(&minus_codes[i],&plus_codes[j],&self.cfg.word_diff_regex);
            let (ma,mb)=align::emph_ranges(&at,&bt,&ops);
