            let is_emph=if paired { emph_bool.get(idx).cloned().unwrap_or(false)} else {false};
            let mut j=idx+1;
            while j<per_char.len() {
                let wsj=ws_range.map(|(a,b)|j>=a&&j<b).unwrap_or(false);
                let ej=if paired {emph_bool.get(j).cloned().unwrap_or(false)} else {false};
