pub fn tokens_to_char_bool(tokens:&[align::Token], token_bool:&[bool], char_len:usize)->Vec<bool>{
    let mut v=vec![false;char_len];
    for (t,b) in tokens.iter().zip(token_bool.iter()) {
        if *b { for i in t.start..t.end.min(char_len) {v[i]=true;} }
    }
