    }
}
pub fn repeat_to_width(symbol:&str,width:usize)->String{
    if symbol.is_empty() {return String::new();}
    let sw=display_width(symbol); if sw==0 {return String::new();}
    let mut s=String::new();
    while display_width(&s)<width {s.push_str(symbol); if s.chars().count()>100000 {break;}}
    // Truncate to width by display width (characters)
    let mut out=String::new(); let mut w=0;
    for c in s.chars() { let cw=unicode_width::UnicodeWidthChar::width(c).unwrap_or(0); if w+cw>width {break;} out.push(c); w+=cw; }
    out
}
RS
"}

