    fn blame_separator_parts(&self,line_no:usize,is_new_block:bool)->(String,String,String){
        let fmt=&self.cfg.blame_separator_format;
        if fmt=="none" {
            return (String::new(),String::new(),"│".to_string());
        }
        // Find one {n...} placeholder
        let segs=parse_format(fmt);
        let mut pre=String::new(); let mut post=String::new(); let mut field=String::new(); let mut seen=false;
        for seg in segs {
            match seg {
                FmtSeg::Lit(s)=>{ if seen {post.push_str(&s);} else {pre.push_str(&s);} }
                FmtSeg::Field(name,spec)=>{
                    if name!="n" { if seen {post.push_str(&format!("{{{}}}",name));} else {pre.push_str(&format!("{{{}}}",name));} continue; }
                    seen=true;
                    // spec may include _block or _every-N suffix
                    let (fmt_spec,typ) = match spec.rfind('_') {Some(p)=>(spec[..p].to_string(),Some(spec[p+1..].to_string())),None=>(spec.clone(),None)};
