                        Some("block")=>is_new_block,
                        Some(t) if t.starts_with("every-")=>{
                            let n:t_parse(t);
                            is_new_block || n.map(|n|n>0 && line_no % n == 1 % n.max(1)).unwrap_or(true)
                        }
                        _=>true,
                    };
                    let effective_spec=if fmt_spec.is_empty() {"^4".to_string()} else {fmt_spec};
                    field=if show {format_field(&line_no.to_string(),&effective_spec)} else {format_field("",&effective_spec)};
                }
            }
        }
        if !seen {
            // Entire format is suffix (pre should be empty per reference: fragments are "", "", fmt)
            return (String::new(),String::new(),pre);
        }
        (pre,field,post)
    }
}
fn t_parse(s:&str)->Option<usize>{ s.strip_prefix("every-")?.parse().ok() }
