                    let code_raw=json_path_text(data.get("lines"));
                    let code=code_raw.trim_end_matches('\n').trim_end_matches('\r').to_string();
                    let line_no=data.get("line_number").and_then(|x|x.as_u64()).map(|x|x as usize);
                    let mut ranges:Vec<(usize,usize)>=Vec::new();
                    if typ=="match" {
                        if let Some(arr)=data.get("submatches").and_then(|x|x.as_array()) {
                            for sm in arr {
                                let s=sm.get("start").and_then(|x|x.as_u64()).unwrap_or(0) as usize;
                                let e=sm.get("end").and_then(|x|x.as_u64()).unwrap_or(0) as usize;
                                // Convert byte offsets in code_raw to char indices in code (same prefix)
                                let cs=byte_to_char_idx(&code_raw,s); let ce=byte_to_char_idx(&code_raw,e);
                                ranges.push((cs,ce));
                            }
                        }
                    }
                    let gl=GrepLine{file,line_no,sep:if typ=="match" {':'} else {'-'},kind:if typ=="match" {GrepKind::Match} else {GrepKind::Context},code,match_ranges:ranges};
                    let rip = match self.cfg.grep_output_type.as_deref() {Some("classic")=>false, _=>true};
