                }
                "begin"|"end"|"summary"=>{},
                _=>{ self.emit_raw_line(line); }
            }
        }
    }
    fn handle_grep_line(&mut self,line:&str){
        let stripped=ansi::strip_ansi(line);
        if stripped=="--" { self.emit("--".to_string()); return; }
        match parse_classic_grep_line(line,&stripped) {
            Some(gl)=>{ let rip=self.grep_output_is_ripgrep(); self.emit_grep_line(gl,rip); }
            None=>self.emit_raw_line(line),
        }
    }
    fn emit_grep_line(&mut self,gl:GrepLine,ripgrep_output:bool){
        // Function-context header lines get special treatment in classic output, but in ripgrep they are treated after file header.
        if gl.kind==GrepKind::Header && !ripgrep_output {
            self.emit_grep_header(&gl);
            return;
        }
        if ripgrep_output {
            // file header on change
            if self.grep_file.as_deref()!=Some(gl.file.as_str()) {
                if self.grep_file.is_some() { self.emit(String::new()); }
                self.emit_grep_file_header(&gl.file);
