        out.push_str(&paint_with_style(&self.cfg.grep_file_style,&gl.file,None));
        let sep_str = if self.cfg.grep_separator_symbol=="keep" { gl.sep.to_string() } else { self.cfg.grep_separator_symbol.clone() };
        out.push_str(&sep_str);
        if let Some(n)=gl.line_no {
            let seg=paint_with_style(&self.cfg.grep_line_number_style,&n.to_string(),None);
            if self.cfg.hyperlinks {
                let url=self.file_hyperlink_url(&gl.file,Some(n),true);
                out.push_str(&format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\",url,seg));
            } else {out.push_str(&seg);}
            out.push_str(&sep_str);
            let digits=n.to_string().len();
            if digits<3 { out.push_str(&" ".repeat(3-digits)); }
