            let url=self.file_hyperlink_url(file,None,false);
            let seg=paint_with_style(&self.cfg.grep_file_style,file,None);
            s.push_str(&format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\",url,seg));
        } else {
            s.push_str(&paint_with_style(&self.cfg.grep_file_style,file,None));
