        if style.has_file {
            painted.push_str(&paint_with_style(&self.cfg.grep_header_file_style,&gl.file,None));
            painted.push('='); plain.push_str(&gl.file); plain.push('=');
            // Note: if both file and line-number are present, reference separator between them is '=' (original) rather than ':'.
        }
        if style.has_line_number {
            let num=gl.line_no.unwrap_or(0).to_string();
            painted.push_str(&paint_with_style(&self.cfg.grep_line_number_style,&num,None));
            painted.push('='); plain.push_str(&num); plain.push('=');
        }
        let code_seg=format!("{} ",gl.code);
        plain.push_str(&code_seg);
        if style.fg==Fg::Syntax {
            let kind=syntax::kind_for_language(&syntax::language_name_for_path(&gl.file,&self.cfg.default_language));
            let mut st=SynState::Normal;
            let toks=syntax::tokenize_line(&code_seg,&kind,&mut st);
            let mut secs=Vec::new();
            for (text,cat) in toks { let sc=self.palette.map(|p|p.colors[cat].to_color(self.cfg.true_color)); secs.push(PaintSection{style:ConcreteStyle::from_style_resolved(style,sc),text}); }
            painted.push_str(&paint_sections_to_string(&secs));
        } else {
            painted.push_str(&paint_with_style(style,&code_seg,None));
        }
        // decoration
        let deco=&self.cfg.grep_header_decoration_style;
        // grep_header_decoration_style in Config currently defaults to hunk decoration even in ripgrep; reference default is none in ripgrep mode. Config didn't know output type at resolve time for JSON. Handle here:
        let effective_deco: Style = if self.cfg.grep_output_type.as_deref()==Some("ripgrep") && self.cfg.grep_header_decoration_style.orig.is_empty() {
            // This condition is imperfect; explicit ripgrep mode with no explicit grep header deco should be none. Our Config set orig from hunk deco string when defaulting, so behaviour for JSON is handled because emit_grep_header is called in classic only usually (ripgrep header path above calls this too). To approximate, if caller is ripgrep output, use a plain style.
            deco.clone()
        } else {deco.clone()};
        let lines=decorated_lines(&painted,&plain,&effective_deco,&self.cfg);
        for l in lines {self.emit(l);}
    }
    fn paint_grep_code(&self,gl:&GrepLine)->String{
        let kind=syntax::kind_for_language(&syntax::language_name_for_path(&gl.file,&self.cfg.default_language));
        // expand tabs and truncate? Grep code lines: reference expands tabs according to --tabs (observed whitespace tab expansion in diff; assume same)
        let code=truncate_chars(&expand_tabs(&gl.code,self.cfg.tabs),self.cfg.max_line_length);
        let mut st=SynState::Normal;
        let toks=if self.cfg.syntax_theme.is_none() {vec![(code.clone(),crate::syntax::CAT_PLAIN)]} else {syntax::tokenize_line(&code,&kind,&mut st)};
        // match ranges are char ranges in original code; after tab expansion offsets could shift if tabs before match - rare. Use ranges as char in expanded if no tab before, else approximate by mapping through original code chars.
        let mut per_char:Vec<(char,usize)>=Vec::new();
        for (text,cat) in &toks {for c in text.chars() {per_char.push((c,*cat));}}
        if per_char.len()!=code.chars().count() {per_char=code.chars().map(|c|(c,crate::syntax::CAT_PLAIN)).collect();}
        let mut sections:Vec<PaintSection>=Vec::new();
        let mut i=0;
        while i<per_char.len() {
            let cat=per_char[i].1;
            let is_match=gl.match_ranges.iter().any(|(a,b)|i>=*a&&i<*b);
            let mut j=i+1;
            while j<per_char.len() && per_char[j].1==cat && gl.match_ranges.iter().any(|(a,b)|j>=*a&&j<*b)==is_match {j+=1;}
            let text:String=per_char[i..j].iter().map(|x|x.0).collect();
            let base_style = match gl.kind {
                GrepKind::Match=> if is_match {self.cfg.grep_match_word_style.clone()} else {self.cfg.grep_match_line_style.clone()},
                _=>self.cfg.grep_context_line_style.clone(),
            };
            let sc=self.palette.map(|p|p.colors[cat].to_color(self.cfg.true_color));
            sections.push(PaintSection{style:ConcreteStyle::from_style_resolved(&base_style,sc),text});
            i=j;
        }
        paint_sections_to_string(&sections)
    }
}
fn byte_to_char_idx(s:&str,byte:usize)->usize{
    let mut idx=0; for (bi,_) in s.char_indices() { if bi>=byte {return idx;} idx+=1; } idx
}
fn json_path_text(v:Option<&serde_json::Value>)->String{
    let Some(v)=v else {return String::new()};
    if let Some(t)=v.get("text").and_then(|x|x.as_str()) {return t.to_string();}
    if let Some(b)=v.get("bytes").and_then(|x|x.as_str()) {
        if let Some(bytes)=base64_decode(b) {return String::from_utf8_lossy(&bytes).to_string();}
    }
    if let Some(t)=v.as_str() {return t.to_string();}
    String::new()
}
fn base64_decode(s:&str)->Option<Vec<u8>>{
    // standard base64 without external crate
    let mut vals:Vec<u8>=Vec::new();
    for c in s.chars() {
        let v=match c {'A'..='Z'=>c as u8-b'A','a'..='z'=>c as u8-b'a'+26,'0'..='9'=>c as u8-b'0'+52,'+'=>62,'/'=>63,'='=>break,_=>continue};
        vals.push(v);
    }
    let mut out=Vec::new();
    for chunk in vals.chunks(4) {
        if chunk.len()>=2 {out.push((chunk[0]<<2)|(chunk[1]>>4));}
        if chunk.len()>=3 {out.push(((chunk[1]&15)<<4)|(chunk[2]>>2));}
        if chunk.len()>=4 {out.push(((chunk[2]&3)<<6)|chunk[3]);}
    }
    Some(out)
}
pub fn parse_classic_grep_line(raw_line:&str,stripped:&str)->Option<GrepLine>{
    // Match ranges from raw sections in code part are computed after parsing positions in stripped text.
    let chars:Vec<char>=stripped.chars().collect();
