            let file:String=chars[..pos].iter().collect();
            let code:String=chars[pos+1..].iter().collect();
            let gl=GrepLine{file,line_no:None,sep:'=',kind:GrepKind::Header,code,match_ranges:vec![]};
            return Some(gl);
        }
    }
