        let mut per_char:Vec<(char,usize)>=Vec::new();
        for (text,cat) in &toks {for c in text.chars() {per_char.push((c,*cat));}}
        if per_char.len()!=code.chars().count() {per_char=code.chars().map(|c|(c,crate::syntax::CAT_PLAIN)).collect();}
        let mut sections:Vec<PaintSection>=Vec::new();
        let mut i=0;
        while i<per_char.len() {
            let cat=per_char[i].1;
            let is_match=gl.match_ranges.iter().any(|(a,b)|i>=*a&&i<*b);
            let mut j=i+1;
            while j<per_char.len() && per_char[j].1==cat && gl.match_ranges.iter().any(|(a,b)|j>=*a&&j<*b)==is_match {j+=1;}
            let text:String=per_char[i..j].iter().map(|x|x.0).collect();
            let base_style = match gl.kind {
                GrepKind::Match=> if is_match {self.cfg.grep_match_word_style.clone()} else {self.cfg.grep_match_line_style.clone()},
                _=>self.cfg.grep_context_line_style.clone(),
            };
            let sc=self.palette.map(|p|p.colors[cat].to_color(self.cfg.true_color));
            sections.push(PaintSection{style:ConcreteStyle::from_style_resolved(&base_style,sc),text});
            i=j;
        }
        paint_sections_to_string(&sections)
    }
}
fn byte_to_char_idx(s:&str,byte:usize)->usize{
    let mut idx=0; for (bi,_) in s.char_indices() { if bi>=byte {return idx;} idx+=1; } idx
}
fn json_path_text(v:Option<&serde_json::Value>)->String{
    let Some(v)=v else {return String::new()};
    if let Some(t)=v.get("text").and_then(|x|x.as_str()) {return t.to_string();}
    if let Some(b)=v.get("bytes").and_then(|x|x.as_str()) {
        if let Some(bytes)=base64_decode(b) {return String::from_utf8_lossy(&bytes).to_string();}
    }
    if let Some(t)=v.as_str() {return t.to_string();}
    String::new()
}
fn base64_decode(s:&str)->Option<Vec<u8>>{
    // standard base64 without external crate
    let mut vals:Vec<u8>=Vec::new();
    for c in s.chars() {
        let v=match c {'A'..='Z'=>c as u8-b'A','a'..='z'=>c as u8-b'a'+26,'0'..='9'=>c as u8-b'0'+52,'+'=>62,'/'=>63,'='=>break,_=>continue};
        vals.push(v);
    }
    let mut out=Vec::new();
    for chunk in vals.chunks(4) {
        if chunk.len()>=2 {out.push((chunk[0]<<2)|(chunk[1]>>4));}
        if chunk.len()>=3 {out.push(((chunk[1]&15)<<4)|(chunk[2]>>2));}
        if chunk.len()>=4 {out.push(((chunk[2]&3)<<6)|chunk[3]);}
    }
    Some(out)
}
pub fn parse_classic_grep_line(raw_line:&str,stripped:&str)->Option<GrepLine>{
    // Match ranges from raw sections in code part are computed after parsing positions in stripped text.
    let chars:Vec<char>=stripped.chars().collect();
    // Try line-number parse
    if let Some(gl)=try_parse_grep_with_line_number(&chars) {
        return Some(fill_grep_match_ranges(gl,raw_line,stripped));
    }
    // Header without line number: path '=' code (path cannot contain ':'; find first '=')
    if let Some(pos)=chars.iter().position(|c|*c=='=') {
        if pos>=2 && !chars[..pos].contains(&':') {
            let file:String=chars[..pos].iter().collect();
            let code:String=chars[pos+1..].iter().collect();
            let gl=GrepLine{file,line_no:None,sep:'=',kind:GrepKind::Header,code,match_ranges:vec![]};
            return Some(gl);
        }
    }
    // Without line number: first ':' or '-' as separator, path len>=2 and path does not contain ':' (by construction)
    // Reference: separator could be ':' (match) or '-' (context). Find first ':' first? For f.txt-10:code case first '-' (in f.txt? no hyphen) - our algorithm: find earliest occurrence of either ':' or '-' at pos>=2.
    let mut first:Option<(usize,char)>=None;
    for i in 2..chars.len() { if chars[i]==':'||chars[i]=='-' {first=Some((i,chars[i])); break;} }
    if let Some((pos,sep))=first {
        let file:String=chars[..pos].iter().collect();
        if file.contains(':') {return None;}
        let code:String=chars[pos+1..].iter().collect();
        let kind=if sep==':' {GrepKind::Match} else {GrepKind::Context};
        let gl=GrepLine{file,line_no:None,sep,kind,code,match_ranges:vec![]};
        return Some(fill_grep_match_ranges(gl,raw_line,stripped));
    }
    None
}
fn try_parse_grep_with_line_number(chars:&[char])->Option<GrepLine>{
    // Iterate potential delimiter positions in order; path prefix must not contain ':'
    for i in 2..chars.len() {
        let sep=chars[i];
        if sep!=':'&&sep!='-'&&sep!='=' {continue;}
        if chars[..i].contains(&':') { 
            // If sep is ':' this i is first colon so prefix has none - contradiction means a later colon, skip all remaining? A later potential delimiter would also have colon in prefix, so no line-number parse.
            if sep==':' {continue;} else {continue;}
        }
        // parse digits after
        let mut j=i+1; let start=j;
        while j<chars.len() && chars[j].is_ascii_digit() {j+=1;}
        if j==start {continue;}
        if j>=chars.len() || chars[j]!=sep {continue;}
        let line_no:usize=chars[start..j].iter().collect::<String>().parse().ok()?;
        let file:String=chars[..i].iter().collect();
        let code:String=chars[j+1..].iter().collect();
        let kind=match sep {':'=>GrepKind::Match,'-'=>GrepKind::Context,'='=>GrepKind::Header,_=>GrepKind::Match};
        return Some(GrepLine{file,line_no:Some(line_no),sep,kind,code,match_ranges:vec![]});
    }
    None
}
fn fill_grep_match_ranges(mut gl:GrepLine,raw_line:&str,stripped:&str)->GrepLine{
    if gl.kind!=GrepKind::Match {return gl;}
    // Find code start char index in stripped
    let code_start = stripped.chars().count() - gl.code.chars().count();
    let secs=ansi::parse_sections(raw_line,false);
    let mut pos=0usize;
    for sec in secs {
        let len=sec.text.chars().count();
        let sec_start=pos; let sec_end=pos+len;
        if sec_end>code_start {
            let is_match_style = sec.style.bold && sec.style.fg==Fg::Color(Color::Ansi(1));
            if is_match_style {
                let a=sec_start.max(code_start)-code_start; let b=sec_end-code_start;
                if b>a {gl.match_ranges.push((a,b));}
            }
        }
        pos=sec_end;
    }
    gl
}
