#[derive(Clone,Debug,PartialEq,Eq)]
pub enum LineOp { Pair(usize,usize), Delete(usize), Insert(usize) }
pub fn align_line_sequences(minus:&[String],plus:&[String],word_regex:&Regex,max_distance:f64)->Vec<LineOp>{
    let n=minus.len(); let m=plus.len();
    let mtoks:Vec<Vec<Token>>=minus.iter().map(|l|tokenize(l,word_regex)).collect();
    let ptoks:Vec<Vec<Token>>=plus.iter().map(|l|tokenize(l,word_regex)).collect();
    let mut dist=vec![vec![1.0;m];n];
    for i in 0..n {for j in 0..m {let ops=align_tokens(&mtoks[i],&ptoks[j]); dist[i][j]=compute_distance(&mtoks[i],&ptoks[j],&ops);}}
    align_line_sequences_with_dist(&dist,max_distance)
}
pub fn align_line_sequences_with_dist(dist:&[Vec<f64>],max_distance:f64)->Vec<LineOp>{
    let n=dist.len(); let m=if n>0 {dist[0].len()} else {0};
    let inf=f64::INFINITY;
    let mut dp=vec![vec![inf;m+1];n+1]; dp[n][m]=0.0;
    for i in (0..=n).rev() { for j in (0..=m).rev() {
        if i==n&&j==m {continue;}
        let mut best=inf;
        if i<n&&j<m&&dist[i][j]<=max_distance {best=best.min(dist[i][j]+dp[i+1][j+1]);}
        if i<n {best=best.min(1.0+dp[i+1][j]);}
        if j<m {best=best.min(1.0+dp[i][j+1]);}
        dp[i][j]=best;
    }}
    let mut ops=Vec::new(); let mut i=0; let mut j=0;
    while i<n||j<m {
        if i<n&&j<m&&dist[i][j]<=max_distance && (dist[i][j]+dp[i+1][j+1]<=dp[i][j]+1e-12) {ops.push(LineOp::Pair(i,j)); i+=1;j+=1;}
        else if i<n && (j>=m || 1.0+dp[i+1][j]<=dp[i][j]+1e-12) {ops.push(LineOp::Delete(i)); i+=1;}
        else if j<m {ops.push(LineOp::Insert(j)); j+=1;}
        else if i<n {ops.push(LineOp::Delete(i)); i+=1;}
    }
    ops
}
RS
"}

