impl Delta {
    pub fn paint_side_by_side_block(&mut self,minus:&[CodeLine],plus:&[CodeLine])->Vec<String>{
        let mcodes:Vec<String>=minus.iter().map(|l|l.code.clone()).collect();
        let pcodes:Vec<String>=plus.iter().map(|l|l.code.clone()).collect();
        let ops=align::align_line_sequences(&mcodes,&pcodes,&self.cfg.word_diff_regex,self.cfg.max_line_distance);
        // emph maps for paired
        let mut me:HashMap<usize,Vec<bool>>=HashMap::new(); let mut pe:HashMap<usize,Vec<bool>>=HashMap::new();
        for op in &ops { if let align::LineOp::Pair(i,j)=op { let (_d,at,bt,tops)=align::distance_and_ops(&mcodes[*i],&pcodes[*j],&self.cfg.word_diff_regex); let (a,b)=align::emph_ranges(&at,&bt,&tops); me.insert(*i,tokens_to_char_bool(&at,&a,mcodes[*i].chars().count())); pe.insert(*j,tokens_to_char_bool(&bt,&b,pcodes[*j].chars().count())); } }
        let mut rows_str:Vec<String>=Vec::new();
        for op in ops {
            match op {
                align::LineOp::Pair(i,j)=>{
                    let le=me.get(&i).cloned().unwrap_or_default(); let re=pe.get(&j).cloned().unwrap_or_default();
                    rows_str.extend(self.sbs_rows(Some((&minus[i],Some((le,true)))) , Some((&plus[j],Some((re,true))))));
                }
                align::LineOp::Delete(i)=>{ rows_str.extend(self.sbs_rows(Some((&minus[i],None)),None)); }
                align::LineOp::Insert(j)=>{ rows_str.extend(self.sbs_rows(None,Some((&plus[j],None)))); }
            }
        }
        rows_str
    }
    pub fn paint_side_by_side_zero(&mut self,line:&CodeLine)->Vec<String>{
        self.sbs_rows(Some((line,None)),Some((line,None)))
    }
    fn sbs_rows(&self,left:Option<(&CodeLine,Option<(Vec<bool>,bool)>)>,right:Option<(&CodeLine,Option<(Vec<bool>,bool)>)>)->Vec<String>{
        let total_width=self.cfg.available_width;
        let left_panel_width=total_width/2;
        let right_panel_width=total_width-left_panel_width;
        // Compute code area widths based on line number formats (formatted widths are fixed in typical use; compute using a dummy line with numbers of representative width from actual line)
        let left_frags = match left {Some((l,e))=>self.wrap_code_line(l,e,left_panel_width,true),None=>vec![Vec::new()]};
        let right_frags = match right {Some((l,e))=>self.wrap_code_line(l,e,right_panel_width,false),None=>vec![Vec::new()]};
        let nrows=std::cmp::max(left_frags.len(),right_frags.len());
        let mut out=Vec::new();
        for row in 0..nrows {
            let ltxt=self.sbs_panel(left.map(|x|x.0),left_frags.get(row),left_panel_width,true,row);
            let rtxt=self.sbs_panel(right.map(|x|x.0),right_frags.get(row),right_panel_width,false,row);
            // ltxt already padded to left_panel_width visually inside sbs_panel
            out.push(format!("{}{}",ltxt,rtxt));
        }
        out
    }
    fn line_number_plain_width(&self,line:&CodeLine,is_left:bool)->usize{
        if !self.cfg.line_numbers {return 0;}
        let fmt=if is_left {&self.cfg.line_numbers_left_format} else {&self.cfg.line_numbers_right_format};
        let mut secs:Vec<PaintSection>=Vec::new();
        self.add_one_line_number_column(&mut secs,fmt,if is_left {&self.cfg.line_numbers_left_style} else {&self.cfg.line_numbers_right_style},line,is_left);
        secs.iter().map(|s|display_width(&s.text)).sum()
    }
    // Wrap a code line into fragments; each fragment is Vec<PaintSection> for code only (no line numbers)
    fn wrap_code_line(&self,line:&CodeLine,emph:Option<(Vec<bool>,bool)>,panel_width:usize,is_left:bool)->Vec<Vec<PaintSection>>{
        let lnw=self.line_number_plain_width(line,is_left);
        let code_width=panel_width.saturating_sub(lnw).max(1);
        // Build per-char sections for code
        let mut code_secs:Vec<PaintSection>=Vec::new();
        // Use a clone line without marker inclusion determined by append_code_sections (marker handled if keep; in sbs marker counts in code width)
        self.append_code_sections(line,emph,&mut code_secs);
        // Convert to per-char
        #[derive(Clone)] struct Ch {c:char,style:ConcreteStyle}
        let mut chars:Vec<Ch>=Vec::new();
        for sec in code_secs { for c in sec.text.chars() {chars.push(Ch{c,style:sec.style.clone()});} }
        let total_w:usize=chars.iter().map(|ch|unicode_width::UnicodeWidthChar::width(ch.c).unwrap_or(0)).sum();
        let mut frags:Vec<Vec<PaintSection>>=Vec::new();
        if total_w<=code_width {
            frags.push(chars_to_sections(&chars));
            return frags;
        }
        let max_wraps=self.cfg.wrap_max_lines.as_usize();
        if max_wraps==0 {
            // truncate to code_width
            let mut taken:Vec<Ch>=Vec::new(); let mut w=0;
            for ch in chars { let cw=unicode_width::UnicodeWidthChar::width(ch.c).unwrap_or(0); if w+cw>code_width {break;} w+=cw; taken.push(ch); }
            frags.push(chars_to_sections(&taken));
            return frags;
        }
        let hint_style=ConcreteStyle::from_style_resolved(&self.cfg.inline_hint_style,None);
        let mut remaining=chars;
        let mut wraps_done=0usize;
        loop {
            let rem_w:usize=remaining.iter().map(|ch|unicode_width::UnicodeWidthChar::width(ch.c).unwrap_or(0)).sum();
            if rem_w<=code_width {
                frags.push(chars_to_sections(&remaining)); break;
            }
            if wraps_done>=max_wraps {
