            while idx<remaining.len() { let cw=unicode_width::UnicodeWidthChar::width(remaining[idx].c).unwrap_or(0); if w+cw>cap {break;} w+=cw; taken.push(remaining[idx].clone()); idx+=1; }
            let rest:Vec<Ch>=remaining[idx..].to_vec();
            let rest_w:usize=rest.iter().map(|ch|unicode_width::UnicodeWidthChar::width(ch.c).unwrap_or(0)).sum();
            let right_align = rest_w<=code_width && (rest_w as f64 *100.0 / code_width.max(1) as f64) < self.cfg.wrap_right_percent;
            let symbol=if right_align {&self.cfg.wrap_right_symbol} else {&self.cfg.wrap_left_symbol};
            let mut frag=chars_to_sections(&taken);
            // pad frag to cap with spaces in last style? Reference wrap symbol is at end of line (right edge). If taken width < cap due wide char, spaces will be added by panel padding before symbol? We place symbol immediately after taken; panel padding will be after it unless we internal-pad here. Instead add spaces section to push symbol to right edge with style of last char/base.
            if w<cap {
                let pad_style=taken.last().map(|c|c.style.clone()).unwrap_or_else(ConcreteStyle::plain);
                frag.push(PaintSection{style:pad_style,text:" ".repeat(cap-w)});
            }
            frag.push(PaintSection{style:hint_style.clone(),text:symbol.clone()});
            frags.push(frag);
            wraps_done+=1;
            if right_align {
                // Next (final) fragment right-aligned: prefix symbol + spaces
                let mut frag2:Vec<PaintSection>=Vec::new();
                frag2.push(PaintSection{style:hint_style.clone(),text:self.cfg.wrap_right_prefix_symbol.clone()});
                let prefix_w=display_width(&self.cfg.wrap_right_prefix_symbol);
                let spaces=code_width.saturating_sub(prefix_w+rest_w);
                // spaces are plain (or with first rest style background?) Use first rest style
                let sp_style=rest.first().map(|c|c.style.clone()).unwrap_or_else(ConcreteStyle::plain);
                if spaces>0 {frag2.push(PaintSection{style:sp_style,text:" ".repeat(spaces)});}
                frag2.extend(chars_to_sections(&rest));
                frags.push(frag2);
                break;
            } else {
                remaining=rest;
            }
        }
        frags
    }
    fn sbs_panel(&self,line:Option<&CodeLine>,frag:Option<&Vec<PaintSection>>,panel_width:usize,is_left:bool,row_idx:usize)->String{
        let mut sections:Vec<PaintSection>=Vec::new();
        if self.cfg.line_numbers {
            if let Some(l)=line {
                let fmt=if is_left {&self.cfg.line_numbers_left_format} else {&self.cfg.line_numbers_right_format};
                let col_style=if is_left {&self.cfg.line_numbers_left_style} else {&self.cfg.line_numbers_right_style};
                if row_idx==0 {
                    self.add_one_line_number_column(&mut sections,fmt,col_style,l,is_left);
                } else {
                    let mut blank=l.clone(); blank.minus_no=None; blank.plus_no=None;
                    self.add_one_line_number_column(&mut sections,fmt,col_style,&blank,is_left);
                }
            } else {
                // blank panel line numbers: construct dummy line
                let dummy=CodeLine{raw:String::new(),stripped:String::new(),marker:String::new(),code:String::new(),ty:if is_left {LineType::Minus} else {LineType::Plus},minus_no:None,plus_no:None,syntax:vec![],raw_code_sections:None,mapped_sections:None,is_raw:false,combined:false};
                let fmt=if is_left {&self.cfg.line_numbers_left_format} else {&self.cfg.line_numbers_right_format};
                let col_style=if is_left {&self.cfg.line_numbers_left_style} else {&self.cfg.line_numbers_right_style};
                self.add_one_line_number_column(&mut sections,fmt,col_style,&dummy,is_left);
            }
        }
        if let Some(f)=frag { for s in f {sections.push(s.clone());} }
        let plain_w:usize=sections.iter().map(|s|display_width(&s.text)).sum();
        let mut out=paint_sections_to_string(&sections);
        // Fill/pad to panel width
        if is_left {
            if plain_w<panel_width {
                // If line has bg and line-fill-method=spaces, pad spaces should be painted with bg. Reference left panel padding for minus/plus lines: spaces after code are part of bg fill in spaces mode; in ansi mode they may be plain spaces with bg via EL impossible mid-line. We'll pad with a bg-only painted space section if base style has bg, else plain spaces.
                if let Some(l)=line {
                    let base=self.base_style_for(l.ty,false);
                    if let Bg::Color(c)=base.bg {
                        // only pad with bg if this fragment belongs to a non-zero line (zero bg may be normal)
                        out.push_str(&format!("\x1b[{}m{}\x1b[0m",c.ansi_bg()," ".repeat(panel_width-plain_w)));
                    } else { out.push_str(&" ".repeat(panel_width-plain_w)); }
                } else { out.push_str(&" ".repeat(panel_width-plain_w)); }
            }
        } else {
            // right panel
            if let Some(l)=line {
                let base=self.base_style_for(l.ty,false);
                if let Bg::Color(c)=base.bg {
                    if self.cfg.line_fill_method=="spaces" {
                        if plain_w<panel_width { out.push_str(&format!("\x1b[{}m{}\x1b[0m",c.ansi_bg()," ".repeat(panel_width-plain_w))); }
                    } else {
                        if !matches!(self.cfg.width_spec,WidthSpec::Variable) { out.push_str(&format!("\x1b[{}m\x1b[0K\x1b[0m",c.ansi_bg())); }
                    }
                }
            }
        }
        out
    }
}
fn chars_to_sections(chars:&[impl std::borrow::Borrow<(char,ConcreteStyle)>])->Vec<PaintSection>{
    // helper not used generically due Ch private type mismatch - see below
    let _=chars; Vec::new()
}
RS
