        if let Some(f)=&cfg.hyperlinks_commit_link_format { line(&mut o,"hyperlinks-commit-link-format",show_string(f)); }
    }
    line(&mut o,"inspect-raw-lines",cfg.inspect_raw_lines.to_string());
    line(&mut o,"keep-plus-minus-markers",cfg.keep_plus_minus_markers.to_string());
    line(&mut o,"line-numbers",cfg.line_numbers.to_string());
    if cfg.line_numbers {
        style_line(&mut o,"line-numbers-minus-style",&cfg.line_numbers_minus_style);
        style_line(&mut o,"line-numbers-zero-style",&cfg.line_numbers_zero_style);
        style_line(&mut o,"line-numbers-plus-style",&cfg.line_numbers_plus_style);
        style_line(&mut o,"line-numbers-left-style",&cfg.line_numbers_left_style);
        style_line(&mut o,"line-numbers-right-style",&cfg.line_numbers_right_style);
        line(&mut o,"line-numbers-left-format",show_string(&cfg.line_numbers_left_format));
        line(&mut o,"line-numbers-right-format",show_string(&cfg.line_numbers_right_format));
    }
    line(&mut o,"max-line-distance",format!("{}",cfg.max_line_distance));
    line(&mut o,"max-line-length",cfg.max_line_length.to_string());
    line(&mut o,"diff-stat-align-width",cfg.diff_stat_align_width.to_string());
    line(&mut o,"line-fill-method",cfg.line_fill_method.clone());
    line(&mut o,"navigate",cfg.navigate.to_string());
    match &cfg.navigate_regex_str {Some(s)=>line(&mut o,"navigate-regex",show_string(s)),None=>line(&mut o,"navigate-regex",String::new())}
    line(&mut o,"pager",cfg.pager.clone().unwrap_or_else(||"none".to_string()));
    line(&mut o,"paging",cfg.paging.clone());
    line(&mut o,"side-by-side",cfg.side_by_side.to_string());
    line(&mut o,"syntax-theme",cfg.syntax_theme_display.clone());
    line(&mut o,"width",match cfg.width_spec {WidthSpec::Fixed(n)=>n.to_string(),WidthSpec::Variable=>"variable".to_string()});
    line(&mut o,"tabs",cfg.tabs.to_string());
    line(&mut o,"word-diff-regex",show_string(&cfg.word_diff_regex_str));
    o
}
pub fn list_syntax_themes()->Vec<String>{
    SYNTAX_THEMES.iter().map(|(k,n)|format!("{}\t{}",k,n)).collect()
}
pub fn list_languages(cfg:&Config)->Vec<String>{
    // Format name in 26 char field, extensions each painted green. Wrap like bat: textwrap at a width. Observed wrap around 125 chars; determine from reference based on terminal width? In pipe it wrapped at 125. We implement wrapping with available width logic: bat's list_languages uses termwidth maybe 125? We'll implement wrap width = max(??) Use config.available_width but that is 80 in pipe, giving mismatch. The list from bat uses its own wrapping to terminal width detected separately (maybe stdout tty fallback 120?). We'll use a wrap limit of 125 to match captured pipe, but if terminal width is specified via --width, does it affect list? later test.
    let wrap_width=125usize;
    let mut out=Vec::new();
    for (name,exts) in LANGUAGES {
        let mut line_plain=format!("{:<26}",name);
        let mut line_painted=line_plain.clone();
        let mut first=true;
        for ext in *exts {
            let plain_piece=if first {ext.to_string()} else {format!(", {}",ext)};
            let painted_piece=if first {format!("\x1b[32m{}\x1b[0m",ext)} else {format!(", \x1b[32m{}\x1b[0m",ext)};
            // Bat wraps when adding next ext would exceed limit? Observed lines end with ", " and next line starts indent, meaning it first appends ext+sep for next and wrappoints at spaces in a textwrapper on painted string with width (?) It wraps at spaces after commas, leaving trailing comma+space at EOL (plain lengths 117 etc). Implement a token flow: We append pieces; if after appending a piece the plain length >= wrap_width, then break after adding its trailing ", " for next? Observed Apache line length117 and ends ", " - that piece was .HTACCESS, and next piece .htgroups would bring to ~128, so wrapper breaks before next piece but has already emitted separator? Their code may construct string exts joined ", " then textwrap with width 125 and subsequent indent, wrapping at the space after comma leaving trailing space.
            // Simpler algorithm to match: build full plain and painted pieces as tokens (ext painted + separator after it except last), then wrap tokens greedily: a line can include tokens while its plain len + token plain len <= wrap; if it would exceed, wrap before token but include previous token's separator in prior line.
            // We'll do wrapping in a second pass below instead of inline here (unused vars)
            let _=plain_piece; let _=painted_piece; first=false;
        }
        // Build token list where each token plain = ext + (", " if not last), painted accordingly (separator plain)
        #[derive(Clone)] struct Tok{plain:String,painted:String}
        let mut toks:Vec<Tok>=Vec::new();
        for (idx,ext) in exts.iter().enumerate() {
            let last=idx+1==exts.len();
            toks.push(Tok{plain:format!("{}{}",ext,if last {""} else {", "}),painted:format!("\x1b[32m{}\x1b[0m{}",ext,if last {""} else {", "})});
        }
        let mut cur_plain=line_plain.clone(); let mut cur_painted=line_painted.clone();
        for tok in toks {
            // If adding token exceeds wrap and current line has at least one ext (plain len > 26), wrap before it
            if display_width(&cur_plain)+display_width(&tok.plain)>wrap_width && display_width(&cur_plain)>26 {
                out.push(cur_painted);
                cur_plain=" ".repeat(26); cur_painted=" ".repeat(26);
            }
            cur_plain.push_str(&tok.plain); cur_painted.push_str(&tok.painted);
        }
        out.push(cur_painted);
        let _=cfg;
    }
    out
}
