cat > src/main.rs <<'RS'
mod align;
mod ansi;
mod config;
mod delta;
mod gitconfig;
mod languages;
mod csscolors;
mod opts;
mod paint;
mod process;
mod show;
mod style;
mod syntax;
mod themes_data;

use std::io::{self, BufRead, IsTerminal, Read, Write};
use std::process::ExitCode;
use crate::config::Config;

pub fn detected_light_mode()->Option<bool>{ None }

fn main()->ExitCode{
    match real_main() {
        Ok(code)=>ExitCode::from(code),
        Err(msg)=>{
            // Validation errors from Config already include trailing newline in many cases; if not, add one.
            if msg.starts_with("Error:") {
                eprint!("{}",msg);
                if !msg.ends_with('\n') {eprintln!();}
                return ExitCode::from(1);
            }
            eprint!("{}",msg);
            if !msg.ends_with('\n') {eprintln!();}
            ExitCode::from(2)
        }
    }
}
fn real_main()->Result<u8,String>{
    let args:Vec<std::ffi::OsString>=std::env::args_os().collect();
    let cmd=opts::build_command();
    let matches=match cmd.try_get_matches_from(&args) {
        Ok(m)=>m,
        Err(e)=>{
            use clap::error::ErrorKind;
            match e.kind() {
                ErrorKind::DisplayHelp|ErrorKind::DisplayHelpOnMissingArgumentOrSubcommand=>{
                    let long=is_long_help_requested(&args);
                    let text=if long {include_str!("help_long.txt")} else {include_str!("help_short.txt")};
                    let text=maybe_colorize_help(text);
                    print!("{}",text);
                    return Ok(0);
                }
                ErrorKind::DisplayVersion=>{
                    println!("delta 0.18.2"); return Ok(0);
                }
                _=>{
                    let mut rendered=e.render().ansi().to_string();
                    rendered=fix_clap_error(rendered,&args);
                    eprint!("{}",rendered);
                    return Ok(2);
                }
            }
        }
    };
    let raw=opts::RawOpts::from_matches(&matches);
    // dark/light CLI precheck for early modes
    // Full config creation also checks merged values.
    let term_width=terminal_width();
    let output_is_tty=io::stdout().is_terminal();
    // Generate completion: still needs config prechecks (dark/light, theme warning, width) as reference. We create config but ignore most style errors for these early modes by catching specific errors.
    // To keep behaviour for the common cases, create config first for all modes except completion/list where style errors should be ignored.
    let early_mode = raw.get("generate-completion").is_some() || raw.flag("list-languages") || raw.flag("list-syntax-themes") || raw.flag("parse-ansi");
    let cfg_result=Config::from_raw(raw.clone(),term_width,output_is_tty);
    let cfg=match cfg_result {
        Ok(c)=>c,
        Err(e)=>{
            if early_mode {
                // Width and dark/light errors should still be reported.
                if e.starts_with("Invalid value for width") || e.contains("cannot be used together") || e.starts_with("Invalid value for --true-color") || e.starts_with("Invalid value for --paging") {
                    return Err(e);
                }
                // Build a minimal config for early modes by using a sanitized raw (drop problematic style options) - simpler: construct with no-gitconfig and defaults via a cloned raw stripped of style/wrap/regex options.
                let mut clean=raw.clone();
                for spec in opts::SPECS {
                    if spec.long.ends_with("-style") || spec.long.contains("regex") || spec.long.starts_with("wrap-") || spec.long=="minus-style" {
                        clean.values.remove(spec.long);
                    }
                }
                clean.values.remove("wrap-right-percent"); clean.values.remove("wrap-max-lines");
                match Config::from_raw(clean,term_width,output_is_tty) {Ok(c)=>c,Err(e2)=>return Err(e2)}
            } else { return Err(e); }
        }
    };
    if let Some(w)=&cfg.bat_warning { eprint!("{}",w); }
    // Dispatch early modes in priority order
    if let Some(shell)=raw.get("generate-completion") {
        let text=match shell {
            "bash"=>include_str!("completions/bash.txt"),
            "elvish"=>include_str!("completions/elvish.txt"),
            "fish"=>include_str!("completions/fish.txt"),
            "powershell"=>include_str!("completions/powershell.txt"),
            "zsh"=>include_str!("completions/zsh.txt"),
            _=>"",
        };
        write_output_direct(text)?;
        return Ok(0);
    }
    if cfg.list_languages {
        return output_lines(show::list_languages(&cfg),&cfg);
    }
    if cfg.list_syntax_themes {
        return output_lines(show::list_syntax_themes(),&cfg);
    }
    if cfg.show_syntax_themes {
        let input=read_stdin_lines_if_not_tty();
        let lines=show::show_syntax_themes(&raw,&cfg,input,term_width,output_is_tty);
        return output_lines(lines,&cfg);
    }
    if cfg.show_themes {
        let input=read_stdin_lines_if_not_tty();
        match show::show_themes(&raw,&cfg,input,term_width,output_is_tty) {
            Ok(lines)=>return output_lines(lines,&cfg),
            Err(e)=>{ eprint!("{}",e); return Ok(2); }
        }
    }
    if cfg.show_colors {
        let lines=show::show_colors(&cfg);
        return output_lines(lines,&cfg);
    }
    if cfg.parse_ansi {
        let lines=read_stdin_lines();
        let out=show::parse_ansi_lines(&lines,&cfg);
        return output_lines(out,&cfg);
    }
    if cfg.show_config {
        return output_lines(show::show_config(&cfg),&cfg);
    }
    // Normal delta / two-file diff
    let mut err_code:u8=0;
    let lines:Vec<String> = if cfg.minus_file.is_some() && cfg.plus_file.is_some() {
        match diff_two_files(&cfg) {
            Ok((ls,code))=>{err_code=code; ls}
            Err(e)=>return Err(e),
        }
    } else {
        read_stdin_lines()
    };
    let calling=process::detect_calling_process();
    let mut d=delta::Delta::new(cfg.clone(),calling);
    d.run(&lines);
    let code=output_lines(d.out,&cfg)?;
    Ok(if err_code!=0 {err_code} else {code})
}

fn is_long_help_requested(args:&[std::ffi::OsString])->bool{
    for a in &args[1..] {
        let s=a.to_string_lossy();
        if s=="--" {break;}
        if s=="--help" {return true;}
        if s=="-h" {return false;}
        if s.starts_with('-') && !s.starts_with("--") && s.contains('h') {return true;}
    }
    true
}
fn maybe_colorize_help(text:&str)->String{
    if !io::stdout().is_terminal() {return text.to_string();}
    crate::show::colorize_help(text)
}
fn fix_clap_error(rendered:String,args:&[std::ffi::OsString])->String{
    // If error contains a similar argument tip for a normal option, reference renders a huge usage list.
    if rendered.contains("a similar argument exists") && !rendered.contains("--help\u{1b}") && !rendered.contains("--version") {
        // Determine if suggested argument is --help/--version by the tip text (strip ansi)
        let plain=crate::ansi::strip_ansi(&rendered);
        if plain.contains("a similar argument exists: '--help'") || plain.contains("a similar argument exists: '--version'") {
            return rendered;
        }
        let bin = args.get(0).map(|s|{
            let p=s.to_string_lossy().to_string();
            p.rsplit('/').next().unwrap_or(&p).to_string()
        }).unwrap_or_else(||"delta".to_string());
        // Replace the Usage line
        let mut out_lines:Vec<String>=Vec::new();
        for line in rendered.lines() {
            if crate::ansi::strip_ansi(line).starts_with("Usage:") {
                out_lines.push(opts::huge_usage(&bin));
            } else {out_lines.push(line.to_string());}
        }
        let mut s=out_lines.join("\n");
        if rendered.ends_with('\n') {s.push('\n');}
        return s;
    }
    rendered
}
fn terminal_width()->Option<usize>{
