fn shell_words_split(s:&str)->Vec<String>{
    let mut out=Vec::new(); let mut cur=String::new(); let mut chars=s.chars().peekable(); let mut in_s=false; let mut in_d=false;
    while let Some(c)=chars.next() {
        if in_s { if c=='\'' {in_s=false;} else {cur.push(c);} continue; }
        if in_d { if c=='"' {in_d=false;} else if c=='\\' { if let Some(n)=chars.next() {cur.push(n);} } else {cur.push(c);} continue; }
        match c {
            '\''=>in_s=true,
            '"'=>in_d=true,
            '\\'=>{ if let Some(n)=chars.next() {cur.push(n);} }
            c if c.is_whitespace()=>{ if !cur.is_empty() {out.push(std::mem::take(&mut cur));} }
            _=>cur.push(c),
        }
    }
    if !cur.is_empty() {out.push(cur);}
    out
}
fn diff_two_files(cfg:&Config)->Result<(Vec<String>,u8),String>{
    let minus=cfg.minus_file.clone().unwrap(); let plus=cfg.plus_file.clone().unwrap();
    // Reference behaviour: runs git diff --no-index --color -- <minus> <plus> plus diff_args, falling back to diff for process substitution.
    // Determine if either is a process substitution pipe (a FIFO / /dev/fd) or git fails due to... The reference fallback logic: try git; if git fails because paths are outside repo? git diff --no-index works for regular files.
    // Build git args: split cfg.diff_args by shell words.
    let extra=shell_words_split(&cfg.diff_args);
    let mut cmd=std::process::Command::new("git");
    cmd.arg("diff").arg("--no-index").arg("--color");
    for a in &extra {cmd.arg(a);}
    cmd.arg("--").arg(&minus).arg(&plus);
    match cmd.output() {
        Ok(out)=>{
            // git diff exits 1 if differences, 0 if same, >1 error
            if out.status.code().unwrap_or(1)>1 {
                // Check for process substitution fallback condition: if either path is /dev/fd or fifo, use diff -u
                let is_fd = minus.starts_with("/dev/fd/")||plus.starts_with("/dev/fd/")||minus.starts_with("/proc/self/fd/");
                if is_fd {
                    return diff_with_diff_tool(&minus,&plus,&extra);
                }
                let stderr=String::from_utf8_lossy(&out.stderr).trim_end().to_string();
                // git error prefix observed: "git diff: error: Could not access '<path>'"
                // git itself outputs "error: Could not access ..." to stderr; delta prefixes with "git diff: "
                let msg=if stderr.is_empty() {"git diff: error\n".to_string()} else {format!("git diff: {}\n",stderr)};
                eprint!("{}",msg);
                return Ok((Vec::new(),1));
            }
            let mut reader=io::Cursor::new(out.stdout);
            Ok((read_lines_from(&mut reader),0))
        }
        Err(_)=>{
            diff_with_diff_tool(&minus,&plus,&extra)
        }
    }
}
fn diff_with_diff_tool(minus:&str,plus:&str,extra:&[String])->Result<(Vec<String>,u8),String>{
    let mut cmd=std::process::Command::new("diff");
    cmd.arg("-u");
    for a in extra {cmd.arg(a);}
    cmd.arg(minus).arg(plus);
    match cmd.output() {
        Ok(out)=>{
            if out.status.code().unwrap_or(1)>1 {
                let stderr=String::from_utf8_lossy(&out.stderr);
                eprint!("{}",stderr);
                return Ok((Vec::new(),1));
            }
            let mut reader=io::Cursor::new(out.stdout);
            Ok((read_lines_from(&mut reader),0))
        }
        Err(e)=>Err(io_error_string(&e)),
    }
}
pub fn hyperlink_remote_url(hash:&str)->Option<String>{
    // Determine remote url from git config in cwd repo (origin) and convert to web commit url for supported hosts.
    // Use git config entries loaded via our gitconfig loader with a minimal RawOpts? Instead read repo .git/config directly via discover logic approximated: walk up from cwd.
    let mut dir=std::env::current_dir().ok()?;
    loop {
        let cfgpath=dir.join(".git").join("config");
        if cfgpath.exists() {
            if let Ok(content)=std::fs::read_to_string(&cfgpath) {
                if let Some(url)=parse_remote_url(&content) { return commit_url_from_remote(&url,hash); }
            }
            return None;
        }
        if !dir.pop() {return None;}
    }
}
fn parse_remote_url(content:&str)->Option<String>{
    let mut in_origin=false;
    for line in content.lines() {
        let t=line.trim();
        if t.starts_with('[') { in_origin = t.to_lowercase().starts_with("[remote \"origin\"]"); continue; }
        if in_origin {
            if let Some((k,v))=t.split_once('=') { if k.trim().to_lowercase()=="url" {return Some(v.trim().to_string());} }
        }
    }
    None
}
fn commit_url_from_remote(remote:&str,hash:&str)->Option<String>{
    // Convert ssh/https git remote to https base
    let mut s=remote.trim().to_string();
    if let Some(rest)=s.strip_suffix(".git") {s=rest.to_string();}
    // git@github.com:user/repo or ssh://git@github.com/user/repo
    let host_path:Option<(String,String)> = if let Some(idx)=s.find("://") {
        let rest=&s[idx+3..];
        let rest=rest.rsplit('@').next().unwrap_or(rest);
        let mut it=rest.splitn(2,'/'); Some((it.next()?.to_string(),it.next().unwrap_or("").to_string()))
    } else if s.contains('@') && s.contains(':') {
        let after_at=s.rsplit('@').next()?;
        let mut it=after_at.splitn(2,':'); Some((it.next()?.to_string(),it.next().unwrap_or("").to_string()))
    } else {None};
    let (host,path)=host_path?;
    let host_l=host.to_lowercase();
    let base=format!("https://{}/{}",host,path.trim_start_matches('/'));
    if host_l.contains("github") {Some(format!("{}/commit/{}",base,hash))}
    else if host_l.contains("gitlab") {Some(format!("{}/-/commit/{}",base,hash))}
    else if host_l.contains("sourcehut")||host_l.contains("git.sr.ht") {Some(format!("{}/commit/{}",base,hash))}
    else if host_l.contains("codeberg") {Some(format!("{}/commit/{}",base,hash))}
    else if host_l.contains("bitbucket") {Some(format!("{}/commits/{}",base,hash))}
    else {None}
}
