fn real_main()->Result<u8,String>{
    let args:Vec<std::ffi::OsString>=std::env::args_os().collect();
    let cmd=opts::build_command();
    let matches=match cmd.try_get_matches_from(&args) {
        Ok(m)=>m,
        Err(e)=>{
            use clap::error::ErrorKind;
            match e.kind() {
                ErrorKind::DisplayHelp|ErrorKind::DisplayHelpOnMissingArgumentOrSubcommand=>{
                    let long=is_long_help_requested(&args);
                    let text=if long {include_str!("help_long.txt")} else {include_str!("help_short.txt")};
                    let text=maybe_colorize_help(text);
                    print!("{}",text);
                    return Ok(0);
                }
                ErrorKind::DisplayVersion=>{
                    println!("delta 0.18.2"); return Ok(0);
                }
                _=>{
                    let mut rendered=e.render().ansi().to_string();
                    rendered=fix_clap_error(rendered,&args);
                    eprint!("{}",rendered);
                    return Ok(2);
                }
            }
        }
    };
    let raw=opts::RawOpts::from_matches(&matches);
    // dark/light CLI precheck for early modes
