fn fix_clap_error(rendered:String,args:&[std::ffi::OsString])->String{
    // If error contains a similar argument tip for a normal option, reference renders a huge usage list.
    if rendered.contains("a similar argument exists") && !rendered.contains("--help\u{1b}") && !rendered.contains("--version") {
        // Determine if suggested argument is --help/--version by the tip text (strip ansi)
        let plain=crate::ansi::strip_ansi(&rendered);
        if plain.contains("a similar argument exists: '--help'") || plain.contains("a similar argument exists: '--version'") {
            return rendered;
        }
        let bin = args.get(0).map(|s|{
            let p=s.to_string_lossy().to_string();
            p.rsplit('/').next().unwrap_or(&p).to_string()
        }).unwrap_or_else(||"delta".to_string());
        // Replace the Usage line
        let mut out_lines:Vec<String>=Vec::new();
        for line in rendered.lines() {
            if crate::ansi::strip_ansi(line).starts_with("Usage:") {
                out_lines.push(opts::huge_usage(&bin));
            } else {out_lines.push(line.to_string());}
        }
        let mut s=out_lines.join("\n");
        if rendered.ends_with('\n') {s.push('\n');}
        return s;
    }
    rendered
