pub fn show_themes(raw:&crate::opts::RawOpts,cfg:&Config,input:Vec<String>,term_width:Option<usize>,output_is_tty:bool)->Result<Vec<String>,String>{
    // A theme is a delta feature section that sets dark=true or light=true.
    let mut theme_names:Vec<(String,bool)>=Vec::new();
    for name in cfg.git_config.feature_names() {
        let dark=cfg.git_config.get("delta",Some(&name),"dark").and_then(|v|crate::gitconfig::parse_git_bool(v));
        let light=cfg.git_config.get("delta",Some(&name),"light").and_then(|v|crate::gitconfig::parse_git_bool(v));
        if light==Some(true) && dark!=Some(true) {theme_names.push((name,true));}
        else if dark==Some(true) {theme_names.push((name,false));}
    }
    theme_names.sort_by(|a,b|a.0.cmp(&b.0));
    // Filter by light_theme_filter if Some; if None show all? Reference with no gitconfig themes errors anyway.
    let filtered:Vec<(String,bool)>=theme_names.into_iter().filter(|(_,is_light)|{
        match cfg.light_theme_filter {Some(f)=>f==*is_light,None=>true}
    }).collect();
    if filtered.is_empty() {
        return Err("No themes found. Please see https://dandavison.github.io/delta/custom-themes.html.\n".to_string());
    }
    let demo=if input.is_empty() {crate::show::show_themes_demo_lines()} else {input};
    let mut out:Vec<String>=Vec::new();
    for (name,_is_light) in filtered {
        out.push(String::new()); out.push(String::new());
        out.push(format!("Theme: {}",name));
        out.push(String::new());
        let mut r=raw.clone();
        // Activate just this theme as a feature, replacing feature list, but keep user's main [delta] options (features in main are ignored if option in main - our Config handles features list from CLI value)
        r.values.insert("features".to_string(),name.clone());
        r.present.insert("features".into());
        r.flags.remove("show-themes");
        // Env DELTA_FEATURES handling in Config would override; tests with env are unlikely for show-themes. Leave as is.
        match Config::from_raw(r,term_width,output_is_tty) {
            Ok(mut c)=>{
                if let Some(w)=&c.bat_warning { eprint!("{}",w); c.bat_warning=None; }
                let mut d=crate::delta::Delta::new(c,crate::process::CallingProcess::Other);
                d.run(&demo);
                out.extend(d.out);
            }
            Err(e)=>{
                // If a theme's style is invalid (e.g. unknown syntax theme handled as warning not error) propagate? Reference shows warnings and continues; style errors in a theme would error out.
                return Err(e);
            }
        }
    }
    Ok(out)
}
