pub fn show_colors(cfg:&Config)->Vec<String>{
    use crate::csscolors::COLOR_GROUPS;
    use crate::syntax::{self,SynState,LangKind};
    let palette = cfg.syntax_theme.as_ref().and_then(|k|syntax::theme_palette(k));
    let kind=LangKind::JavaScript;
    let mut out:Vec<String>=Vec::new();
    let paint_code=|code:&str,bg:Option<crate::style::Color>| -> String {
        let mut st=SynState::Normal;
        let toks=syntax::tokenize_line(code,&kind,&mut st);
        let mut secs=Vec::new();
        for (text,cat) in toks {
            let mut style=crate::style::Style::default();
            style.fg=crate::style::Fg::Syntax;
            if let Some(c)=bg {style.bg=crate::style::Bg::Color(c);}
            let sc=palette.map(|p|p.colors[cat].to_color(cfg.true_color));
            secs.push(crate::paint::PaintSection{style:crate::paint::ConcreteStyle::from_style_resolved(&style,sc),text});
        }
        crate::paint::paint_sections_to_string(&secs)
    };
    for (group,items) in COLOR_GROUPS {
        out.push(String::new()); out.push(String::new());
        out.push(format!("\x1b[1m{}\x1b[0m",group));
        out.push(String::new());
        for (name,hex) in *items {
            let rgb=crate::style::parse_rgb_hex(hex).unwrap();
            let bgcol=if cfg.true_color {crate::style::Color::Rgb(rgb.0,rgb.1,rgb.2)} else {crate::style::Color::Fixed(crate::style::rgb_to_fixed(rgb))};
            out.push(paint_code("export function color(): string {{ return \"none\" }}",None));
            out.push(paint_code("export function hex(): string {{ return \"none\" }}",None));
            out.push(paint_code(&format!("export function color(): string {{ return \"{}\" }}",name),Some(bgcol)));
            out.push(paint_code(&format!("export function hex(): string {{ return \"{}\" }}",hex),Some(bgcol)));
        }
    }
    out
}
RS
