// Sections split at every escape sequence, not merged (for --parse-ansi)
pub fn parse_sections_unmerged(s:&str)->Vec<Section>{
    let mut sections:Vec<Section>=Vec::new();
    let mut cur=Style::default();
    let mut text=String::new();
    let mut it=s.chars().peekable();
    while let Some(ch)=it.next() {
        if ch=='\x1b' {
            if !text.is_empty() {sections.push(Section{text:std::mem::take(&mut text),style:cur.clone()});}
            match it.peek() {
                Some('[')=>{it.next(); let mut params=String::new(); let mut fin=' ';
                    while let Some(&c)=it.peek() {it.next(); if ('@'..='~').contains(&c) {fin=c;break;} else {params.push(c);}}
                    if fin=='m' {apply_sgr(&mut cur,&params,false);}
                }
                Some(']')=>{it.next(); let mut prev='\0'; while let Some(c)=it.next() {if c=='\x07' {break;} if prev=='\x1b'&&c=='\\' {break;} prev=c;}}
                Some(_)=>{let _=it.next();}
                None=>{}
            }
        } else {text.push(ch);}
    }
    if !text.is_empty() || sections.is_empty() {sections.push(Section{text,style:cur});}
    sections
}
