pub fn colorize_help(text:&str)->String{
    // Only called when stdout is a tty; reproduce clap styling for the static (80-col) help text.
    let mut out=String::new();
    for line in text.lines() {
        let mut l=line.to_string();
        if l=="Arguments:"||l=="Options:"||l=="Git config"||l=="Features"||l=="Styles"||l=="Colors"||l=="Line Numbers"||l=="Support" {
            l=format!("\x1b[1m\x1b[4m{}\x1b[0m",l);
        } else if l.starts_with("Usage: delta ") {
            l=l.replacen("Usage:","\x1b[1m\x1b[4mUsage:\x1b[0m",1).replacen(" delta "," \x1b[1mdelta\x1b[0m ",1);
        } else {
            // Bold option flags at line start-ish: clap bolds -x and --long tokens in the options list.
            // Apply to occurrences that look like an option start after leading spaces / comma.
            // Use a simple scan.
            let mut res=String::new(); let bytes:l;
            let mut i=0; let chars:Vec<char>=l.chars().collect();
            while i<chars.len() {
                // detect --word or -x at a word boundary in first 10 chars (<- option list area), and possible-value list items for detect-dark-light
                let at_start_area = i<12;
                if at_start_area && chars[i]=='-' {
                    if i+1<chars.len() && chars[i+1]=='-' {
                        let mut j=i+2; while j<chars.len() && (chars[j].is_ascii_alphanumeric()||chars[j]=='-' ) {j+=1;}
                        if j>i+2 {res.push_str("\x1b[1m"); res.extend(&chars[i..j]); res.push_str("\x1b[0m"); i=j; continue;}
                    } else if i+1<chars.len() && (chars[i+1].is_ascii_alphanumeric()||chars[i+1]=='@') {
                        res.push_str("\x1b[1m"); res.push(chars[i]); res.push(chars[i+1]); res.push_str("\x1b[0m"); i+=2; continue;
                    }
                }
                res.push(chars[i]); i+=1;
            }
            l=res;
            // detect-dark-light possible values list
            for v in ["auto","always","never"] {
                let pat=format!("- {}:",v);
                if l.contains(&pat) { l=l.replacen(&pat,&format!("- \x1b[1m{}\x1b[0m:",v),1); }
            }
            if l.contains("See the Colors section") { l=l.replacen("Colors","\x1b[4mColors\x1b[0m",1); }
        }
        out.push_str(&l); out.push('\n');
    }
    out
}

pub fn parse_ansi_lines(lines:&[String],_cfg:&Config)->Vec<String>{
    let mut out=Vec::new();
    for line in lines {
        let secs=crate::ansi::parse_sections_unmerged(line);
        let mut s=String::new();
        for sec in secs {
            if sec.text.is_empty() {continue;}
            let disp=sec.style.to_string();
            let painted_disp=paint_with_style(&sec.style,&disp,None);
            s.push('('); s.push_str(&painted_disp); s.push(')');
            s.push_str(&paint_with_style(&sec.style,&sec.text,None));
        }
        out.push(s);
    }
    out
}

