    let is_unexpected_value = plain.contains("unexpected value");
    if !is_unknown && !is_unexpected_value { return rendered; }
    // Suggested argument from tip
    let mut suggested:Option<String>=None;
    for line in plain.lines() {
        if let Some(idx)=line.find("a similar argument exists:") {
            let rest=&line[idx..];
            if let Some(s)=rest.split('\'').nth(1) { suggested=Some(s.to_string()); }
        }
    }
    let suggested_is_group = suggested.as_deref().map(|s|{
        let name=s.trim_start_matches('-');
        crate::opts::SPECS.iter().any(|sp|sp.long==name)
    }).unwrap_or(false);
    let prior_used = has_prior_group_arg_before_error(args);
    if !(prior_used || suggested_is_group) { return rendered; }
    let bin = args.get(0).map(|s|{let p=s.to_string_lossy().to_string(); p.rsplit('/').next().unwrap_or(&p).to_string()}).unwrap_or_else(||"delta".to_string());
    // Prefix flag for help/version suggestion or target
    let mut prefix_flag:Option<String>=None;
    if let Some(sug)=&suggested {
        if sug=="--help" || sug=="--version" { prefix_flag=Some(sug.clone()); }
    }
    if is_unexpected_value {
        // target is in first line: for '--help' or '--version'
        if plain.contains("for '--help'") { prefix_flag=Some("--help".to_string()); }
        if plain.contains("for '--version'") { prefix_flag=Some("--version".to_string()); }
    }
