    let mut out_lines:Vec<String>=Vec::new();
    for line in rendered.lines() {
        if crate::ansi::strip_ansi(line).starts_with("Usage:") { out_lines.push(huge.clone()); } else {out_lines.push(line.to_string());}
    }
    let mut s=out_lines.join("\\n");
    if rendered.ends_with('\\n') {s.push('\\n');}
    s
}
fn has_prior_group_arg_before_error(args:&[std::ffi::OsString])->bool{
    // Scan tokens; return true if a known grouped option appears successfully before an unknown/error token.
    let mut i=1;
    while i<args.len() {
        let s=args[i].to_string_lossy().to_string();
        if s=="--" {return false;}
        if s.starts_with("--") {
            let (name,has_eq)=match s[2..].split_once('=') {Some((a,_))=>(a.to_string(),true),None=>(s[2..].to_string(),false)};
            if name=="help"||name=="version" {return false;}
            let Some(spec)=crate::opts::SPECS.iter().find(|sp|sp.long==name) else {return i>1 && has_any_prior_option(args,i);};
            if spec.value_name.is_none() && has_eq {
                // This token itself is the error; prior if any option before it
                return has_any_prior_option(args,i);
            }
            if spec.value_name.is_some() && !has_eq { i+=1; } // consume value token in loop increment below (approx.)
            i+=1;
            // If this is the last token and no error follows, not relevant
            continue;
        }
        if s.starts_with('-') && s.len()>1 {
            // short cluster: check chars
            let mut is_error=false;
            for c in s[1..].chars() {
                if c=='h'||c=='V' {return has_any_prior_option(args,i);}
                let Some(spec)=crate::opts::SPECS.iter().find(|sp|sp.short==Some(c)) else {is_error=true; break;};
                if spec.value_name.is_some() {break;}
            }
            if is_error {return has_any_prior_option(args,i);}
            i+=1; continue;
        }
        // positional
        i+=1;
    }
    false
}
fn has_any_prior_option(args:&[std::ffi::OsString],before:usize)->bool{
    // Re-scan tokens before index for a known long/short option
    for a in &args[1..before] {
        let s=a.to_string_lossy();
        if s.starts_with("--") {
            let name=s[2..].split('=').next().unwrap_or("");
            if crate::opts::SPECS.iter().any(|sp|sp.long==name) {return true;}
        } else if s.starts_with('-') && s.len()>1 {
            for c in s[1..].chars() { if crate::opts::SPECS.iter().any(|sp|sp.short==Some(c)) {return true;} }
        }
    }
    false
}
