pub fn format_field_blame(value:&str, spec:&str)->String{
    // Blame placeholders default to width 15 if no width is specified.
    if spec.is_empty() { return format_field(value,"<15"); }
    // Parse spec to see whether width digits are present after optional fill/align
    let chars:Vec<char>=spec.chars().collect();
    let mut idx=0;
    if chars.len()>=2 && ['<','^','>'].contains(&chars[1]) {idx=2;}
    else if !chars.is_empty() && ['<','^','>'].contains(&chars[0]) {idx=1;}
    if idx>=chars.len() || !chars[idx].is_ascii_digit() {
        let mut new_spec:Vec<char>=Vec::new();
        new_spec.extend_from_slice(&chars[..idx]);
        new_spec.push('1'); new_spec.push('5');
        new_spec.extend_from_slice(&chars[idx..]);
        return format_field(value,&new_spec.iter().collect::<String>());
    }
    format_field(value,spec)
}
