old_end=p.index('        let mut out=String::new();',old_start)
new_block='''        let apply_blame = |values:&HashMap<String,String>| -> String {
            let mut s=String::new();
            for seg in parse_format(&self.cfg.blame_format) {
                match seg { FmtSeg::Lit(x)=>s.push_str(&x), FmtSeg::Field(name,spec)=>s.push_str(&format_field_blame(values.get(&name).map(|x|x.as_str()).unwrap_or(""),&spec)) }
