                            } else {s.push_str(&field);}
                        } else {s.push_str(&field);}
                    }}
                }
                s
            } else { apply_blame(&values) }
        } else {
            let plain=apply_blame(&values);
            " ".repeat(display_width(&plain))
        };
'''
