{"command":"cat > /tmp/patch_rust2.py <<'PY'
p=open('src/syntax.rs').read()
# Revert Rust double quote special handling to original full placeholder split by restoring that block from current custom to full string.
start=p.index('            if *kind==LangKind::Rust && ch==\'"\' {')
end=p.index('            } else {\n                push(&mut out,substr(i,j),CAT_STRING);',start)
new='''            if *kind==LangKind::Rust && ch=='"' {
                let full:Vec<char>=chars[i..j].to_vec();
                let mut p0=0usize;
                let mut k=0usize;
                while k<full.len() {
                    if full[k]=='{' && (k+1>=full.len() || full[k+1]!='{') {
                        if k>p0 {push(&mut out,full[p0..k].iter().collect(),CAT_STRING);}
                        let mut depth=0usize; let mut e=k;
                        while e<full.len() {
                            if full[e]=='{' {depth+=1;}
                            if full[e]=='}' {depth-=1; if depth==0 {e+=1; break;}}
                            e+=1;
                        }
                        push(&mut out,full[k..e].iter().collect(),CAT_NUMBER);
                        p0=e; k=e; continue;
                    }
                    if full[k]=='{' && k+1<full.len() && full[k+1]=='{' {k+=2; continue;}
                    if full[k]=='}' && k+1<full.len() && full[k+1]=='}' {k+=2; continue;}
                    k+=1;
                }
                if p0<full.len() {push(&mut out,full[p0..].iter().collect(),CAT_STRING);}
'''
p=p[:start]+new+p[end:]
# Add expect_impl_name variable
p=p.replace('    let mut in_closure_params=false;','    let mut in_closure_params=false;\n    let mut expect_impl_name=false;')
# In identifier branch, insert support variants and impl handling.
# Insert after expect_class_name branch in cat chain
old='''            } else if expect_class_name {
                expect_class_name=false; if *kind==LangKind::Rust {CAT_FUNCTION} else {CAT_CLASS}'''
new='''            } else if expect_impl_name && generic_depth==0 && word.chars().next().map(|c|c.is_uppercase()).unwrap_or(false) {
                expect_impl_name=false; CAT_FUNCTION
            } else if expect_class_name {
                expect_class_name=false; if *kind==LangKind::Rust {CAT_FUNCTION} else {CAT_CLASS}'''
assert old in p; p=p.replace(old,new)
# When storage word impl, set expect_impl_name if line doesn't contain " for " as a word.
old2='''            } else if storage_words(kind).contains(&word.as_str()) {
                if (*kind==LangKind::Rust && matches!(word.as_str(),"fn"|"struct"|"enum"|"trait"|"type"|"mod")) || (*kind==LangKind::Go && word=="func") { expect_func_name=true; }'''
new2='''            } else if storage_words(kind).contains(&word.as_str()) {
                if *kind==LangKind::Rust && word=="impl" && !line.split_whitespace().any(|w|w=="for") { expect_impl_name=true; }
                if (*kind==LangKind::Rust && matches!(word.as_str(),"fn"|"struct"|"enum"|"trait"|"type"|"mod")) || (*kind==LangKind::Go && word=="func") { expect_func_name=true; }'''
assert old2 in p; p=p.replace(old2,new2)
# Type context comma removal
p=p.replace("let type_ctx = generic_depth>0 || matches!(prev_char,Some(':')|Some(',')|Some('('))", "let type_ctx = generic_depth>0 || matches!(prev_char,Some(':')|Some('(')) || chars[..i].iter().collect::<String>().trim_end().ends_with(\"->\")")
# Known enum variants before type_words: insert before type_words branch, but ordering with after_path: currently after_path is before type_words and returns Plain for Some after :: (desired for Option::Some) and for a standalone Some(, after_path false. Add branch right before type_words.
old3='''            } else if type_words(kind).contains(&word.as_str()) {'''
new3='''            } else if *kind==LangKind::Rust && ["Some","None","Ok","Err"].contains(&word.as_str()) {
                CAT_FUNCTION
            } else if type_words(kind).contains(&word.as_str()) {'''
assert old3 in p; p=p.replace(old3,new3,1)
# Closure pipe classify Plain when starting closure: Determine prev sig char in operator branch - simpler: if pipe is opening (in_closure_params currently false) classify Plain, closing also Plain; but bitwise OR single pipe would become plain if it toggles first time. Use condition: if previous nonspace char is '(' ',' '=' or in_closure_params is true, treat as closure punctuation.
old4='''            if *kind==LangKind::Rust && ch=='|' && !(i+1<n && chars[i+1]=='|') {
                push(&mut out,"|".to_string(),CAT_OPERATOR); i+=1; in_closure_params=!in_closure_params; after_dot=false; continue;
            }'''
new4='''            if *kind==LangKind::Rust && ch=='|' && !(i+1<n && chars[i+1]=='|') {
                let prev_nonspace=(0..i).rev().find(|&idx|!chars[idx].is_whitespace()).map(|idx|chars[idx]);
                let is_closure=in_closure_params || matches!(prev_nonspace,Some('(')|Some(',')|Some('='));
                if is_closure {
                    push(&mut out,"|".to_string(),CAT_PLAIN); i+=1; in_closure_params=!in_closure_params; after_dot=false; continue;
                }
            }'''
assert old4 in p; p=p.replace(old4,new4)
open('src/syntax.rs','w').write(p)
