{"command":"cat > /tmp/patch_syntax3.py <<'PY'
p=open('src/syntax.rs').read()
# Language exact matching heuristic
old='''    // exact filename / dotfile
    for (name,exts) in LANGUAGES {
        for e in *exts {
            if *e==base { return name.to_string(); }
        }
    }'''
new='''    // exact filename / dotfile (entries that are plain extensions should not match a whole filename)
    for (name,exts) in LANGUAGES {
        for e in *exts {
            if *e==base && (e.contains('.') || e.chars().any(|c|c.is_uppercase()||c=='_'||c=='-') || ["wscript","gyp","gypi","bazel"].contains(e)) { return name.to_string(); }
        }
    }'''
assert old in p; p=p.replace(old,new)
# Insert Rust capitalized support before type_words but after Some branch: currently Some branch immediately before type_words. Add another branch before Some? We'll insert before "} else if type_words" after Some branch.
old2='''            } else if type_words(kind).contains(&word.as_str()) {'''
new2='''            } else if *kind==LangKind::Rust && word.chars().next().map(|c|c.is_uppercase()).unwrap_or(false) && (generic_depth>0 || param_after_colon || prev_char==Some(':') || chars[..i].iter().collect::<String>().trim_end().ends_with("->")) {
                CAT_FUNCTION
            } else if type_words(kind).contains(&word.as_str()) {'''
assert old2 in p; p=p.replace(old2,new2,1)
# after_path support type return Function
p=p.replace('if type_words(kind).contains(&word.as_str()) && matches!(prev_char,Some(_)) && ["Self","String","Vec","Option","Result","Box"].contains(&word.as_str()) { CAT_TYPE } else { CAT_PLAIN }',
'if ["Self","String","Vec","Option","Result","Box","Some","None","Ok","Err"].contains(&word.as_str()) { CAT_FUNCTION } else { CAT_PLAIN }')
open('src/syntax.rs','w').write(p)
