import math,ast
levels=[0,95,135,175,215,255]
def lab(rgb):
 def f(c):
  c/=255; return c/12.92 if c<=.04045 else ((c+.055)/1.055)**2.4
 r,g,b=map(f,rgb); x=r*.4124+g*.3576+b*.1805; y=r*.2126+g*.7152+b*.0722; z=r*.0193+g*.1192+b*.9505
 x/=.95047; z/=1.08883
 def fx(t): return t**(1/3) if t>.008856 else 7.787*t+16/116
 x,y,z=fx(x),fx(y),fx(z); return (116*y-16,500*(x-y),200*(y-z))
TH=[36,115,155,195,235]
def q(c):
 for i,t in enumerate(TH):
  if c<t:return i
 return 5
def conv(rgb,qmode=None):
 idx=[q(c) for c in rgb]; ci=16+36*idx[0]+6*idx[1]+idx[2]; cv=tuple(levels[i] for i in idx)
 src=rgb
 if qmode=='5bit255': src=tuple(round((c>>3)*255/31) for c in rgb)
 if qmode=='5bit8': src=tuple((c>>3)<<3 for c in rgb)
 if qmode=='5bitrep': src=tuple(((c>>3)<<3)|((c>>3)>>2) for c in rgb) # replicate bits
 lum=.299*src[0]+.587*src[1]+.114*src[2]
 gi=min(range(24),key=lambda i:abs((8+10*i)-lum)); gv=(8+10*gi,)*3
 return ci if math.dist(lab(rgb),lab(cv))<=math.dist(lab(rgb),lab(gv)) else 232+gi

data=[]
for line in open('/tmp/probe/conv_data.txt'):
 s,e=line.rsplit(' ',1);data.append((ast.literal_eval(s),int(e)))
for mode in [None,'5bit255','5bit8','5bitrep']:
 print(mode,sum(conv(c,mode)==e for c,e in data), [(c,e,conv(c,mode)) for c,e in data if conv(c,mode)!=e][:10])
for mode in [None,'5bit255']:
 print(mode,conv((51,15,15),mode),conv((153,153,153),mode))
