new='''fn spawn_pager_and_write(pager_cmd_str:&str,text:&str,cfg:&Config)->io::Result<()>{
    if pager_cmd_str.trim().is_empty() {return Err(io::Error::new(io::ErrorKind::NotFound,"empty pager"));}
    let parts=shell_words_split(pager_cmd_str);
    if parts.is_empty() {return Err(io::Error::new(io::ErrorKind::NotFound,"empty pager"));}
    let prog=&parts[0];
    let is_less = std::path::Path::new(prog).file_stem().map(|s|s=="less").unwrap_or(false);
    let mut cmd=std::process::Command::new(prog);
    let mut args:Vec<String>=parts[1..].to_vec();
    if is_less {
        // Unicode / ANSI handling env vars set by bat/delta for less.
        cmd.env("LESSANSIENDCHARS","mK");
        cmd.env("LESSCHARSET","UTF-8");
        cmd.env("LESSUTFCHARDEF","E000-F8FF:p,F0000-FFFFD:p,100000-10FFFD:p");
        if args.is_empty() {
            let version=less_version(prog);
            args.push("--RAW-CONTROL-CHARS".to_string());
            let add_no_init = match version { Some(v)=>v<530, None=>true };
            if add_no_init {args.push("--no-init".to_string());}
        }
        if cfg.navigate {
            if let Some(path)=write_less_history_file(cfg) {
                cmd.env("LESSHISTFILE",path);
            }
        }
    }
    cmd.args(&args);
    cmd.stdin(std::process::Stdio::piped());
    let mut child=cmd.spawn()?;
    if let Some(mut inp)=child.stdin.take() {
        let _=inp.write_all(text.as_bytes());
    }
    let _=child.wait();
    Ok(())
}
fn less_version(prog:&str)->Option<u32>{
    let out=std::process::Command::new(prog).arg("--version").stdin(std::process::Stdio::null()).output().ok()?;
    let text = format!("{}{}",String::from_utf8_lossy(&out.stdout),String::from_utf8_lossy(&out.stderr));
    // Find "less <num>" on first line/anywhere
    for tok in text.split_whitespace() {
        // tokens after a 'less' token are handled by scanning pairs below
        let _=tok;
    }
    let words:Vec<&str>=text.split_whitespace().collect();
    for i in 0..words.len() {
        if words[i]=="less" {
            if let Some(v)=words.get(i+1) {
                let num: String = v.chars().take_while(|c|c.is_ascii_digit()).collect();
                if let Ok(n)=num.parse::<u32>() {return Some(n);}
            }
        }
    }
    None
}
fn write_less_history_file(cfg:&Config)->Option<std::path::PathBuf>{
    let home=crate::gitconfig::home_dir()?;
    let dir=home.join(".local").join("share").join("delta");
    if std::fs::create_dir_all(&dir).is_err() {return None;}
    let path=dir.join("lesshst");
    let regex=cfg.navigate_regex_str.clone().unwrap_or_default();
    let content=format!(".less-history-file:\\n.search\\n\\"{}\\n",regex);
    if std::fs::write(&path,&content).is_err() {return None;}
    Some(path)
}
